window.__D("text/imrei-bina/c003",{"p":[[1700400217,"להתבשל כי שינים טוחנות ומפרידות החלקי' שבו להוציא טעמו הרוחני אח\"כ ע\"י חיך הטועם שעולה למוח כמ\"ש במ\"א וזהו ענין לבון הלכתא שזהו לבון שיני' הנק' גירס' שמפרר לחלקים כמו חטים גרוסי' כו' כך הלומד בפה ומחלק לחלקי' כל דבר בפ\"ע ואח\"כ החיך יטעום אוכל שהוא החכמה הרוחני' שבדבר ה' זו הלכה ומחמת זה נתחזקו מוחין של הנשמה האלקי' ברוחניות יותר מהתחזקות אברי' שבה ע\"י גופו של הלכה שגורס ונכנס אח\"כ בתוך מעיו כמ\"ש ותורתך בתוך מעי שחיזוק זה אינו רק כמו חיזוק גשמי דלב ואברים ע\"י האכילה גשמי' (וכמו שאמ' דוק בבכי ותשכח בנגרי כך ע\"י הגירס' בדיוק ישכח חיזוק כח ההילוך של הנשמה בהשגת אלקות ממדרגה למדרגה כמ\"ש ילכו מחיל כו' כמו מג\"ע לג\"ע כו' וכמ\"ש בזהר בפי' למחכ' לו דדייק מילין דאורייתא כו' לפי שזהו בירור רוחני יותר מבקיבה כו') ולפי שנעוץ תחלתן בסופן וסופן כו' ע\"כ חיזוק הרגל תלוי בגרסא שבשיני' דוקא) וזהו כי לא על הלחם לבדו מצד עצמו יחי' האדם במוחי' חדשים כ\"א על כל מוצא פי ה' שבלחם שהוא בחי' הרוחניות דח\"ע שאוכל גי' זן מזונא דחכמ' כו' והוא בחי' הטעמי' שבחכ' כמ\"ש טוב טעם ודעת למדני כו' שנק' מוצא פי' הוי' דחכמ' מאין כו' וזהו עיקר הלחם גי' מזלא כידוע ומבואר במ\"א והוא ענין התלמוד דוקא שנק' טעם דגן (אבל חטה כ\"ב אתוון דאורייתא היינו מקרא בעשי' ואחר כך משנה ותלמוד כמו האופה פת כו') ועם זה יובן שההכרה בדעת רוחני האלקי בנשמ' אינו בא רק ע\"י טעם דגן שהוא התלמוד דוקא כמו שע\"י הלחם הנטעם יחזק הרוחניות של המוחי' שבראש כנ\"ל (ולכך נשמות בג\"ע אין משיגי' אלקות רק ע\"י טעם תלמוד שלמדו בעוה\"ז דוק' כנ\"ל דורות הראשוני' שהכירו בדעת בלא לחמה של תורה הרי גם לאבות לא נגל' שמו העצמי וכמ\"ש ושמי הוי' לא כו' רק באל שדי שהוא בחי' המל' לכך הכירו הראשונים והוא שלא הכירו בבחי' עצמיו' כבן לאב לקרות אבא כמו כי אתה אבינו כי אברהם לא ידענו כו' והתורה שרשה בעצמיות המוחין וז\"ש ג' קשרין הן ישראל באוריית' כו' וכלך ע\"י טעם דגן דתלמוד הכירו ישראל דוק' לקרות אבא לבד ולא אמר שע\"י טעם דגן יהיה לו דעת לתינוק זולת זה משום דהא בהא תליא וד\"ל) וזהו ואספת דגנך הוא לחמה של תורה שהוא מזון עצמי לנפש האלקי' שידע לקרות אבא בבחי' עצמיות שלמעלה מן ההשג' של הראשונים משום דישראל עלו במח' כו' ואח\"כ אמר תירושך ויצהרך שהן בחי' יין ושמן פנימית ורזין דאוריית' כנ\"ל וההפרש בין פנימי' התורה לחצונית שבה שהוא מ\"ש אורייתא סתים וגליא הוא כמו שיש הפרש בין לחם ליין ושמן כו' (ומ\"ש בפ' שמע ודברת בם דקאי ג\"כ בתלמוד ומשנה שנק' תורה שבע\"פ כו' ובפ' והיה קורא לזה בשם מאכל טעם דגן היינו אך רק שבדבו' הוא כמ\"ש כי על כל מוצא פי וכו' למוצאיה' בפה ולא באכיל' הלחם מצד עצמו יחי' האדם כו' ובאמת ענין ואספת דגנך קאי בבחי' הברורי' דעה\"ד כו' ולכך אמרו דפסו' זה נאמר כשאין ישראל עושין כו' וכשישראל עושין רצונו של מקום נא' ועמדו זרים כו' ואפש' דלע\"ל יהי' עליות המדרגות ומאכל דגן דנשמות עכשיו יעשו זרים ונשמות יאכלו לויתן ושור הבר שהוא בחי' בירור שני כמ\"ש במ\"א ואכלתם אכול כו' והיינו כי על כל מוצא כו' ומ\"ש ויתן לך מטל כו' ורוב דגן וקאי לע\"ל כידוע מלאכתם זה נעשה ע\"י זרים) וכללות ההפרש הוא שהלחם צריך תיקון ובירור כמו הזריעה והטחינה ורקידה ואח\"כ לישה ואפי' ואם לאו אין בו טעם כלל וביין טעמו בא מיד שנסחט מן הענבים כו' וכמ\"ש במ\"א בענין אכלו רעים כו' וזהו ענין"],[1700400218,"ההפרש בין לחמה של תורה בחי' גליא שהוא בחי' הברורים דרפ\"ח כו' להבדיל בין טמא לטהור כו' משא\"כ בחי' פנימית סתים דאורייתא כמ\"ש כי טובים דודיך מיין יינה של תורה כו' והן כמו רזין וסודות טעמי תורה (והוא טעם וסוד ה' שבכל הלכה שלמעלה מטעם פשוט שבתלמוד הנ\"ל):\n(נד) <b>והנה</b> מעתה יש להבין ההפרש בין יין ושמן שזהו תירושך ויצהרך דהנה מבואר במ\"א בביאור ענין מחלוקת ריב\"נ ורבנן בשמן שצף ע\"ג יין אם חיבור לטומאה דלחד איל להם חיבור זע\"ז לענין טומאה ולאידך יש להם חיבור זע\"ז לטומאה ולכאורה אין טעם כלל למחלוקת הזאת דהלא זהו הדבר הנראה בחוש אם השמן צף ע\"ג היין באופן שאין להם חיבור זע\"ז בתערוב' או אם יש להם חיבור בתערובו' דהיינו שאין השמן נבדל בכל החלקי' שבו כי ימצאו מעין דקות חלקיו ביין וכן מחלקי היין בשמן הרי יש להם חיבור ואם השמן נבדל לגמרי בכל חלקיו וצף ע\"ג היין ממש בלתי חיבור בכל שהוא ודאי אין להם חיבור (וגם אם בטעמו ולא בממשו אם ימצא טעם יין בשמן בפחות מס' או שמן ביין כגון בכלי הבלוע מן השמן שנתנו בו יין וכן להיפך) ובאמת מה שהשמן צף ע\"ג היין אינו על היין לבד אלא גם על המים וחלב ושאר משקין כי טבע השמן לעמוד למעלה ע\"ג כל משקין הגם שיערבוהו ויבלבלוהו עם המשקה כמה פעמי' יבא על מקומו למעלה בהבדלה גמורה כידוע וזהו היפך טבע השמן שנמשך ונבלע בכל דבר כמו במאכל ובגד דמפעפע בעומקק בטבעי יותר מכל משק' מצד שמנונית דשמן שטבע שמנונית לפעפע בעומק ודווקא שמנונית דשמן לבד אבל שומן בשר וחלב רותח הגם שמפעפעי' ג\"כ אבל לא כשמן ואמנם ע\"ג משקין עומד ואינו מתחבר גם בטעמו מלבד ממשו שהרי לא ימצא טעם שמן ביין לעולם (ואפשר טעם יין ימצא בשמן כי גם שהשמן צף אבל היין מתחבר בו אם היין למעלה רק כשהשמן למעלה הרי גם היין נבדל דאל\"כ יש חיבור מצד היין) ומכ\"ז יובן למעלה בפרטיות ענין ההפרש שבין חכמ' לבינה שהחכמה נק' שמן מפעפע שנמשך בכל דבר והוא בחי' המשכת החכמ' בכל הברואי' שבעולם עד שימצא גם בדומם כמו ושמן מחלמיש צור כידוע לבד במשקין כיין ומים שהחכמה נבדל ונק' קדש כו' וגם בטעמו מלבד ממשו וכידוע דהעונג שבחכמה מובדל בערך מעונג שבבינה שנק' יין או בחסד שנק' מים ולזה הטעמי' לפעמי' בכתר ולפעמי' בחכמה ולזה הכולל בע\"ח דפנימי' אבא הוא פנימי' ע\"י כו' אבל בטעם שבמאכל מתחבר מפני ששרש טעם האוכל בחכמ' (וכידוע דמשמני הארץ צומח כל תבואה וחלב ודבש ויין אינו תלוי בשמני הארץ כי אם בחום או לחלוחית טובים כו' כמו ארץ זבת חלב ודבש ארץ זית שמן כו' דמקומות הגדלים זיתים נבדל ממקומו' הגדילי' גפני' או שאר משקין) אבל אחר האור נמשך השמן וכמו שמן שבנר שנמשך אחר הפתילה להדליק מפני שהחכמה נק אור ושמן הוא בבחי' מקור חכמה שבא לידי גלוי אור כמ\"ש במ\"א בענין חכמת אדם תאיר פניו כו' (ונמצא עונג שבארת פנים אע\"פ שהוא בגלוי שרשו בהעלם העונג שבח\"ס ממש שהוא בחי' שמן שצף כו' ומה שנמשך מאין דחכמה ליש אין זה בא מפנימי' החכמ' שהוא בהעלם תמיד ונק' שכל הנעל' מכל רעיון שאינו בא לידי גלוי לעולם ונבדל תמיד כשמן שצף כו' ונק' קדש מלה בגרמי' אלא זהו רק בחי' חיצוניו' חכמ' כמשי\"ת) אך הנה יש להקדים ענין א' הנז' בזהר תמיד שיש ב' מדריגות ברזין דאוריית' א' נק' רזא סתם והב' נק' רזא דרזין ווהפרש לכאורה אינו מובן דרזא הוא סוד שאינו בא לידי גלוי לעולם וא\"כ מהו רזא דרזין (ולפ\"ז יש להבין ג\"כ"],[1700400219,"מ\"ש סתימו דכל סתימין אם פי' סתימין דלא אתגליין לעולם א\"כ מהו סדכ\"ס) אלא הענין הוא כידוע דבכל עולם יש ב' מדריגות דסתים וגליא העלם וגלוי ובהשתלשלו' בבחי' עו\"ע ודאי שמבחי' גלוי ההעלם שבעליון נעשה בחי' העלם לגבי התחתון כמו שמבחי' או\"פ שבעליון נעשה א\"מ לתחתון או ממל' שבעליון כתר לתחתון וכן להיפך ממקיף והעלם שבעלול נעשה א\"פ וגלוי בעילה שלו כו' ונמצא דגם שלגבי העלול נק' העלם ומקיף לגבי העילה המשפיע נק' גלוי וכענין לפניך נגלו כל תעלומות כו' וזה ג\"כ פי' סדכ\"ס דגם שנק' סתימין לגבי התחתונים העלולים ממנו נק' גלוי לבחי' העליון הימנו ולכך נק' סדכ\"ס וכך יתפרש בענין רזא דרזין דגם שנק' רז וסוד לגבי התחתון נק' גלוי לגבי העליון ולא בשם רזא כלל ע\"כ נק' בחי' העליון רזא דרזין (וכמו חכם הרזים שענינו שמגלה כל רזין דלפניו נגלה כל סוד משא\"כ לזולתו שהדבר הסתום נשאר בסוד ולא יבא על גלויו לעולם וזהו בהרכח שמדריגת חכם הזה הנק' חכם הרזים בבחי' מקור כל שכליים הללו הנק' רזים ע\"כ יבואו אצלו בגלוי וכמו כל רז לא אניס לי' כו' וכנ\"ל בפי' רזא דרזין וד\"ל אמנם אין זה מתיישב בענין סתום וגליא שבתורה דלגבי בחי' הנגלה ממש שבתור' אין הפרש בין רזא לרזא דרזין הנ\"ל מאחר שנק' גם הוא רז וסוד לגבי הנגלה ממש כו' ולגבי מקור הרזין שניה' נק' גלוי ושוין שם בחי' סתים וגליא כנ\"ל א\"כ בכללות ענין סתים וגליא דתורה אין תירוץ זה מתיישב להיות זה נק' רזא וזה רזא דרזין וד\"ל: והנה ביאור הדברי' הלא זהו בחי' יין ושמן שנק' תירוש ויצהר כי הנה ידוע שיש בטבע היין להוציא כל סוד הנעלם לגלוי דוקא לפי שעצם טבע היין הוא בחי' ההתגלו' שכאשר האדם טוב לבו ביין יגלה כל דבר מצפוני לבבו וגם מצד השמחה שביין יוציא כל סוד לגלוי אבין מעצור כלל לרוחו כי גם טבע השמחה לבא הכל בגלוי כידוע שבשמח' האדם יבא בגלוי לכל מכל אשר לו ברצון ושכל ומדות כו' לא יוכל להעלי' דבר וחצי דבר גם מכל פנימי' כחות נפשו אך יש להבין בב' דברי' הללו היין והשמח' למה יש להם כח זה להפך טבע הסו' שיב' לגלוי כמו שאמרו נכנס יין יצא סוד דמשמ' שכניס' היין מכרי' את הסוד להפך טבעו ולבא לגלוי (וכענין אגברו חמרי אדרדקי כו' דאנפי זטרי הן בחי' מוחין דקטנוק וכל שכל וחכמ' עמוק' נעלם מאד מהם ולא יבואו להם בגלוי כלל וגם אם מושג אצלם בסוד לא יוכלו להביא' בדיבור כלל אך כאשר תגבר היין על הדרדקי הללו יאמרו כל סודו' הנעלמי' אצלם וכן גם לזקן שקנ' חכמ' וסבא דעתי' סתים מאד בעמקו' גדול' בעומק והעלם אחר העלם מ\"מ יבא לידי גלוי רק שצריך להיות דוקא ע\"י יין ישן שדעת זקנים דוקא נוחה כו' שהוא מכריח גם לסוד דזקנים לגלותם וכמו יין המשומר שית' וד\"ל) וכמ\"ש במ\"א בענין כוס ישועות כו' כוסי רוי\"ה גי' רכ\"א בחי' אריך אנפין כו' שנק' אנפין רברבי זקן שקנה חכמה ולכך צריך יין המשומר בכוס של ברכה דלע\"ל כו') והנה לכאורה אם מטעם שהיין טבעו בבחי' גלוי דוק' א\"כ אדרבה איך יוכל להכריח היפוכו שהוא הסוד שיבא לגלוי אלא מוכרח לומר שיש ביין מטבע דבחי' ההעלם דוקא בגבורת כח חזק יותר עד שמכריח להסוד הנעל' לבא לגלוי דאל\"כ מאין ימצא בו כח זה להכריח את הדבר הסתום בטבעו שיצא חוץ לגדרו ואם יש בכחו לגבור עליו שיצא חוץ לטבעו ודאי מוכרח שגבוה ממנו וזהו מובן במה שאנו רואים במהות היין המשמח שתחלתו בהעלם גדול כי כחו החזק נעלם בו מאד ויוצא אא\"כ לגילוי וכנראה לעין גידול היין שהוא כמוס ונעלם בתוך הענבי' זמן רב ובתוך זמן עיכובו בהעל' בענבי' הולך ומתגב' בכחו שהרי ענבי' שלא"],[1700400220,"נתבשלו כ\"צ אין יינן חזק ויין המשומר בענביו הוא שעמד זמן רב או שעומד בענביו לחזק כחו ביותר (ומצד שנשקט על שמריו ונק' חמראדמנטר' דשקיט ושכיך כו' כחמר טב דיתיב על דורדיא כמ\"ש בזהר) לכך כח היין חזק מאד ביציאתו בסחיטה לגלוי להוציא כל סוד לשותין אותו וכל שכחו חזק יותר מצד התגברותו בהיותו בהעל' בענביו יותר יותר בכחו להוציא כל סוד (משא\"כ השמן שנסחט מן הזיתי' שאין עיכובו בזית מוסיף כחו בחיזוק כלל רק שעצור וכלא בזית בהעלם בשמנוני' וע\"י כתישת הזית יותר יבא לצלילת ושמנונית וכיתוש הראשון מוציא השמן המשובח יותר וצלול יותר כו') ולפ\"ז יובן דסיבת פעולת היין להוציא הסוד כמו דוגמת עצמו בהיותו בענביו בהעלם לבא לגלוי וכל עיכובו בהעעלם אינו רק בשביל גלויו וכך הוא ענין השמחה בגלוי דאם הטעם רק מצד שטבע השמחה לבא בהתגלות נגלות כו' למה יהיה כחה להתגבר על הסתום ונעלם ברצונו הפנימי לגלותו אין זה אלא מפני ששרש השמחה מגיע בעצם רוממות הנפש בתענוג הפשוט שכל סוד שם יגלה (מחמת שהתענוג שבא בשמח' הוא גלוי התפשטות עצמו' הנפש והסוד הוא בבחי' העלם וכיווץ בעצמות וההתפשטות שגובר על ההעלם והכיווץ מוכרח שגבוה ממנו ע\"כ יש בכחו להפוך טבע הסוד שיבא לגלוי] ולפ\"ז שרש היין והשמחה הוא בהעלם שאינו רק לבא לגלוי מאחר שהשמחה והיין מביאים כל העלם לגלוי ולכך נכנס יין יצא סוד בכלל כל כחות הנפש ובפרט כל דבר שברצון ושכל ומדות לא ישאר דבר וחצי דבר כידוע ואמנם מ\"מ יש הפרש בין יין ושמח' דהיין שרשו בהעלם כאשר היה כמוס בענביו רק שהוא בא לגלוי והשמח' שרשם בעצמו' שבא לידי גלוי שממילא לא יוכל להעלים כלל ולכך בניסול היין ע\"ז המזבח היו ב' דברים היין המנסכי' והשיר בשמחה משום דא\"א שירה אלא על היין כפי שאין שמחה אלא ביין דוקא לפי שהשמחה לבד אין בכחה לגבור בכח על הסוד שיצא כמו היין וגם היין הוא המשמח שמביא לידי שמחה שהוא גלוי העצמו' ממש ונק' יין המשמח אלקי' כו' (והשמח' צריך ליין מפני שהיין משמח כו' אבל היין א\"צ לשמח' דבלא שמח' היין משמח ומוציא סוד ואדרבה גם למרי נפש יין ישמחם וכמ\"ש תנו כו' ויין למרי נפש וכידוע בענין טעם ניסוך היין בשיתין להמתיק המרירו' דמ\"ת בוכין שבתהום רבה כו') אבל השמן טבעי להיפך שהוא נשאר בסתימו' וחשאי ולא יבא לגלוי לעולם וד\"ל:\n(נה) <b>ובזה</b> יובן ענין רזא ורזין דרזין הנ\"ל דהנה יין המשמח אלהי' הוא מ\"ש אם הבנים שמחה שהוא ענין השמח' והעונג המורגש בהשגה הנק' התבוננו' בגדולת אא\"ס ב\"ה וע\"ס דאצי' וכה\"ג ולמעלה היינו בחי' בינה דאצי' שהוא יין שבינה נק' יש כמו להנחיל אוהבי יש כנשמו' שנהנין מזיו כו' שמרגישין העונג האלהי בבחי' יש ממש ומזה באה השמחה העצומה בהגלות נגלות הכל כמו בדוד שא' ושחקתי לפני ה' וכתי' בי' מפזז ומכרכר בכל עוז כו' שזהו רק בחי' עוצם הגלוי עד שנבזה בעיני מיכל בהגלות נגלות כא' כו' (משא\"כ כמו ענין כריעו' והשתחווא' דר\"ע אע\"פ שזהו גלוי הנעלם אבל הגלוי עצמו בא בהעלם מחמת הביטול עצמי) כמו שאנו רואים בטרוד בעומק ענין גדול שיעשה ריבוי תנועות שונות בידיו וברגליו משא\"כ המשחק בשמחה וריקוד שבא בהתגלות כל עצמותו ממש והביטול הנגלה הנ\"ל היפך זה ממש שבא עוצם צד ביטול כל עצמותו עד שלא ירגיש עצמו כלל ויעשה שלא במתכוין ולא ידע גם אחר זמן מה שעשה בידיו וגופו כו' (וגם בשמחה גדולה ועצומה שבריקוד יוכל להיות כך מצד ביטול כל כחות נפשו דכלא חשיבי לגבי גלוי כל עצמותו ישכח ולא ירגיש כלל בעצמו מה שיעשה"],[1700400221,"בגופו כידוע וזה וזה באין באופן א' ובאמת ה' הפכי' הן ממש וד\"ל) ואמנם מבואר למעלה שגלוי זה הי' ודאי בסוד והעלם תחלה כמו שהוא באופן טבע הסוד שלא יוכל לבא לגלוי כלל רק ע\"י היין יצא סוד זה לגלוי והוא ע\"י השמח' שביין שנק' בינה הבא במורגש בהשגה הנ\"ל ומאין יש לו כח זה אם לא ששרשו בהעלם העצמו' בכח חזק יותר מטבע כח הסוד ע\"כ מכריח הסוד לבא חוץ מגדרו כו' ולכך יין גי' סוד ופעולתו להיפך להוציא כל סוד לגלוי מפני שיש ב' מיני סוד א' אשר בא לידי גלוי והוא הנק' רזא ובלה\"ק פלא כמו כי יפלא דבר כו' ונק' שכל הנעלם מכ\"ר או שכל הנפלא או תעלומ' חכמ' וכה\"ג אבל מפלא נעשה אלף לשון אוליפנא ולימוד שבא לגלוי עד שנעש' מאין יש בהשג' דבינ' כידוע דחו\"ב נק' תרין ריעין כו' שהחכמה נק' אין ונק' כח מה כלומ' מה פשפשת כו' בבחי' העלם ונפלא מכל רעיון והשגה לאדם ועכ\"ז נמשך הסוד ואין דכח מה זה לגלוי יש ממש בבינה כו' (וע\"ז נאמר והחכמ' מאין הנעלם תמצא לבחי' יש וכמו אאלפך חכמה הרי גם החכמה נק' בחי' לימוד כי האלפ פירושו לימוד וקאי על אלף דחכמה ג\"כ באמרו אאלפך חכמה כו' והוא כמו בחי' מזל ונוצר חסד שרש ומקור החכמה שנק' אין דחכמה וכך אמרו בס\"י הבן בחכמה וחכם בבינה וידוע דהבן בחכמה הוא בחי' ס\"ג דע\"ב שהוא מה שהעלם ומקור דחכמ' יוכל לבא לידי הבנה והסבר דבר מתוך דבר שנק' נבון והוא קוץ התחתון דיו\"ד שגדול במעלה מנקוד' דחכמה שהיא רק גלוי היש דאין דחכמה הנק' יסוד אבא כידוע בציור אלף וחכם בבינה הנק' עומק המושג בחי' אין הנעלם במושג וע\"ז אמ' אאלפך בינה מבחי' מזל ונקה שרש ומקור לכל ההשגה בעומק ותמצית הנק' אין דבינה כו' וגם הב' מזלו' הללו נקראו גלוי מבחי' המקו' הראשון שהו' הסתו' ונעל' באמ' שנק' רדל\"א כידוע בענין ג' רישין כו' ולפ\"ז בבחי' רדל\"א או הנק' ע\"י דע\"י או סדכ\"ס יש ב' מדריגו' א' הבא לגלוי עכ\"פ להיות שרש לשרש לחכמ' בינה שנק' אין ויש בגלוי הנ\"ל והב' אשר לא בא להיות גם בחי' מקור למקור ושרש לשרש למציא' דחו\"ב וזהו פי' הפשוט דבתמיה ממש קא' והחכמ' מאין כו') והב' בחי' סוד ממש שלא בא לידי גלוי לעולם כמו בעדן דכתי' בי' עין לא ראתה פי' עין דחכמ' שנק' אור מפני שנק' אור הגנוז לעולם שאין אור דחכמ' רואה בו (וגם פלאו' חכמ' הנק' ח\"ס הנ\"ל לא ישיגנו והוא שנק' סדכ\"ס או ע\"י דע\"י או רדל\"א כו' כנ\"ל) וכמו בדניאל דכתי' ואתה סתום וחתום כו' שאין קץ משיח בא בגלוי לעולם רק לזמן בואו לבד ולמעלה זהו הנק' רזא דרזין דגם בבחי' סתום שבתורה יש סוד ה' שנתגלה ליריאיו עכישו או עתידי' לבא בגלוי כמו ישקני מנשיקות כו' שהן טעמי וסודו' המצו' שיתגלו לע\"ל אבל רזא דרזין דאוריית' גם לע\"ל לא יתגלו כמו ואין זולתך לבדו כו' (וכפי' הפשוט והחכמ' מאין כלומר היכן מקומה לא נוגע ונגלה לעולם רק אלהי' הבין דרכה והוא ידע כו') וזהו הנק' סוד סתום שנשאר בסתימותו לעולם מצד עוצם עומקו כי עמוק עמוק הוא מי ימצאנו דהיינו הנק' עומק לעומק ויובן זה ע\"ד דוגמא ממה שאנו רואי' גם בשכל האנושי שיש שכל וחכמ' עמוקה נפלאה מכל רעיון שא\"א להכילה שום חכם גם היותר מופלג ועמוק בכל עמקי תעלומו' חכמ' לא יעמוד על סודה ועומקה לעולם כמו סוד פרה אדומ' שגם שלמה אמר אמרתי אחכמה והיא רחוקה ונפלא' מהשגתו לגמרי (וכה\"ג כמה טעמי מצות שלא יבואו לגלוי גם לעתיד שע\"ז א' במופלא ממך אל תדרוש כו') (אך מ\"ש אשר עשה עמכם להפליא הפלא ופלא שנק' פלא דפלא כמו עושה פלא אדון הנפלאות וכה\"ג וכן כימי כו' אראנו נפלאות תרין שהוא גלוי גם לסדכ\"ס כידוע וכן מ\"ש וא' ביום ההוא הנה אלקינו זה ממש דעין בעין יראו כו'"],[1700400222,"היינו מ\"ש אלקים זולתך יעשה למחכה לו כו' והוא בעוה\"ב שנא' להנחיל אוהבי יש גלוי העצמות דא\"ס ממש ואין זה נק' גלוי סוד כמו גלוי רזא דרזין כי לגבי בחי' העצמות לא יתכן לשון גלוי סוד או סוד דסוד שהרי א' אני ה' לא שניתי כלל והוא עכשיו כמו לע\"ל ממש בשוה כידוע] והנה יש בחי' ממוצע בין רזא לרזא דרזין והוא ששרשו ברזא דרזין עצמו רק שמ\"מ בא לידי גלוי אבל אין אופן גלויו כגלוי הסוד ממש רק כאופן גלוי הסוד הסתו' שאינו בא לידי גלוי לעול' ע\"כ בא באופן גלוי משונה דהיינו שאין הגלוי שלו בא בדיבור כלל רק ברמז או מבין מדעתו כי גם ברזא דרזין יש השגה קצת עכ\"פ כמו שמצינו בזהר וראיה ממ\"ש במופלא ממך אל תדרוש כו' ואם היה אור שכל המופלא הזה בלתי בא לעולם לגלוי השגה למה צריך להזהיר בל תדרוש אם לא יוכל לדרוש אותו מן ההעלם לגלוי כלל אלא ודאי שיוכל לבא בהשגה רק שהשגה זו נק' השגה שבהעלם ולכאורה ההעלם א\"א שיושג ואיך יתכן לקרות השגה שבהעל' אמנם הענין הוא דשכל שבדבור נק' השגה גלוי' אבל שכל עמוק עמוק כנ\"ל שא\"א לגלותו בדיבור גם אם ירבה בדיבור או יקצר לא יכילנו כלי הדיבו' מצד העומק שלו העצו' עד שאין האותיו' מכילי' אותו ואין לו לבוש כלל גם במחשבה בהתגלות רק כהעלם העיון הדק ביותר הנק' עומק המחשבה וגם לא בהלבשת משלי' וחידות להעלימו ביותר גם זה לא יכילנו וכידוע דמ\"ש וידבר ג' אלפי' משל היינו עמקי תעלומות חכמה שיוכלו לבא בגלוי ע\"י המשלי' עכ\"פ כג' מאות מתלי' דר\"מ (דהמשל מגלה סוד ע\"י לבושו הגס אבל אינו מגלה רק סוד הבא לגלוי הנק' ח\"ס ותעלומו' ופלאו' חכמה כו' אבל רזא דרזין גם במשלי' דשלמ' וכה\"ג לא נתגלה רק לע\"ל יתגלה וגם שה\"ש דנק' קה\"ק בא לגלוי עכ\"פ באותיות וגם בחי' הטעמים ונגינות רינה דאורייתא בא לגלוי רק שאינו בא בדבור באותיות אבל טעם וסוד הנשאר סתים גם בטעמים לא בא ומ\"ש ויהי שירו כו' אינו רק גלוי בבחי' פלאות חכמה וכה\"ג) (ואין השיר בניגון וטעמי' שבתורה נק' השגה שבהעלם מאחר שאינו בא בדבור כי עכ\"פ גלוי הוא בקול וכמו קולו של משה כו' משא\"כ הרמז שלא נודע רק למבין מדעתו וד\"ל) והנה עמקות המחשבה הנעלמת שמכילים קצת לשכל העמוק ביותר הוא הנק' חכם ומבין מדעתו כמו במעש' מרכבה דכתיב בהו במופלא כו' ודוקא בל תדרוש בגלוי הדבור כלל רק שיהיה מבין מדעתו בעומק ההשגה הנעלמ' שבמח' הנק' השגה שבהעל' ולכך אין מוסרי' לו רק ראשי פרקים כו' ואם אינו חכם ומבין מדעתו בהם אסור לגלות לו משום שנאמר בל תדרוש (ובאמת אל תדרוש ותחקור גם לעצמו קאמר כמו ולא הלכתי בגדולות ובנפלאות ממני כו' דאם נק' רזא דרזין בלתי אפשר שיצאו אמתתם לגלוי והדורשם אינו מכוין לאמתתם כקוצץ ופוגם באור הנעלם שזהו עיקר כבודו להיות בהעל' דווקא וכמ\"ש כבוד אלקי' הסתר כו' ויש בזה ב' טעמי' א' שאין הגלוי לאמתתו וממילא אין זה כבודו ועוד שגם אם הי' מכוין לאמיתתו עיקר כבודו בהעלם וכמו שהפליגו בעונש המגלה רזין כו' וכענין ההוגה השם כו' וכפי' ונוקב שם ומגלה כו' ויש סוד שכבודו לבא בגלוי ומכוונין לאמיתו כמו סוד ה' ליראיו שמגלה סודו ליראיו וזהו כבודו וכמ\"ש כבוד מלכים חקור כו' והיינו במה שהורשית התבונן דוקא והוא טעם לשבח בגלוי רזין דאוריית' לטובי' ולישרי' ילכו בם לראות אור עולם וכו' וכמו בלימוד הזה\"ק וכה\"ג כידוע) והרמז ביד מורי על הבנת והשגת עצמו דוק' במה שמבין מדעתו לבד שא\"א לגלות' בדבור כלל והוא בחי' הממוצע בין רזא לרזא דרזין הנ\"ל"],[1700400223,"דהיינו שהוא גלוי הבא בהעלם דווקא כענין כריעות והשתחוואו' דר\"ע הנ\"ל וד\"ל ונמצא שכל שהוא נתפס בהשגה בגלוי יבא בדיבור וכל שלא יותפס בהשגה רק בהעלם ודקות לא יבא בדיבור רק ברמז וכה\"ג וזהו ההפרש בין ב' מיני סוד הנ\"ל הא' שהסוד דחכמה מאין בא ליש בגלוי בהשגה דבינה והב' הסוד סתום שלא יבא בגדר השגה לעולם ונק' נתיב לא ידעו כו' (ובאמת כתיב לא ידעו בגילוי קא' אלא בהעלם והוא בחי' שביל דקיק דבי' עייל אבא להיכל אימא כו' לפי שגם בגילוי השפע מאין ליש יש מדריגה שנמשך בהעלם כמו הבן בחכמ' הרי יש בינה בחכמ' וחכמ' יש בבינה רק שהוא בהעלם) והנה מעתה מה שיש בכח היין להוציא הסוד כנ\"ל שבהכרח יבא מכח העליון יותר מהסוד הנעלם שאינו בא לגלוי הרי שרש היין מגיע בהעלם העצמו' יותר רק שפעולתו להיפך להוציא הסוד בגלוי ומ\"מ מה שנק' סוד סתום לגמרי אין בכח היין להביא בגלוי (ובאמת יש בכח יין ישן לגלות סוד סתום דזקן שקנה חכמה כנ\"ל ולזה בחי' יין המשומ' לע\"ל יגלה סוד הסתום שהוא מ\"ש כוסי רויה כו' ואפשר לא מבחי' סדכ\"ס רק מבחי' ח\"ס דא\"א כו') רק סוד שיוכל לבא לגלוי מגל' הכל וכן השמחה שמגלה הצפון אע\"פ שמגל' כל עצמותו לא יתגלה מה שא\"א לבא בגלוי לעולם זהו ההפרש בין יין ושמן הנק' תירוש ויצהר שהשמן הוא בחי' סוד סתים הנ\"ל שא\"א לבא לגלוי לעולם והיין הוא הסוד שבא לידי גלוי לפרקי' כמו אגברו חמרי אדרדקי כנ\"ל והמה ב' הפכי' ממש מן הקצה כו' וד\"ל:\n(נו) <b>וזהו</b> ענין מחלוקת ריב\"נ ורבנן בשמן שצף ע\"ג יין אם יש חיבור כו' דהנה השמן הוא בבחי' החכמ' שנק' קדש מלה בגרמי' מובדל מכל דבר ויש כו' אלא הוא תמיד בבחי' אין והעלם גדול והוא הנק' סוד סתום שבלתי בא בגלוי לעולם כנ\"ל והיין הוא המוציא הסוד לגילוי וב' הפכי' כאלה מהקצה כו' כנ\"ל בלתי אפשר שיתחברו ולכך השמן צף ע\"ג היין בלתי נמשך ומתחבר בו כלל וכלל כי אין טבעו לירד בגלוי כלל וזהו הטעם דמ\"ד שאין להם חיבור זע\"ז לטומאה גם לא לפרקים ומ\"ד שיש להם חיבור טעמו הוא לפי שגם שהשמן בלתי מתחבר ביין בתערובות ממש שהוא ערוב החלקי' כעירוב מים ביין אבל בעמדו ע\"ג היין וצף ע\"ג מ\"מ נדבק ונוגע ביין בנגיעה ודביקה ממש שא\"א להפרידם (דגם אם יסננו או יבדילו לגמרי השמן מן היין ישאר חלקי' שמנונית דשמן ע\"ג היין הרי נוגע ומודבק עכ\"פ ואדרבה בענין דביקותם בנגיעה יותר הוא דבוק מדביקות יין ומים יחד לפי שהשמן בטבעו נדבק בכל דבר רק שבשאר הדברים הוא מפעפע ובמשקין עומד למעלה) וזהו דמיון להבין ענין תרין רעין דלא מתפרשין לעלמין שהן חו\"ב שבחי' אין דחכמ' נמשך ונדבק בהשגה דבינה כמו גלוי הסוד מהעלמו שבא מאין ליש ממש ואע\"פ שגם בהשגה מובדל לעצמו בחי' נקוד' אין דחכמ' כידוע בלתי מתערב בחלקי ההסבר המושג ממש וכמו וחכם בבינה שנק' עומק המושג כו' עכ\"ז דבוקים כא' ולא מתפרשין לעלמין כמעיין הנובע ונמשך לנהר מהעלם לגלוי שדבוק המעיין בנביעתו לנהר יחדיו ידובקו כו' ולכך ס\"ל שיש להם חיבור לטומאה וד\"ל אך עדיין קשה על שניהם דמ\"ד אין להם חיבור אין זה רק מטעם דבחי' סוד סתום הנ\"ל שנק' רזא דרזין וכה\"ג הרי מטעם מדריגה הב' דחכמ' שנק' רזא שהוא סוד הבא לגלוי הי' לו להודות דיש להם חיבור וכן אידך מ\"ד דס\"ל שיש להם חיבור הרי מטעם בחי' סוד סתום שלא בא לגלוי הל\"ל דאין להם חיבור ועוד למה חלקו בדבר הנראה שבנגיע' יש להם חיבור ובעצ' התערוב' אין להם חיבור ואמנם הנה באמת הגם שמבואר"],[1700400224,"למעלה בבחי' שמן שאינו בא לידי גלוי לעולם הרי לכאורה יש סתירה גדולה מכמה מקומות שמצינו היפך זה ממש דהיינו שבחי' שמן הוא בא בבחי' ההמשכ' וירידה דוקא היפך הסתימו' וההעלם בעצמו' והוא מ\"ש כשמן הטוב על הראש דכה\"ג יורק על הזקן זקן אהרן כו' שזהו עיקר ומקור ההמשכה עליונה מהעצ' דקדושה העליונה שבשמן זה דוקא נמשך בחי' קדש העליון על ראשו וזקנו ומשם יורד ע\"פ מדותיו כו' שמשם מקור לי\"ג מדה\"ר וכן כל כלי המקדש שנמשחו בשמן משחת קדש הרי עיקר הקדושה שבאה בגלוי עליהם להיות נק' כלי קדש אינו רק ע\"י המשכה זו שנמשכו בשמן ולכך נק' שמן משחת קדש העליון כו' וכה\"ג כל המלכים שנמשחו בשמן הקדש מן הפך או הקרן כדוד ושאול ושאר מלכים כו' לפי שהשמן בעצם טבעו בבחי' המשכה דוקא וכמ\"ש ונהרותם כשמן אוליך כו' הרי שבח זה למעליו' אמר שיהי' המשכת הנהרות בבחי' המשכה טובה כהמשכת שמן שהוא נמשך בטוב יותר מהמשכת מים וכמו טבע השמן שנמשך בכל דבר גם אחר הפתילה וגם נמשך ונדבק בדומם הקשה כצור ואבן מפעפע ונדבק בו בכל חלקיו וכמ\"ש ושמן מחלמיש צור וכה\"ג (וכמ\"ש בספרי החקירה שיש בכל חלקי דצח\"ע וד\"י מהשמן הנק' אלים) (ולכך אנו מוצאי' דבחי' החכמ' נמשך ומתפשט עד למטה מטה ביותר וכמ\"ש כולם בחכמ' עשית עד שבדומם יש כח מאור החכמ' והוא מ\"ש ושמן מחלמיש כמ\"ש במ\"א) אך הנה באמת יש בשמן מב' הענינים ההפכיי' א' שהוא בבחי' הסתימו' וההעלם בלתי בא בגלוי כלל והב' מה שבא בהמשכ' להיותו נדבק למט' מטה ביות' כנ\"ל אמנם כל בחי' המשכ' דשמן אינה בחי' המשכה גלוי' כהמשכת קול ודבור ופעולה ותנועה וכה\"ג אלא היא נקראת בחי' המשכ' נעלמה ביותר כענין קול דממה דקה תמן קאתי מלכא דקאתי מלכא ממש מההעלם העצמו' אבל הוא בא בהעלם ובחשאי בלתי נודע ומורגש כלל כדוגמת קלא דלא משתמ' והיינו ונהרותם כשמן אוליך בלתי מורגש כלל וכלל וד\"ל דהנה לכאורה יש להבין בענין ב' מיני סוד הנ\"ל דאם באמת בחי' סוד סתום הנ\"ל אין בטבעו ומהותו כלל לבא לגלוי א\"כ פליאה גדולה מה שיוכל להיות גלוי סוד כמו גלוי סוד ה' ליריאיו דודאי אין הכוונה רק על סוד הב' הנ\"ל שבא לגלוי כנ\"ל שהרי גם הסוד הזה שיוכל לבא לגלוי בא בבחי' המשכ' מהעלם עצמו' בעל הסודות (כדוגמת חכם הרזים הנ\"ל) טרם שיבא לגלוי וא\"כ מוכרח שיש בחי' המשכה עכ\"פ גם מסוד סתום הנ\"ל מאחר שהוא מקור מוצא לכל סוד שבהעלם (כמו חכם הרזים) [וכמו רשב\"י שהיה מגלה סודות התורה וטרם שגילה לחביריו סוד ה' הזה הי' בא הכל בנפשו בהעלם ונמשך כמעיין המתגבר וכאור המאיר שבודאי נמשך זה המקור ממקורא ומבועא דכולא שנק' העלם כל העלם או עומקא דעומקא כו'] ולפ\"ז פי' סוד ה' ליראיו לא בגלוי דוקא אלא גם בהעלם כענין חכם ומבין מדעתו הנ\"ל שנק' המשכה נעלמת כנ\"ל גם לזה יש מקור מוצא שנק' מקור הראשון שהוא מקור להמשכ' כל סוד שבהעל' ממש כמו שסוד הבא לגלוי נק' מקור לגלוי ממש וד\"ל וא\"כ א\"א להחליט בסוד סתום הנ\"ל שאינו בא בגלוי לעולם כ\"א שבלתי בא בגלוי גמור מאין ליש ממש אבל הנה הוא בא ונמשך להיות בבחי' המשכה הנעלמת הנק' סוד ה' וסוד זה הרי נמשך לגלוי גמור ולפ\"ז הדרא קושי' לדוכתא למה נק' סוד סתום לגמרי מכל וכל מאחר שעתי' לבא ממנו בגלוי עכ\"פ יהי' איך שיהי' וד\"ל אלא מוכרח לומר דבחי' המשכ' הנעלמה דחכמ' אינו בא לגלוי לעולם והוא בחי' פנימי' החכמ' מ\"ה דחכמ' ומה שיש סוד שבא לגלוי הוא בחי' חיצוניו' חכמ' שמאיר בבינה ונדבק שם כענין תרי רעין כו' ונמצא דסוד סתום לא בא לגלוי לעולם"],[1700400225,"[ולפ\"ז חכם הרזים כרשב\"י אינו בא בהשגה גמורה וכן סוד ה' ליריאיו סתום וגנוז רק להם משא\"כ בנשמות בג\"ע שהכל יכולין ליהנות ולהשיג כו' שהוא גלוי סוד ממש] וזהו עיקר ההפר' בין חו\"ב שנק' שמן ויין דיין גי' סוד שבא בגלוי ושמן בלתי נגל' אע\"פ שנמשך ממש בהמשכה רק שנמשך בהעל' וביאור זה אנו מוצאי' בענין המשכו' בטול דהיינו כמו כריעות והשתחוואו' שאנו רואי' המשכ' בתנועו' שונו' אבל הוא מצד תכלית הביטול וכן קול דממה דקב וצלותא בלחש וכמ\"ש בזוהר בפי' יביע אומר בהעלם גדול ולא יבא לעולם לגלוי כשמן שצף כו' וזהו ב' ענינים שבשמן והכל א' דהיינו עצם ההעלם והסתימות בלתי נגלה כלל לעולם והב' מה שנמשך אבל בבחי' המשכ' נעלמת דוקא ובהיותו נמשך מבחי' ההעלם העצמי שלא יבא לגלוי לעולם ע\"כ גם המשכה נעלמה זו לא תתגלה לעולם ואם בא ממנה גלוי אין זה פנימיותה רק חיצוניות' שהוא הנגלה בהשגה דבינה וזהו שהשמן נבדל מהכל ונמשך בכל לפי שהמשכתו בהעלם וגם בדומם הקשה יומשך וכמו המשכ' בטול דמ\"ה דחכמ' שנמשך למטה מטה כנ\"ל וזהו ונהרות' כשמן אוליך לשבח גדול קא' דהמשכ' חסדי' המגולים שהן מי נהר שיוצא מעדן עכשיו לע\"ל יהי' במדריג' המשכה נעלמת דחכמ' כמו שמן משחת קדש הנ\"ל בכה\"ג וכלי הקדש שהוא נשאר בהעלם וכמ\"ש ולא יראו כבלע את הקדש כו' ובזה הכל מתורץ דודאי עיקר הקדושה נמשך ע\"י השמן לפי שהוא בחי' המשכה מן העצמו' דוקא לכך נק' גם הוא קדש מלה בגרמי' כשמן על הראש דכה\"ג הנ\"ל אבל הוא בחשאי ובהעלם והיינו מצד שרשו שהוא בסתימו' ממש שהוא בחי' סוד סתום לעולם הנ\"ל וגם טעם מחלוקותם יתורץ דמ\"ד יש לו חיבור מצד הנגיעה היינו בחיצוניו' דח\"ע ומ\"ד דאין לו חיבור הוא מצד פנימי' דח\"ע שנק' ח\"ס ונק' שמן קדש וכה\"ג בחי' קול דממה דקה כו' ולענין טומאה שהוא יניקות החיצוני' שאינו אלא מאחוריי' דחכמ' אבל בפנימי' ח\"ע נא' ימותו ולא בחכמ' לכך אין לו חיבור ומ\"ד דיש לו חיבור לטומאה הוא מצד אחיזת החיצוני' באחוריי' דחכמ' והוא בנגיעה שנוגע השמן ביין ונדבק בו כנ\"ל שהוא בחי' חו\"ב תרין רעין כו' וד\"ל ובכ\"ז יובן ג\"כ בענין רזין דאורייתא שהוא סתים שבתורה יש ב' מדרגו' סוד סתום כשמן הנק' יצהר גם בהמשכות הסודות כנ\"ל וכמ\"ש לריח שמניך וכה\"ג יוהב' יינה דאורייתא שהוא גלוי הסוד ושניהם למעלה מבחי' גליא דתורה שהוא התלמו' שנק' דגנך שהוא בא לברר ברורי' דעה\"ד להבדיל כו' ונק' לחם שיסעד הלב אמנם יש בו' ג\"כ ב' מדריגו' טעם הלחם שהוא טעמים שבתלמוד ושרשו מטוב טעם שבסוד סתים שבפנימי' התורה ולע\"ל נק' לחם פנג וכן לחם הפנים והב' גשם הלחם שהוא מחבר הנפש בגוף כמו מזון שסועד הלב והוא לנגד יינה של תור' כו' (משא\"כ בשר וש\"ד לא נק' מזון אעפ\"י שמוסיף דם הוא הנפש א\"י להלוך ברגל כנ\"ל בענין דוק בככי' כו' לפי ששרש הלח' בחכמ' שנק' מזלא רק שבא בבחי' המשכה נעלמ' ג\"כ כשמן ובטעם רוחני שבו הנק' טעם דגן ובגלוי כיין שמוצי' סוד בגשמיו' שבו ולכך סמכם כא' דגנך תירושך ויצהרך וד\"ל) (וכן מ\"ש ויתן לך כו' מטל השמים ומשמני הארץ ורוב דגן ותירוש כו' ולע\"ל יהיה כ\"ז שלא ע\"י העלמה כלל וכלל וכמ\"ש במ\"א בענין עתידה א\"י שתוציא גלוסקאות כו' כי גם שמן ויין בהעלמה באו שהוא ע\"י נר מצוה כמשי\"ת וד\"ל):\n(נז) <b>והנה</b> מבואר למעלה בסדר הכתובי' הללו בפ' והיה שהוא ונתתי מטר ארצכם ואח\"כ ואספת דגנך כו' משמע דכסדרן באין זא\"ז דתחלה ונתתי מטר אז ואספת דגנך כו' בהיות שבפ' זו השנית הוא ענין קבלת עול מצות"],[1700400226,"וכמבואר למעלה וכתיב כי נר מצוה ותור' אור שע\"י נר מצוה דוקא בא האור דתורה מהעלם לגלוי בג' מדריגות הללו דדגנך תירושך ויצהרך שהוא סתים וגליא בין בחיצוניות בין בפנימי' שבתורה הכל ע\"י נר מצוה באו כי הנה השמן בנר נמשך אחר הפתילה ומזה מאיר האור וא' בזהר ע\"פ ושמן על ראשך כו' דא עובדן טבאן כו' להיות אור דתורה העצמי' בבחי' סוד סתום וכמוס כמ\"ש חתום תורה כו' וע\"י השמן ופתילה יומשך בגלוי אור (וגלוי אור זה הוא כמו בחי' הארת פנים שהוא גלוי העצמו' ממש וכנ\"ל בפי' חכמ' אדם תאיר פניו ולזה אור גי' רז והוא למעלה גם מבחי' רזא דרזין הנ\"ל שאינו בא בגלוי לעולם מאחר שבא לגלוי בפנים וכמו לע\"ל כו' ולזה חייבי' להקביל פני רבו דוקא וזהו יתרון מעלת שמן למאור על שמן משחת קדש הנ\"ל) והיינו מ\"ש ונתתי מטר תחלה ועי\"ז יהי' גלוי אור דתורה ע\"י שלשה אופנים בטעם דגן שבתלמוד לברר ברורים דעה\"ד דבח\"ע אתברירו וע\"י שמן ויין בחי' חו\"ב שבהעלם הבא לגלוי שזהו תירושך ויצהרך והכל להאיר את הנשמ' האלקי' שנק' אדם ואמנם מה שע\"י נר מצוה דוקא בא אור דתורה מהעלם העצמו' לגלוי כו' הנה זהו מ\"ש ונתתי מטר דמטר הוא רמ\"ח מ\"ע וע\"ה גי' מטר ושרשם הראשון הוא בחי' ה\"ח העצמיי' כו' (והוא בחי' המשכת מ\"ד שע\"י המצות שעי\"ז יבא אור דתור' כו' וכנ\"ל בפי' מטר) ועוד יתפרש ענין מטר זה באמרו ונתתי דרך מתנה מעצמו כי חפץ חסד הוא כו' על ענין שרש הראשון להמשכ' אור דתור' מהעל' לגלוי הנ\"ל בענין תירושך ויצהרך כו' בהיו' מבואר למעל' בבחי' שמן שהוא בחי' המשכה נעלמת עכ\"פ ומוכרח ודאי שיש מקור הממשיך המשכה נעלמה זו בכמה מדריגות חלוקות ואופנים שונים וכמ\"כ בהמשכה הב' שבא' לגלוי סוד ממש כנ\"ל והנה להבין זה בתוס' ביאור יש להקדי' ענין הידוע בע\"ח בשרשים של המוחין דאו\"א שהן מקבלים מב' מזלות דנוצר ונקה אור אבא יונק ממזל הח' ונוצר חסד ואור אימא ממזל הי\"ג ונקה כו' וזה שאמרז\"ל הכל תלוי במזל אפי' ס\"ת בהיכל שהוא יחוד או\"א במוחין חדשים שמקבלים מבחי' מזל העליון ומזל התחתון שהו ונוצר ונקה דהיינו שלפי אופן היחוד ב' מזלות הללו בעצמן תחלה כך יהיה אופן השפע שלהם לאו\"א כו' וכדוגמא זאת מצינו בגמ' שאמרו מזל מחכים כו' דמשמע דשרש מקור החכמה תלוי במזל וזה פלא לכאורה אך הנה ידוע בענין המאמר אאלפך חכמה דפירושו להבא שעתיד ללמדו ועדיין לא למד והוא ענין מקור הראשון שממנו עתיד להיות המשכה ולימוד זה כשהוא בהעלם וסתימות נק' פלא ולא אלף ומ\"ש אאלפך הוא כענין עושה פלא שממשיך ועושה לפלא להיות אלף ממנו כידוע והיינו מה שיצא הסוד הסתום לגלוי ולא לגלוי גמור אלא להיות בחי' המשכה נעלמת הנ\"ל שהוא הנק' פלא דהיינו שממשיך ועושה לפלא סוד זה ומפלא זה עתי' להיות אלף הוא מ\"ש אאלפך שעתיד להיות אלף ולא ישנו עדיין רק שעתיד להיות במציאות והנה ביאור הדברים הללו ידוע ויש להקדים תחלה במשל המטר גשמי דהנה אנו רואים התהוות המטר בגשמיות הוא בא כדמיון אות ו' שראשו יו\"ד והוא כדמיון הקו וחוט שנמשך בדקות גדול ממקורו שבהעלם כך המטר הוא קוין וחוטין דקין מאד ביציאתן ממקורם ונמשכין בדקות והעלם ולמטה נראין בהגשמה גמורה כידוע וה\"ז ממש כדמיון השערו' שיונקין ונמשכין ממוחין שבראש שיש לכל שערה ושערה גומא בראשששם יונקת חיות רוחני בהעל' ודקו' גדול וראשית יציאת' הוא בהמשכ' נעלמו' ודקה מצומצם מאד בחלל השערה ואח\"כ הולך וגדל ונמשך למטה בהגשמה גמורה שהשערה בעצם גשם נבדל מן חיות הגוף כידוע והדוגמא מן השערות שיש לכ\"א"],[1700400227,"גומא בהעלם יניקתה ואם היו יוצאין שתים מגומא אח' הי' מבלבל המוח כך המטר יש לכל טפה שרש ומקור בפ\"ע ואם היו שתים יוצאו' כו' כמבואר בדברי רז\"ל ע\"פ ובסערה כו' ודרך לחזיז קולות כו' בין שערה ושערה לא נתחלף כו' והנה למעלה מעלה יובן מזה הדגומא בבחי' מזלות עליונות שהמזל הוא כמו יזל מים כו' שההזלה עצמה באה בדקות והעלם וצמצום גדול כי לא נודע מאין הוא בא וכמ\"כ המשכת החכמ' מאין שהוא מבחי' מזל ונוצר כנ\"ל שמבואר במ\"א שזהו כמשל המציא' שמוצאין בדרך שלא נודע מאין באה ועכ\"ז ישנה במציאת כך הוא גלוי נקודת החכמ' שנופל מלמעלה מן השכל שלא נודע מי הוא המשפיע וה\"ז כמו השפע הנמשך דרך צינור דק ונעלם מאד וזהו כמו יניקת השערה מהגומא בהעלם ודקות גדול מאד וזהו והחכמ' מאין ממש תמצא אח\"כ במציא' נקודה עכ\"פ כברק המבריק כו' כידוע בכל אור ושפע התחכמו' שנק' הבנה והמצאה הגם שעדיין היא כנקודה עד שבאה לכלל השגה בבינה בהסבר רב כו' מ\"מ נק' גלוי לגבי מקורה שהוא משפיע בבחי' המשכה נעלמה והוא בחי' הצינור מזל ונוצר (וכמו פתח ר' פלוני פי' פתח הצינור כו') והנה בחי' סוד הב' הנ\"ל שבא לגלוי הרי הוא בא לגלוי בהשגה ממש אבל גלוי זה דנקוד' חכמה מח המשכיל בא בבחי' המשכת סוד נעלם הנ\"ל בסוד סתום והיינו שכח המשכיל ההיולי טרם ששופע וממשיך גם לבחי' המשכה נעלמה דרך צינור ושערו' הנ\"ל הוא בבחי' סוד סתום הנ\"ל שבלתי בא לגלוי המשכה כלל וכלל אך כמו שהוא בעצם להשכיל כל שכל נעלם יש בזה ג\"כ מדריגות חלוקות כמ\"ש יהב חכמתא לחכימין דוקא וכמו שהקטן כח המשכיל ההיולי שלו קטן וגדל וצומח וזהו ג\"כ מזל מחכים וכן והחכמ' מאין כו' אבל הוא למעלה הרבה מהמשכו' החכמ' בהתחכמו' פרטיות (וכמבואר הכל בפי' המלות דב\"ש בענין רדל\"א כו') וכן פי' אאלפך חכמ' יתפרש על עצם כח המשכיל כו' ובאמת הכל א' דהא בהא תליא דלפ\"ע הזקנה שנתוסף עצם כח חכמתו נתוסף לפ\"ע צינורי שפעו להשכיל שכל דרך צינור בהעלם והן ע\"י בחי' שערות הזקן שקנה חכמה ממקור' כו' וכמ\"ש באד\"ז דסבא דעתי' סתום כו' וד\"ל וזהו ענין מזל ונוצר להיות מקור להמשכת חכמ' מאין בהעלם שנק' מטר כמטר היורד מלמעלה בהעלם ומזל ונקה הוא מקור להמשכה בגלוי שבבחי' בינה מאין ליש ממש (ולכך זה נק' מזל העליון וזה נק' מזל התחתון וכמשי\"ת בסמוך בענין יורה ומלקוש) והנה לפי אופן היחוד העליון בב' מזלות דנוצר ונקה כן יהיה ערך השפע בחו\"ב כנ\"ל והענין הוא כנ\"ל דעצם כח המשכיל כל שכל שישכיל כו' עדיין לא נק' גם ח\"ס בבחי' העלם ההמשכה ג\"כ ואופן היחוד דב' מזלות הנ\"ל היינו שנמשך למזל העליון דנוצר תוס' כח ועוז לעצמו להמשיך למזל התחתון להיות שגם המזל העליון הזה צריך לקבל מעצם כח המשכיל שיהיה לו תוס' כח כמו בגומ' של השערה שבראש שנמשך בה תוס' חיות להשפיע תמיד כו' (ובל' העולם הוא כמו שאמ' מזל מחכי' לפי השעה והזמן שהתחכמות אינה דומה מזמן לזמן ויש זמן שמצליח בלימודו להתחכם בהמצאו' שכליות חדשות ועמוקות ביותר ויש זמן שאינו מצליח כ\"כ ואינו ממציא לעומק ולא לנקודת האמת וכה\"ג וזה תלוי במזל ונוצר כפי קבלתו ממקור הראשון) וכמ\"ש יהב חכמתא כו' ונתינה זאת הוא ליתן תוספת כח ואור במזל ונוצר כמו יזל מים מדליו כו' באר מים חיים ונוזלי' כמעין המתגבר כו' ואז ממילא נכר זה התוס' בחו\"ב שבאין בגלוי שהוא נקודת חכמ' הנ\"ל (הנק' הבנה והמצאה והשגה דבינה שנק' הסבר לאורך ורוחב כידוע) וזהו פי' אאלפך חכמ' לשון עתיד דוק'"],[1700400228,"כנ\"ל דהיינו שעתי' להיות לימוד הנעלם שהוא המשכה נעלמת דפלא כמו עושה פלא בחי' צנור דונוצר שנתוסף בה כח עי\"ז אאלפך ומ\"ש בל' אלף משום דהכל א' דמפלא זה נעשה אלף שהו' לימוד בגלוי מונוצר הנ\"ל שהוא נקודת חכמה המבריק כברק הנ\"ל וכן אאלפך בינה עתיד לגדל ולהצמיח כח המשיג השגות בהסבר כו' וד\"ל וזהו פי' ונתתי מטר ארצכם פי' מטר זה הוא בחי' מקור הראשון שמשם מקבלים הב' מזלות ונוצר ונקה שנוזלים כמטר אבל מי הוא הנותן זה המטר ה\"ז בא ממקור להמשכ' המזלות הללו לזה א' ונתתי מטר שתלוי בדעת הנותן דוקא כמו יהב חכמתא כו' שתלוי בדעת הנותן כח ועוז למזלות כו' כי יש מקור שמשם הם נובעין כנ\"ל וד\"ל והענין הוא כידוע דאעפ\"י ששרש יניקות המזלות מגומא שבמוחין שבראש שנק' גלגלתא מ\"מ עיקר שרש הראשון שלהם מבחי' הגלגלתא עצמה דהיינו מבחי' חסד דע\"י שבגלגלתא דא\"א שרש למזל ונוצר חסד ששרשו ברב חסד שבעצמו' המאציל וירד מגבוה לנמוך להיות מקור למקור לחו\"ב כנ\"ל וזהו ונתתי בדרך מתנה וחסד חנם כי חפץ חסד הוא מצד טבע הטוב להטיב (והיינו רב חסד דביה אחיד אבא כו' והוא שרש לקו הימין חח\"ן והוא ה\"א דהגדול כידוע בחי' גבורה דע\"י שמלובש בח\"ס דא\"א משם שרש למזל ונקה שהוא מקור לבינה וכמ\"ש אני בינה לי גבורה והוא קו השמאל בג\"ה כידוע וכמשי\"ת בסמוך בענין יורה ומלקוש כו' וד\"ל:\n(נח) <b>ומעתה</b> יש להבין ענין יורה ומלקוש הנה מבואר מדברי רז\"ל במס' תענית דע\"ד הפשוט ב' מיני מטר הללו יור' ומלקוש יורה זמנו במרחשון שבמרחשון זמן הזריעה שזורעין התבואה בארץ אז יורד המטר הזה הנק' יורה ומלקוש הוא מטר היורד בניסן שאז זמן שכל התבואות באות לגמר צמיחתן ובישולן והנה התועלת המגיע מב' מיני מטר הללו לתבואת הארץ המה ב' ענינים הפכיים מן הקצה לקצה ממש דהנה מטר הנק' יורה שיורד במרחשון בזמן הזריע' עיקר התועל' ממנו רק ללחלח חלקי הארץ לבד כדי שיוכל להיות עי\"ז רקבון הגרעין בארץ במהירות ובכליון יותר שהוא ענין הקליטה היטב שתאבד גשמיותה לגמרי ותוקלט רוחניות כח הצומח שבה בבחי' העלא' מ\"ן בכח הצומח שבארץ הכללי וכל שיעלה בכי טוב יותר בחי' התכללות דרוחניות שבגרעין בכח הצומח יותר יומשך מכח הצומח להצמיח הגרעין בת וס' מרובה על העיקר הנזרע כמו כלום אדם זורע קב אלא להוציא כמה כורי' כידוע וכידוע דזהו בחי' ביטול היש לאין שצריך להיות ההפשטה מבחי' הישות לגמרי מכל וכל בעלותו ליכלל בבחי' האין דכח הצומח כדי להמשיך מחדש מכח האין ליש כו' ולזה הוא כל עיקר התועלת מן המטר היורד במרחשון בזמן זריעת התבואה בארץ כידוע ואמנם הנה תועלת המטר השני הנק' מלקוש היורד בניסן הוא להיפך מזה ממש דהנה בזמן ר\"ח ניסן כבר נשלם צמיחת וגידול כל התבואות דהיינו שכבר גדלו כל צרכן שלא יצטרך עוד למטר להוסיף בהן צמיחה כלל כי לא יצמחו עוד בתוס' מצד שכבר נשלם השיעור שצריכין לצמוח וכמו השבולת של חטים נשלם שיעור צמיחתה בכמותה ואיכות' שלטא יתוסף עוד חטים בשבולת זו מכמו שהן ד' או ה' או י' וי\"א וכה\"ג ואמנם החטים הקבוצים יחד בשבולת כמה שהן במספר הן עדיין דקים וריקים בדלות ורזין בלי ממשות ניכרת בהן עדיין רק שכמותן נגדל כשיעור הצריך ובצמיח' יש ב' דברים הא' שנצמח גוף דבר העצם בצלמו ותמונתו לבד והוא החטה כמו שהיא במהותה בציורה ותמונתה לבד והב' בשפע אור וחיות"],[1700400229,"רוחניו' וגשמיות דהיינו מילוי גשם ממשות החטה שתתמלא בטוב וכן הפרי כענבי' וזתים ותפוחים וכה\"ג שנתמלאו בטוב ונתבשלו כל צרכן ומילוי זה ברוחניות הוא טוב השמנוניות והמלאו' והבריאו' שימצא בה ריבוי טוב טעם וחיות הרבה ונק' שבלים הבריאו' והמלאות וטובות (משא\"כ שבלי' דקות ורקות כו') דהיינו שכל חטה מלא' וגסה בהתפשטות וריבוי מצד רוב השמנונית שטבעו להתפשט כו' (כמו שמנת עבית כו') אז נק' שבולת המלאה וטובה ובריאה כידוע והנה סיבת רבוי התפשטות ישות החטה בשמנונית בא ע\"י המטר השני הנק' מלקוש שיורד בניסן שתועלתו אינו בשביל צמיחה כלל רק ליתן כח ושפע גדולה בחטים שבשבולת שיצמחו בהתפשטות וריבוי ומילוי במהותם ברוב שמנונית ומלאו' כנ\"ל דהיינו שיבאו החטים לתכלית גידולן בבחי' ההתפשטו' ומילוי ולא שיתוסף עוד חטים כי כבר נצמחו שיעור מספרן לא יוסיף ולא יגרע רק אותן שכבר צמחו שיבאו לתכלית התפשטותה במילוי טוב ומלא כנ\"ל לכך יורד בניסן דוקא והנה באמת הרי ב' מיני מטר הנ\"ל המה ב' הפכי' מן הקצה לקצה דהנה עיקר תועלת המטר שנק' יורה אינו רק לעשות הצמיחה כנ\"ל והוא בחי' הקליטה שיוקלט היטב שזהו בחי' הביטול וההתכללות כל הישות וממשות של החטה ליכלל באין דכח הצומח והוא רקבון הגרעין שיוכלל כח הצומח שבחט' בכח ההיולי דכח הצומח שבארץ בבחי' העלא' מ\"ן כו' וה\"ז בחי' התהפכות יש לאין שזה פועל המטר הנק' יורה שיורד בחשון בשעת זריעה והוא היפך גמור לתועלת שמן המטר שנק' מלקוש שיורד בניסן שהרי תועלת המט' דמלקוש אינו אלא לפעול פעולת התפשטו' ומילוי וריבוי בחטים שיהיו מלאו' וטובות ובריאות כנ\"ל שזהו בחי' התולדה מאין ליש דהיינו שיהיה בחי' ריבוי התפשטו' הישות יותר וזהו מבחי' האין שנמשך ובא בהתפשטו' יש דהיינו שכח המצמיח שכבר בא בחטים שצמחו וגדלו שעל' מן הארץ יבא בבחי' התפשטות וריבוי ישות וגסות ברוחניו' וגשמיו' יותר וכח זה שבשבולת תצמיח במילוי והתפשטו' יש הוא היפך ביטול והתכללו' החט' בארץ שהוא התהפכו' מיש לאין ונמצא שהן ב' הפכי' ממש שזה פועל הביטול יש לאין וזה פועל התולד' והתפשטו' מאין ליש ולכך הן בשני זמנים מחולקים זה בחשון לקליטת התבואו' וזה בניסן למילויי' וד\"ל והנמשל מב' מיני מטר הללו יובן למשכיל למעל' דהיינו ב' מיני מזלות הנ\"ל מזל ונוצר ומזל ונקה שנק' מזל העליון ומזל התחתון שנמשלי' למטר כנ\"ל בפי' ונתתי מטר כו' דהנה בחי' מזל ונוצר הוא בחי' המטר שנק' יורה שיורד בחשון ומזל ונקה הוא בחי' מטר הב' שנק' מלקוש שיורד בניסן וז\"ש ונתתי מטר ארצכם בעתו יורה ומלקוש בעתו דוק' שהוא יורה בחשון ומלקוש בניסן כפי הפשוט המבואר במס' תענית כנ\"ל ומזה יובן ג\"כ בענין ב' מזלות הנ\"ל שגם הן שני הפכי' בתועלתם כנ\"ל ביורה ומלקוש דהנה ידוע שהחכמ' נק' אין והבינה נק' יש כמ\"ש להנחיל אוהבי יש כידוע ומבואר למעלה דנוצר זה הוא בחי' אור ההמשכה שבהעלם ודקות כצינור דק וכדמיון השערה כו' כך החכמ' מאין תמצא בהעלם וזהו בחי' כח מ\"ה דחכמ' בבחי' אין והעלם דכתר ושרשו מחסד דע\"י שבגלגלתא כו' וזהו ענין המטר שנק' יורה שיורד בחשוון כנ\"ל שהוא בא רק ללחלח חלקי הארץ שיהי' מזה בחי' ביטול הישות של הגרעין ויוכלל בכח הצומח הרוחני כנ\"ל להפוך ולעשות מיש לאין להביא מן הגשם אל הרוחני בהעלאו' מ\"ן (ונק' כח המעלה מ\"ן כי יש בחי' מי חסדים שנק' מ\"ד שפעולמן לעשות העלאו' מ\"ן כידוע כך הגשמי' שנק' מ\"ד כידוע פעולתן לעשות כח העלאו' מ\"ן מן הארץ והוא לעשות רקבון הגרעין שיעלה כח הצומח שבחטה שנלקח מן כח הצומח שבארץ ויתבטל כנ\"ל ואח\"כ נמשך מ\"ד ממש לעשות"],[1700400230,"המילוי והתפשטות מאין ליש שהוא המלקוש כנ\"ל וזהו עיקר ההפרש ביניהם דהמטר בכלל נק' בחי' מ\"ד כמ\"ש בע\"ח ובכמה מקומות בענין מוריד הגשם דש\"ע אך יורה הוא בחי' מ\"ד שקודם העלאו' מ\"ן לפעול כח ההעלא' כנ\"ל ומלקוש הוא בחי' מ\"ד שאחר העלא' הצמיחה בבחי' אוח\"ח כו' אך לאופן זה לא יתפרש בענין ב' מזלות דמזל ונוצר הוא בחי' מ\"ד דאבא ומזל ונקה הוא בחי' מ\"ן דאימא שמגדל הולד בהתפשטות וריבוי כו' וכמשי\"ת ואפשר הן כמו בחי' ה\"ח המגדילי' דכמו שמקבל מזל ונוצר ממקורו כך מזל ונקה מקבל ממקורו וכענין אאלפך בינה כו') ויובן זה בהקדי' תחלה בבחי' כח מ\"ה דחכמ' שהוא בחי' אין דחכמ' הנק' ביטול ובאמת אין זה מובן מהו ל' ביטול דמשמע שיש מהות דבר מה במציאו' אלא שהוא בטל כענין מה פשפשת כו' שהוא ביטול ההשגה והרי בחכמ' עדיין למעלה מן ההשגה ואיך שייך שם ענין ביטול אלא הענין הוא ידוע דיש ב' מדריגות בבחי' אין א' בחי' אין העצמי כמו שהוא בבחי' פנימי' הכתר כמו היש ה' כו' אם אין והב' בחי' אין שעושה ליש אין דהיינו מה שיורד ונמשך מאין העצמי לעשות בחי' ביטול כל ישות לאין וזהו הנק' כח מ\"ה פי' כח שהוא בבחי' מה לעשות בחי' בטול כל יש לאין ומה כמו ונחנו מה שהיה בהם בחי' הביטול בתכלית כו' עד\"מ שנמשך ברואה את המלך ביטול היש לגמרי נק' המשכה זו המשכת הביטול וכן ע\"י בחי' ראיה דחכמה שהוא רואה עצם האין נמשך המשכת הביטול דיש ויש מי שבטל כו' ע\"כ יפול בזה מדרגות חלוקות ושונות זה בטל כך וזה כך כל א' לפי ערכו כו' (וכך למעלה בד' עולמות דאבי\"ע בכלל יש ד' מדרגות בכח מ\"ה חכמה דאצי' בחי' ביטול עצמי כו' וחכמה דבריאה ביטול היש עד חכמה דעשי' כו') וזהו ענין מזל ונוצר שהוא בחי' ההמשכה מאין העצמי דכתר להתהוות כח מ\"ה דחכמה וכמ\"ש והחכמה מאין כו' דהיינו התהוות כח העושה בחי' ביטול היש לאין שהוא הנק' מ\"ה (וזהו כולם בחכמ' עשית שהחכמה נק' עשי' שהוא לעשות כח מ\"ה זה) ה\"ז בא בבחי' המשכה כללית והוא ע\"י צינור דק בהעלם נמשך בחי' מקור לכל בחי' ביטול לאין שהוא כח מ\"ה ומהן כל עיקר פעולת המשכת אין זה דונוצר רק בשביל התהוות כח מ\"ה כו' שהוא בחי' נקודה דחכמ' שהיא העדר ההתפשטו' בהשגה כענין מה פשפשת בהשגה רק כברק כו' והוא הנק' יורה כמו מורה חץ שבא פתאום מההעלם לגלוי רק כנקודה א' וכמו ויצא כברק חיצו וכן ענין ושלשת החיצים צידה אורה שהן ג' גוונין דקשת דהיינו ג' טפות יסוד אבא כו' שכל שאינו מורה כחץ אינו מוליד עד\"מ הטיפה רוחניו' שבמוח היא מתהוו' מעצם כח המשכיל כמו חץ ואז יוליד בדומה לעצ' כו' (והטפה נמשכת למקבל לעשות העלאו' מ\"ן בחי' ביטול כו' ובאמת קודם שנקלטה הטפה ה\"ז כמו חטה הזרועה שבארץ שע\"י המטר המלחלח תוקלט היטב כנ\"ל ואין זה מתיישב בפי' ונתתי מטר כו' דלפי הנ\"ל המטר עצמו הוא המשכת הטפה שנק' יורה כחץ כו' וד\"ל):\n(נט) <b>והנה</b> ענין המטר השני הנק' מלקוש היורד בניסן הוא בחי' מזל ונקה כנ\"ל והוא להיפך גמור ממטר הנק' יורה כנ\"ל דהיינו שפעולת המלקוש הוא להיות התהוות והתפשטות יש מאין כמו במילוי ושמנוניו' החטים כנ\"ל וביאור הדברים הנה מזל ונקה נק' מזל התחתון וכמ\"ש במ\"א שזהו ענין ועוש' חסד לאלפים עשי' זו היפך ענין ונוצר חסד לאלפי' דונוצר הוא בחי' המשכת האין ומ\"ה דחכמה כנ\"ל והמשכה זו דעושה חסד כו' הוא להתהוות בחי' בינה שנק' יש דוקא שהוא בחי' מוח ההשגה והתפיסא להשיג כל מושכל במציאו' דבר מה בבחי' מורגש כי השגה לשון השגת יד כמו שתופס ביד כך נתפס אור המושכל בכלי ההשגה בהסבר טוב"],[1700400231,"טעם בהתפשטות אורך ורוחב כידוע שכל שאין האדם משיג בשכלו בכי טוב טעם לתכליתו אין לו עונג וחיות משכל זה כלל וכל שישיגנו בטוב יותר יותר יתענג ויקבל חיות כי בהשגה דבינה יש בה בחי' התפשטות וריבוי האור והחיו' במורגש (משא\"כ בחכמה בנקדוה המבריק כחץ כנ\"ל הנק' הבנה והמצאה אין בזה אור וחיות מורגש רק בהעלם ודקו' גדול מאוד כנ\"ל) וה\"ז ממש כדמיון המילוי בטוב בחטים בבריאות ומלאות ושמנונית הנ\"ל ברוחני וגשמי דהיינו בטוב טעמו וממשו הכל בהתפשטוץ גדול' כך העונג שבהשגה נק' טעמו הרוחני וממשו הוא התפשטות ההסבר לאורך ורוחב ועומק כו' (משא\"כ העונג שבחכמ' הוא בהעלם גדול וכנ\"ל בשמן שצף כו') וזהו להנחיל אוהבי יש דקאי בג\"ע ועה\"ב שהנשמות נהנין במורגש בהשגות אלקו' כידוע שהוא בא בבחי' ריבוי הטוב בהתפשטות העונג אלקי ברוחניו' כו' שנק' יש ממש והיינו מצד ההמשכה מאין ליש היפך ביטול היש לאין הנ\"ל וזהו ענין עושה חסד כו' שזהו ענין אאלפך בינה ע\"י בחי' מזל ונקה פ' אאלפך ל' עתיד כמו אאלפך חכמ' (דמ\"ש קנה חכמ' קנה בינה ב\"פ קנה גי' ש\"י הוא בבחי' חו\"ב שמקבלי' מב' מזלות דנוצר ונקה ואינו רק בחצי התחתון שבכתר גי' תר\"ך וזהו יש ש\"י עולמות והוא נכלל במזל ונקה אותיות קנה כמו קונה שמים כו' שמייחד לחו\"ב קנה חו\"ב כו' וכן זקן שקנה חכמה כו' ומפני שמתכללים חו\"ב יחד כמו הבן בחכמ' וחכם בבינה כמשי\"ת אבל מ\"ש אאלפך חו\"ב קאי בחצי העליון דכתר דהיינו מה שעתיד להיות מקור במזלות הנ\"ל) [ולהבין בתוס' ביאור הנה יש להקדים מ\"ש במ\"א בענין וכל העם רואים את הקולות כו' רואין את הנשמע ושומעין את הנראה שזהו בחי' התכללות דחו\"ב דראי' בחכמה ושמיעה בבינה ויש שמיעה דבינה בראי' דחכמ' (וזהו שומעין את הנראה) ויש ראי' דחכמה בבינה (וזהו רואין את הנשמע) והיינו ענין המא' הבן בחכמה וחכם בבינה כידוע וביאור זה הנה ודאי כמו שיש מקור מיוחד לחכמה שהוא המוח של בחי' ההבנה וההמצאה להשכיל חדשות (בל\"א בליצט כברק כו') כך ממש יש מקור מיוחד למוח הבינה הנק' תפסן ובעל השגה כידוע שאנו רואים דאע\"פ שנקוד' חכמה נמשך בהתפשטו' ליש בהשגה דלפ\"ז אין מקום להשגה בלא נקודה וא\"א לנקודה בלי התפשטו' בהשגה כמו שא\"א למעיין בלא נהר ונהר בלא מעיין וכה\"ג מ\"מ הרי אנו מוצאי' שיהיה אדם בעל הבנה מופלג ואינו בעל השגה ותפסן כלל כי להמציא המצאו' כלי מוחו מסוגל והוא בחי' מוח החכמה שהוא קר ולח וכלי מוח ההשגה והתפיסא אינו בטוב אצלו ע\"כ לא ישיג ריבוי דברי' וגם לא ישיג לעומק כלל רק מבחוץ (בל\"א פון אויבין מושכל ראשון וכו') והיינו קוצר המשיג לא לאורך ורוחב ולא לעומק כו' ויש אדם בעל השגה בעומק ואורך ורוחב ואינו בעל הבנה כלל להמציא שכל בעומק ואינו יכול לחדש כלום רק מה ששומע ולומד הוא משיג לעומק בתכלית ולאורך כו' (וגם יוכל להיות בעל עיון גדול לברר וללבן כל דבר על מקומו בתכלית ועכ\"ז לא יש חדשות לגמרי מצד קוצר כלי ההבנה) וכ\"ז מצד שאינם תלויים זב\"ז כלל לפי שיש לכל א' מקור מיוחד בפ\"ע ולזה יש מקור להבנה שבמוח החכמ' יותר מזולתו ולזה יש מקור להשגה יותר (ותלוי במזלות הנ\"ל מזל ונוצר כו' מזל מחכים להשכיל כנ\"ל והוא בחי' מוח החכמ' קר ולח ומזל ונקה להיות נובע ממנו כח ההשגה והתפיסה כו' בחי' מוח בינה שמזגו חם ויבש והמזלות מקבלי' מלמעלה) ועוד ראי' ברורה יותר ממה שאנו רואי' שיש בנקוד' חכמ' להטיב ולהרע כמו חכמי' המה להרע כו' דהיינו להטות כלפי חסד או כלפי דין והחכמ' מאין תמצא להמציא שכל לזכות ולפעמי'"],[1700400232,"תמצא מאין להמצי' שכל לחוב וכמו השוחד שיהפך מחוב לזכות כו' כידוע ונקודה זו אם לזכות או לחוב ודאי יתפשט בהשגה ועטם בהסבר כו' אמין ליש כנ\"ל ולפ\"ז הדבר מוכרח שמה שיחייב אור חכמה אם לזכות או לחוב מיד ימצא כן ממש במוח ההשגה ליתן טוב טעם לזה ובאמת אנו מוצאי' שיהי' בהשגה וטעם להיפך מחיוב המצאת החכמ' כמו שמצינו דאקשו ר\"כ ור\"א לרב וכי מה בין זה לעגל שנולד מן הטרפה שתיק רב וכה\"ג בכמה מקומות הרי לא מצא טעם בהשגה כמו שחייבה גזרת חכמתו לכך שתיק לפי שבטעם והשגה מורה להיפך ממש וכן ב\"ש אוסרי' וב\"ה מתירים והרי אם הקשו ב\"ה לב\"ש בטוב טעם יודו להם ב\"ש על הטעם וההשגה שאתם האמת ועכ\"ז לא יחזרו ב\"ש ממה שקבלו או מצד שכלם שמטה כלפי דין וכן להיפך מב\"ש לב\"ה וכה\"ג הרי השכל שיצא כלפי חסד בחכמ' לא יכריח להיות בהשגה כך אלא יוכל להיות להיפך וכן עוד ראי' ממה שמצינו שיש שכל הנמשך כברק בבחי' נקוד' חכמה הנ\"ל והוא בבחי' עומק גדול או שהוא להיפך בבחי' קטנו' וצמצום גדול כמו המצאת החכם הגדול והמצאת התנוק ובר שכל קטן או באדם א' עצמו לפי השעה והזמן וא\"א לומר לכאורה שבחי' עומק נקודת חכמה זו לא יתפשט גם במוח הבינה בהשגה בעומק מאחר שנמשך מאין ליש ובאמת מאחר שיש למוח בינה מקור מיוחד בפ\"ע המהוה לעצם מציאות כנ\"ל ע\"כ יוכל להיות דעומק שבחכמ' לא יתפשט בהשגה דהיינו שבהשגה אין לו עומק זה כלל וכן להיפך צמצום וקטנו' דחכמ' לא יכריח צמצום וקטנו' בהשגה אדרבה יוכל להיות בהשגה בהרחבה ועומק דוקא וראי' שגידול המוחין דחו\"ב מקטני' לגדלו' מתנוק קטן לזקן בן ע' יש שגידולו בהבנה דוקא ולא בתפיסה והשגה ויש שגידולו בתפיסה ולא בהבנה כו' וכנ\"ל דיש בנ\"א חלוקי' לגמרי בזה דזה בעל הבנה גדול ואינו תפסן כלל כו' וכ\"ז מפני שיש לכל א' מקור מיוחד לעיקר עצם מציאותו ואינם תלויים זב\"ז כלל ולכך חלק לכל א' במאמר בפ\"ע קנה חכמ' קנה בינה דמשמע שיש קונה חכמ' ולא בינה ויש קונה בינה ולא חכמ' וכן אאלפך חכמה אאלפך בינה ומה שא' אם אין חכמ' אין בינ' אם אין בינה אין חכמ' היינו כשמתכללי' יחד דודאי שני מקוריים מחולקי' הם כנ\"ל רק שמתייחדי' ומתכללי' זע\"ז אח\"כ כמו שמתייחדי' זו\"נ דזה מהות בפ\"ע וזה בפ\"ע רק שמתייחדי' זע\"ז כך ממש מוח אבא מהו' בפ\"ע ומתייחד במוח בינה והוא מה שאנו רואי' שיתפשט כל עומק אורך כו' דנקוד' חכמ' בהשג' ברוחב ועומ' וכו' בכל פרטי החלקי' כמו הצר צורה מצור' וכמו שעל הרוב ימצא טעם בהשגה ממש כאופן שהמציא לזכות או לחוב (ונק' ז\"ת דבינה מדו' שבהשגה שמלבישי' למדו' שבחכמה ונק' יחוד יש\"ס ותבונה כמה שכתב במ\"א וזה תלוי ביחוד דג\"ר דאו\"א בעצם ועצם הג\"ר כל אחד יש לו מקור בפ\"ע והן ב' מזלות אמנם גם הב' מזלות מתייחדי' ומתכללים וגם עד\"ז במקור המזלות שנק' מקור למקור כו') והנה מה שיקרא בשם נבון שלמעלה ממדריגת חכם כידוע דבימי משה נבונים לא אשכח כו' שהוא המבין דבר מתוך דבר כידוע זהו פלא גדול לכאורה דאם אין בו רק מוח ההשגה לעומק ולא בחכמ' למה יהיה למעלה מן החכם ואם הוא חכם למה יתוסף בשם נבון ומה שמבין דבר כו' אין זה רבותא כמו חידוש המצא' הנק' הבנה חדשה רק שמחדש דבר מתוך דבר שכבר שמע והשמיעה היא בבינה לבד כנ\"ל אלא זהו בא מצד ענין ההתכללות דחו\"ב כמא' הבן בחכמ' כו' הנ\"ל דודאי כשמתכללים חו\"ב יחד כנ\"ל הנה בהכרח שימצא מציאת בינה בחכמה וזהו הבן בחכמה וימצא מציא' חכמה בבינה וזהו וחכם בבינה והיוצא מאמצעו' התכללות זו הוא הנק' נבון שמבין דבר כו' שלמעלה מן החכם וביאור"],[1700400233,"הדבר ידוע דבינה שבחכמה הוא מה שיוכל אדם להביא כל נקוד' חכמה בהסבר שזה כח מיוחד לעשות מאין ליש שהוא מזל ונקה כנ\"לו חכם בבינה הוא עומק ותמצית כל אריכות ההסבר שזהו בחי' ביטול היש לאין שכל ישות ההשגה נעשה בבחי' אין ותמצית כו' וזהו מזל ונוצר שעושה מיש אין ונמצא החכמה פועל פעולת הבינה ובינה פועל פעולת החכמה שמחליפי' פעולתם זע\"ז וזהו עיקר היחוד וההתכללות כידוע בענין לאכללא שמאלא כו' כאור החסד בכלי הגבו' כו' ויוצא מזה דבר שלמעלה משניהם והוא הנבון שמבין דבר חדש מתוך דבר שזהי רבותא גדולה מהתחכמות חדשה לגמרי כי הדבר שהבין כבר הוא בבינה שכלולה מחכמ' והולדת דבר חדש שמבין מתוך דבר ששמע הוא בחי' החכמ' שכלולה מבינה כענין הבן בחכמ' ע\"כ יוכל להוליד דבר מדבר משא\"כ החכם לא יוכל להוליד מדבר ששמע כלום כ\"א לחד' דבר אע\"פ שהוא מבין בחכמ' אם לא שהוא חכם בבינה וכן גם החכם בבינה אם אינו מבין בחכמה לא יוליד להבין דבר חדש מדבר ששמע כ\"א להשיג התמצית ולברר וללבן ולהפריד דבר מדבר שנק' עיון שהוא בחי' פנימי' בינה כו' רק מי שכלול משניהם להבין בחכמ' וחכם בבינה הוא הנבון שיבין דבר מתוך כו' שזהו מצד שרש התכללות ב' המזלות דונוצר ונקה בשרשם דוקא ולכך נבונים דוקא לא אשכח מטעם הנ\"ל וד\"ל:\n(ס) <b>וזהו</b> וכל העם רואים כו' רואין את הנשמע פי' שמיעה שבבינה ראו בראי' דחכמ' והוא ענין וחכם בבינה שכל שמיעה והבנה שבהשגה ותפיסא הנק' יש ראו בבחי' ראי' דחכמ' הנק' אין והיינו בחי' ביטול היש לאין שע\"י מזל ונוצר כנ\"ל ושומעין את הנראה שמיעה דבינה שמעו את הנראה בבחי' חכמה היינו הבן בחכמה שנקודת חכמ' מתפשטת בישות ההסבר כנ\"ל שזהו פעולת מזל ונקה הנ\"ל לעשות מאין יש והוא בחי' יחוד והתכללו' הב' מזלות דחו\"ב להיות כ\"א פועל פעולת זולתו ההפכי שהבן בחכמ' כו' כנ\"ל מתכלל בחכמ' פעולת הבינה וכן חכם בבינה שהבינה עושה פעול' החכמ' מתכלל פעולת החכמ' בבינ' ולזה גזרו או' דאם אין חכמ' כו' דודאי לאחר התכללות שרש הב' מזלות יחד כנ\"ל א\"א שיהי' מציא' חכמ' בלא בינה ולא בינה כו' וכמא' או\"א תרין ריעין דלא מתפרשין לעלמין כחדא שריין וכחדא נפקין וד\"ל [וכדוגמא זאת אנו מוצאי' בענין שער החמשי' דבינה שכלול מחו\"ב יחד לזאת לא זכה משה לבינה שהוא שער החמשים עד במותו ולא בחייו וכמ\"ש ותחסרהו מעט כו' וכמ\"ש במ\"א בענין ולא ידע איש את קבורתו לעליונים נדמה להם למטה פי' לעליונים שבבחי' אין דחכמה נדמה להם שהוא בבחי' יש דבינה והיינו כענין שומעי' את הנראה דלעיל שהוא הבן בחכמ' ולתחתונים שבבחי' יש דבינה נדמה להם שהוא למעלה בבחי' אין דחכמ' והוא כענין רואים את הנשמע בחי' חכם בבינה כו' לפי ששער הנ' כוללם יחד להיותו מבחי' מקו' הכולל לב' מזלות הנ\"ל וזהו בחג השבועו' שאז נתגלה כתר תורה שזהו בכתר דאו\"א (מבחי' חציו העליון שכולל ש\"י ב\"פ מאין ליש ומיש לאין כא' ממש וד\"ל) (ומה שלא זכה משה בחייו כמ\"ש בזוהר היינו שלא בא בבחי' גלוי גמור בגופו ונשמתו רק הי' בהעלם ומקיף) [וב' כתרים דנעשה ונשמע שהוא כולל כתר וחכמ' זה הי' קודם חטא העגל וידוע דאותיות ונוצר בהפוך אותיות רצון וב' מיני רצון שבחו\"ב כלול במקור כל רצון ולזה תקין ונוצר אחר תיקון ואמת שהוא הארת תרין תפוחין דחכמ' אדם תאיר פניו מאור עצמות הרצון והעונג ושרשו במזלא דכולל הכל והוא אל ארך כו' ולכך כללו רז\"ל במאמר סתום הכל תלוי במזל סתם אפי' ס\"ת בהיכל שהוא שרש יחוד ב' מזלות הנ\"ל] ומעתה הנה לא יתיישב לכאורה פשט הכתוב דונתתי מטר ארצכ' בעתו יורה"],[1700400234,"ומלקו' דודאי יור' ומלקו' באין בשני זמנים רחוקי' זה בחשון וזה בניסן כנ\"ל ולפי הנ\"ל בענין יחוד והתכללות דב' מזלות ונוצר ונקה הרי אם אין חכמ' כו' ואיך יוכל להיות כ\"כ בהתחלקו' יורה בחשון ומלקוש בניסן אמנם הענין יובן בהקדים תחלה להבין פי' דבעתו מהו בעתו דוקא דהנה לכאורה רישא וסיפא דקרא אינן מכוונין זע\"ז דרישא משמע ונתתי מטר סתם כולל כל מיני מטר וסיפא משמע התחלקות מיני מטר יורה ומלקוש ואם נפרש דבריו כך דמטר יתן בעתו כל מטר בזמנו יורה בחשון ומלקוש בניסן דלאו רבות' הוא כ\"כ דודאי ב' מיני מטר הן רק שזמנם בחשון וניסן שלא לאחר ולהקדים הזמן דיורה ומלקוש ואין בפי' בעתו רק דבר זה לבד אלא הכונה גם בהתחלקו' מיני מטר כל א' בעתו דוקא ולא יחליפו פעולתם ולא עתם אלא מוכרח לומר דעתו זה כולל הוא והוא ענין יחוד והתכללות דב' מזלות הנ\"ל בשרשן נק' עתו עת וי\"ו דוי\"ו הוא בחי' המשכה כללית והיולית כמו הקו הנמשך מלמעלה למטה ואח\"כ ממשיכי' אותו לאורך ורוחב כפי שירצו ולכך יש עתים רבים כמו ואל יבא בכל עת כו' ויש עת רצון ויש שאינו עת רצון כו' וכל העיתים נמשכי' מוי\"ו הכוללם יחד והוא בחי' מקור ההיולי הפשוט מבחי' בעל הרצון שנמשך למטה בדרך כללו' ההמשכה ושם הוא יחוד ב' מזלו' הנ\"ל ואח\"כ מתחלקי' זה בעת זו וזה בעת אחרת מזל ונוצר בעת הזריעה לעשו' בטול היש והוא בחי' המשכת האין דחכמ' כנ\"ל הנק' יורה וכענין אאלפך חכמ' כו' ומזל ונקה בעת הצמיחה בניסן לעשו' התפשטו' יש מאין שהוא המלקוש כנ\"ל ובאמת הכל א' דמפני בחי' בטול היש לאין במזל ונוצר כך יהי' המשכ' מאין ליש במזל ונקה וכך הוא מפני בטול הזריעה מיש לאין ע\"י יורה בחשון ע\"כ נמשך בניסן התפשטו' מאין ליש במילוי התבואות שע\"י מלקוש והא בהא תליא ובאמצעות שניהם נעשה שלימות הדבר וזה בלא זה אינו כלום לכך אמר ונתתי מטר ארצכם שכולל ב' מיני מטר יחד בעתו עת וי\"ו כנ\"ל ואח\"כ מתחלקי' יורה בחשוון ומלקוש בניסן אבל גם בהתחלקותן כל עיקר יורה בעתו אינו רק בשביל מלקוש כנ\"ל והיינו אם אין חכמה כו' שאם אין בטול כו' והכל א' ממש גם לאחר התחלקותן משום דכלולים בשרשן וכנ\"ל דכחדא שריין כו' כענין הבן בחכמ' כו' ומתיישב ריש' וסיפא דקרא הכל בענין ושרש אחד התכללו' והתחלקות שניה' אחד וד\"ל וזש\"א אאלפך חכמ' כו' דמשרש א' מתחלקים ואאלפך חכמ' בפ\"ע כו' ועכ\"ז כלולי' שחכמ' זו בחי' בטול יש לאין כדי שיהיה מאין ליש שהוא אאלפך בינה וכן קנה חכמ' כו' וב\"פ קנה ש\"י וב\"פ ש\"י תר\"ך שזהו בעתו עת וי\"ו שכולל הכל כנ\"ל וד\"ל וזהו שסמך פסוק דואספת אחר ונתתי מטר כו' דהא בהא תליא דמטר יורה ומלקוש שנמשך בעתו כנ\"ל מזה נמשך למטה מטה ב' מדריגות דיין ושמן שהן תירושך ויצהרך שנמשך מבחי' חו\"ב דאצי' בגלוי למטה מטה בבי\"ע כו' ומתכללי' ג\"כ כו' ויין גי' סוד להביא מאין ליש ושמן בחשאי ובטול מיש דאין כו' שהוא בחי' המשכת אין ומ\"ה דחכמה כנ\"ל והיינו ג\"כ ענין תושב\"כ ותושבע\"פ ספר וספור דתושב\"כ בבחי' העלם ואין דחכמה ותושבע\"פ בבינה בחי' יש וע\"ז א' קנה חו\"ב וד\"ל והנה ידוע שהמטר מתהווה מן האדים שבארץ העולים מלמטה למעלה ונק' קטור הארץ ונעשה מזה עננים ועבים וענין העבים הללו היינו שלחלוחית האדם שבהם מתגשמים ויורדים למטה והוא כשהענן חשוך לפי שמתגשם ביותר חלקי המים ונעשה ענן כבד משא\"כ עננים העולים למעל' ומתפזר לדקות החלקי מים שבהם ואמנם זאת אשר לפעמי' יורד מטר מן העבים ולפעמים לא ירד מטר כלל הענין הוא שהמים שבעבים מובלעים שם בהעלם גדול והיינו שנעצרים שם זמן רב עד שיצא המטר"],[1700400235,"שהוא יורד כמו קו לבד כנ\"ל ולפעמי' נשארים שם בעבים בהעלם כי נעצרים שם בלתי יצאו בהגשמת מים וכמו ועצ' את השמי' ולא יהיה מטר [כי הגשם מן השמי' יורד וכמ\"ש אני אענה את השמים כו' וכן כי כאשר ירד הגשם מן השמי' ושמה לא ישוב כו' ולהיפך ועצר השמים כו' לפי אופן השפע האלקי הרוחניו' שנמשך ממזלו' שברקיע כמו חלקה א' תמטר כו') וזהו ונתתי מטר ארצכם ע\"ד הפשוט שתלוי בדעת הנותן מטר וכמו מעלה נשיאים כו' ברקי' למטר כו' מוציא רוח כו' שמשיב הרוח ומוריד הגש' אם ירצה ואם לא ירצה ועצר את השמים כו' שנשארי' המים בבחי' ההעלם ואמנם הנה גם אם ירצה ליתן מטר הרי מתחלה מובלעי' המים בהעלם ונעצרים בעבים זמן מה עד שירדו למטה ונמצא שיורד מן ההעלם והצמצום לגלוי מטר בקו וחוט כו' ובלא צמצום והעלם המים בעבי' תחלה אין המטר יורד כך יובן למעלה במ\"ש ונתתי מטר שיורד מן הצמצום והעלם ולא ישאר שם בהעלם ועוצר כו' ולמעלה יובן זה בבחי' העלם עצמות אור הכתר שנק' עה\"ע דגם אור צח ומצוחצח שהן כמו בחי' ב' מזלות הנ\"ל מתחשכאן קמי' כו' כמ\"ש ישת חשך סתרו וכתיב מגלה עמוקות מני חושך ובחי' חושך זה הוא בחי' העלם החכמה עליונה כשהיא בתכלית ההעלם כמים המובלעים בעבי' וכמ\"ש חשכת מים עבי שחקים פי' חשכת מים שהמים חשוכים בבחי' חושך והעלם עצמות אור הכתר כמ\"ש ישת חושך סתרו נק' חשכת מים כו' שנעלמים שם לגמרי (והוא בחי' סוד סתום הנ\"ל וכמו בחי' רדל\"א כו') ואמנם אחר הצמצו' וההעל' דחכמ' הקדומה שבעצמות ממש יוצא ובוקע כמטר והן כמו בחי' ב' מזלות ונוצר ונקה כנ\"ל שנמשל לקוין דמטר וכל הצמצו' והעלם זמן מה הוא כדי שירד בחי' מטר זה דמזלות שזהו כמו שידוע בענין ברישא חשוכא והדר נהורא דח\"ע כמ\"ש יהי אור והיינו אור צח ומצוחצ' כמו בחי' ונוצר ונקה כו' (או כמו אאלפך חו\"ב וקנה חו\"ב הנ\"ל) (ומה שאמ' ר\"ע לתלמידיו כשתגיעו לאבני שיש טהו' א\"ת מים מים הוא היפך זה דאבנים שחקו מים הוא חלק הדומם שבמים ולכך מאבן וצור יצאו מים אך אבני שיש הוא הזדככות חלקי הדומם עד שידמה האבן כמים ממש והן אבני שיש טהור ובאמת הן ג\"כ בחי' דומם שהמי' שם בהסתר וצמצום ולכך הזהירם א\"ת מים מים והן שרש ב' מזלות דחכמ' ובינה הנ\"ל אבל אבנים מפולמות היינו שמפולש בהן יציאו' המים מהעל' לגלוי הוא כדוגמת ב' מזלות שיוצא השפע מהעלם לגלוי כמו החכמ' מאין תמצ' וזהו אבנים שחקו מים שעש' בהן נקב כו') והנה ארז\"ל דנובלו' חש\"מ תור' ופי' נובלו' הן כמו בחי' מזלות דהיינו כמו בחי' שערו' שיוצ' ובוקע מצד התגברו' ביותר יוצא מותרות ונובלות וכן המטר בסיבת התגברות המים בעבי' יורדין בגבורה בבחי' בקיעה כמו קו כו' לכך שבח הח\"ע דתורה יותר נעלה בשרשו והוא שיוצא האור דתורה מתוך ההעלם והחושך דענן כמו במ\"ת שהי' ענן כבד וחושך וערפל ומשם דוקא בא אור דתורה לפי ששרש אור דתורה מעצמות החכמ' שבהעלם עצמותו ממש כמ\"ש ואהי' אצלו אמון שעשועי המלך בעצמות ממש ויוצא דרך נובלו' ובקיעה מתוך החושך והערפל שהוא בחי' חושך סתרו הנ\"ל וכמ\"ש מגלה עמוקות עמוקות עומק לעומק עמקות ח\"ע שהן מקוריים לב' מזלות מני חשך דוקא ולזה אמ' יערוף כמטר לקחי כו' והיינו ונתתי מטר כו' בדרך מתנה שהתורה נתנה במתנה מבחי' רב חסד העליון שיורד מגבוה לנמוך מהעלם העצמות לגלוי שע\"ז נאמר כיתרון אור מתוך החושך דוק' וד\"ל וזהו בפ' שניה שמקבלי' עול מצות וסוף מעשה עבמ\"ת שהוא בתענוג הפשוט שבעצמותו ממש לכך ע\"י נר מצוה דוקא יבא אור דתורה מהעלם לגלוי שהוא מן בחי' החושך הנעל' לאור כנ\"ל וכמ\"ש יהי אור אור דתור'"],[1700400236,"וזהו ונתתי מטר בפ' שניה דוקא וד\"ל:\n(סא) <b>ומעתה</b> יש להבין מ\"ש ונתתי עשב בשדך לבהמתך כו' שא' אחר אכילת אדם דואספת דגנך ותירושך כו' ואכל' ושבעת דהנה אמרז\"ל אסור לאדם לאכול קודם שיתן מאכל לבהמתו שנא' ונתתי עשב כו' והדר ואכלת כו' ולהבין זה יש להקדים תחלה ביאור ענין עשב דהנה ידוע דעשב הוא שי\"ן ע\"ב שהוא שם ע\"ב דהנה לכאורה יש סתיר' לזה דבכאן משמע דעשב מאכל בהמה וכתוב מצמיח חציר לבהמה ועשב לעבודת האדם ואם חציר ועשב ב' מינים הם עכ\"פ מאכל בהמה שניהן ומה זה שא' ועשב לעבודת האדם אך הענין הוא דאינו אומר ועשב למאכל האדם אלא לעבודת האדם ופי' עבודה הוא תיקון ושירות והיינו ענין העבודה דאדם שבצלם האלקי' בפסוד\"ז לזמר בשבחו של מקום כעבודת המלאכים שעליהם א' מצמיח חציר לבהמה גי' ב\"ן כו' ולכך עשב שם ע\"ב כו' ויובן זה בהקדים ענין הפסוק דמצמיח חציר כו' שא' בזוהר דהיינו בחי' ב\"ן גי' בהמה רבה דרביעי' על אלף טורין דמגדלין בכל יומא ושתת לון בגמיעא חדא כו' וידוע שזהו בחי' ברורים דרפ\"ח כו' שנפלו בנוגה שהמל' בחי' ב\"ן מבררת אותן בכל יום והוא שנבלעים ונכללי' בחי בהמה עליונה כו' וחוזרים וצומחי' מדי יום וחוזרים ונבלעים כו' וזהו מצמיח בכל יום חציר לבהמה עליונה שתבלעם כו' וביאור הדברים ידוע שזהו כמו ענין יוצר משרתים שבכל יום כו' שזהו העלאו' מ\"ן דמל' שלא ע\"י אור הזרוע מלמעלה מיסוד ז\"א כו' כמו החציר שצומח מן הארץ מכח עצמה עפ\"י מאמר תדשא הארץ דשא כו' וקוצרים אותו וחוזר ומצמיח עד אין שיעור כך בחי' העלא' הנצוצו' שנפלו בנוגה שעולין מעצמו בבחי' בטול היש לאין כדוגמת הגרים שעולין נצוצו' קדושות בהתעוררו' עצמם מאוה\"ע שנפלו שם ונכללים בשכינה כנר כו' כך יש ענין בירורי' מנוגה בכל יום שמזה נבראו מלאכי' בכל יום ועולין בבחי' ביטול היש לאין האלקי ונבלעו בפי בהמה בחי' ב\"ן שנק' רוח הבהמה שיורד למטה בהתלבשות ע' שרים לברר כו' וזהו יוצר משרתים שנתבטלו ממציאותם בכל יום ונבלעים ברוח פיו העליון כמ\"ש ושתת לון בגמיעא חדא כו' (וכמו בירור חלקי דצ\"ח שבאדם בכל יום כמו באכלו מאכל ועולין לה' אחד במס\"נ שלו כו') ולפי שברורי נוגה מתחדשים בכל יום ע\"כ א' מצמיח חציר בכל יום בשביל בהמה בחי' ב\"ן העליון וכמו הקציר של שחת כו' אך הנה אמר מצמיח לשון מפעיל דוקא הענין הוא משום דמה שיש כח בארץ להוציא צמח העשב והחצי' בלא זריעה כלל זהו בא ונמשך מלמעלה כח ועוז בארץ שתוכל להוציאה צמחה העצמי כמו עפ\"י מאמר תדשא הארץ דשא כו' כך אמר ונתתי עשב בשדך כו' פי' אני הוא הנותן עשב זה בשדך כו' כי הנה ידוע דבחי' המל' נק' שדה ואית שדה כו' שדה העליונה בחי' מל' דאצי' שנק' חקל תפוחין כו' וכמו כריח שדה אשר ברכו ה' כו' שצומח בה כל תבואה או כל מיני פירות טובי' כחקל תפוחין וכו' וזהו בחי' המל' בעלייתה מלמטה למעל' כשמתברכת מאור הזרוע לצדיק עליון שעושה פרי למעלה מכל מיני אור עונג וטעם האלקי כתפוחין קדישין וכל ריח פרי טוב וכמו ויטע ה' כו' ויצמח כו' טוב למאכל כו' ואמנם כשהמל' יורדת למטה בע' שרים דנוגה נק' שדה חריבה וכמו שא' בזוהר ע\"פ ואם בשדה מצא' והחזיק בה כו' ואעפ\"כ כח העלאו' מ\"ן יש במל' מעצמה לברר בירורי נוגה כנ\"ל בענין מצמיח חציר כו' (וכמו ענין גלות ישראל בע' שרי' שאלקו' בהסתר גדול לא נראה שם אור זרוע כלל כמדבר כו' מ\"מ מתעוררי' בתשובה ומע\"ט מעצמם כי שכינה עמהם כו' והוא ענין ספיחי' כו' וכמו דוגמת הגרים שעולין מע' אוה\"ע כנ\"ל)"],[1700400237,"וזהו פי' עשב לעבודת האדם שזהו עבודת האדם העליון בחי' מ\"ה שימשיך כח ועוז במל' שנק' שדה שיהי' לו כח להעלות ברורי נוגה הנק' חציר כו' וכמ\"ש תנו עוז לאלהי' שם ב\"ן כו' ובחי' המשכה זו הוא משם ע\"ב גי' חסד והיינו שי\"ן ע\"ב דג' קוין שבשי\"ן הוא במל' ובאין בבחי' קטנו' המוחין רק כדי לברר לנוגה הנק' חציר כנ\"ל אך שרש המשכה זו מבחי' ע\"ב חסד דז\"א (כמו הנה ה' רוכב על עב קל דע\"ב דמל' נק' עב קל דנשי' דעתן קלות דקל חצי המספר ס\"ר דדכורא שהוא ה' הויות דה\"ג דנוק' כו' וכידוע דג\"פ ע\"ב גי' רי\"ו ורי\"ו גי' גבורה וכ\"ז במל' שנק' גבורה תתאה ושרשם מגבור' עלא' דז\"א וכמו שאמ' מי ימלל גבורות ב' גבורות והן ב\"פ ארי' דארי' ג\"כ גי' גבור' והוא אותיו' ראיה דח\"ע וח\"ת חכמה בראש ובסוף כו' וג' פסוקי' דויסע ויבא ויט היינו ג\"פ ע\"ב דמל' והו' שין דעשב זה שניתן בשדה העליונה ולמעלה כו' וד\"ל) והנה להבין בתוס' ביאור ענין זה למעלה הנה יש להקדים בענין נפש הבהמית שבאדם למטה שע\"ז אמרו שיתן אדם מאכל לבהמתו תחלה בפסד\"ז כנ\"ל דהנה מבואר בע\"ח בשרש נפש דנוגה שממשיכין אב ואם בתאות זווג הגשמי נמשך משמרי האופנים שהן שפע המזלות (ומה שמלאך הממונ' מכריז טפה זו היינו בבחי' אלקו' שהוא אם חכם גבור ועשיר וצדיק ורשע לא קא') וזה נמשך מיד בהולדו דהיינו ביצירת הולד בבטן כו' אך הנפש אלקי' לא נמשך עד היותו בן י\"ג שנה שאז יש לו נשמה בבחי' דעת שכלול חו\"ג כו' (ולא שעד י\"ג שנה אין לו נשמה אלקי' כלל שהרי הו' ישראל לכל דבר כגדול רק שאינו בר עונשין כו' אלא שהנשמה שלו בבחי' קטנות והעלם ולא בגלוי עדיין שהרי אמרז\"ל ג' שותפין כו' והקב\"ה נותן בו נשמה הרי נותן נשמה ביצירת הולד וכן מבואר ממ\"ש אין צור כאלקינו כו' ובכמה דוכתי כמו שאמ' מלמדין אותו כל התורה כו' ובה\"ג) והענין הוא דיש ג' מדריגות נר\"נ ונו\"ר הוא בחי' קטנות המוחין שבמדו' לבד וזהו עד י\"ג שנה דנה\"ב בקטנות זאת משמרי האופנים ונה\"א בקטנו' מאופני' עצמן וכידוע דהאופן בעשיה שזהו קטנו' וחיצוניות המדות דמל' כשמקנן בעשי' (וז\"א ביצי' בגדלות המדות כו') וביאור הדברים ידוע בענין קטן אין לו מחשבה שבהיותו בן יג\"ש הן ולאו חלוקי' ורחוקי' זמ\"ז לפי שהדעת מחלק ומאיר בתוקף בחו\"ג ועד כ' שנה נעשה שלימות גידול המוחין במדות כו' ועד יג\"ש הוא בבחי' נו\"ר שהוא בקטנו' המוחין שבמדות חו\"ג ע\"כ אינו בר עונשין וזהו שקטן אין לו מחשבה ודעת במדותיו שחו\"ג שבו יתחלפו בנקל מהן ללאו כו' וכמוחלט בדבריהם ז\"ל דנשים וקטנים לאו ב\"ד (אך נשים דעתן קלות עכ\"פ בה\"ג דדעת כו' כנ\"ל) (ומבן כ' ואילך נמשך גידול עצם המוחין שלמעלה מן המדו' הנק' אדם פנימי והוא בחי' חי' יחידה וגם בחי' ג\"ר דחו\"ב שלמעלה משכל השייך למדו' לכך מבן כ' ואילך יודע כו') ונמצא עכ\"פ ששרש המשכ' מדות טבעיו' לנה\"ב שבאדם משמרי האופנים הוא עד היותו יג\"ש וכן אוי\"ר טבעיי' (עם קטנו' המוחין השייכי' לזה לבד) שנמשך מהאופנים עצמן כנ\"ל הכל הוא עד יג\"ש וע\"ד כ\"ז יובן בהפרש שבין פסוד\"ז ושתים לפניה לק\"ש עצמה דבפסוד\"ז ושתים לפניה ההמשכה הוא לנה\"ב שבאדם שיהי' לה ג\"כ כח לסדר שבחו של מקום כמלאכי' עליונים שנק' חיות ובהמות כו' והוא כמו בחי' קטנו' המוחין שבמדו' אוי\"ר טבעיי' שבנ\"הא כו' ששרשם באופני' שבעשי' לבד כנ\"ל ואח\"כ בק\"ש מדבר בנשמ' עצמה שלמעל' מבחי' נו\"ר דמלאכי' באמר' שמע ישראל דוק' שזהו כמו מבן יג\"ש ואילך שיש בו דעת דנשמ' כנ\"ל וז\"ש רז\"ל שאסור לאדם לאכול אכילת אדם זה קאי בנשמ' שנק' אדם אדמה לעליון בצלמינו כדמותינו ממש משא\"כ אכילת בהמה גי' ב\"ן שהן כמו המלאכי' שזהו כקרבנו' העולין ע\"ג המזבח ונק' אכילת"],[1700400238,"מזבח כו' עד ענין בירורי נוגה שנק' חציר הנ\"ל וכמו שאו' ביוצר אור איך שהאופנים וחיות כו' עד שיתן מאכל לבהמתו נה\"ב משמרי האופנים וכן לבחי' קטנו' דנה\"א שהוא בחי' אוי\"ר טבעיי' שהוא מהאופנים וחיות עצמן אז יוכל לאכול אכילת אדם דנשמ' עצמה בק\"ש כו' וד\"ל וזהו שבפ' שני' דק\"ש אמר ונתתי עשב בשדך לבהמתך תחלה דהיינו שיהי' כח ועוז במלאכים וגם בקטנו' דנה\"א עד נה\"ב שבאד' למטה שיוכלו לעלות למעלה זהו אני הנותן עשב בחי' שם ע\"ב דחסד שיורד מגבוה לנמוך ביותר עד קטנו' המדו' דמלאכי' ושמרי אופנים שמתברר מנוגה שנק' חציר כנ\"ל שכ\"ז נק' מאכל לבהמתו בחי' בהמה דאדם וכמ\"ש דוד ואני בהמות הייתי עמך בדו\"ר טבעיי' דוקא ואז יוכל לבוא לאכילת אדם שהוא התקשרות הנשמה האלקי' בגדלות המוחין וזהו שאמרז\"ל והדר ואכלת ושבעת כו' דקאי על ואספת דגנך תירושך ויצהרך דסמיך לי' שהוא בחי' חו\"ב דגדלות המוחין שנק' יין ושמן כמשי\"ת וכן דגנך בחי' טעמי' שנק' מאכל אדם כמאמרז\"ל אין התינוק יודע לקרות או\"א עד שיטעום טעם דגן דוקא וכמשי\"ת בסמוך בעז\"ה וד\"ל:\n(סב) <b>והנה</b> אחר שנתבאר דרך פרט ענין יחו\"ע ויחו\"ת דפסוק ראשון דשמע ובשכמל\"ו וענין ב' פרשיות דק\"ש מעת צ\"ל בתוס' ביאור בדרך כלל ענין יחו\"ע דאחד ויחו\"ת דועד וענין ע' רבתי דשמע וד' רבתי דאחד (כמ\"ש בזהר סי' לזה ה' עד כו') וצריך להבין תחלה ענין ועד שהוא בחלופי אתוון דאחד: הנה ידוע שמן הא' דאחד נעש' וי\"ו בועד ומן החי\"ת דאחד נעשה עין בועד בחלופי אתוון ומן הדלי\"ת דאחד לא נעשה שינוי כלל אלא אותו הדלי\"ת רבתי דאחד הוא הדלי\"ת קטן שבועד כו' והנה להבין כ\"ז יש להקדים תחל' להבין מ\"ש במ\"א בציור תמונת אות האלף דהנה ציור תמונתו הוא שני יודין וביניהם קו שהוא באלכסון והוא הוי\"ו שבין ב' יודין יוד העליון הוא בחי' חכמה שבחכמה או כתר שבחכמ' והוי\"ו הוא בחי' מדו' שבחכמ' ויוד התחתון הוא בחי' יסוד שבחכמה וכמבואר בס' הקבלה ולפ\"ז כל עיקר אות הא' בכלל אינו אלא בחכמה רק שתמונתו בפרט הוא פרטי' הע\"ס שבחכמ' ובכמה מקומו' בזהר וס' הקבלה משמע מפורש ששרש אות הא' הוא בבחי' הכתר דוקא וכמו שמבואר בזהר דא' רישא דכול' כו' ולפ\"ז פרטי ציור תמונתו בב' יודין והוי\"ו הכל הוא בבחי' הכתר עצמו דהיינו חכמה שבכתר ומדו' ויסוד ומל' שבכתר וכן הוא האמת לפי הפשט ופירוש דאות האל\"ף בדברי רז\"ל אאלפך חכמה אאלפך בינה הרי ל' זה משמע להבא שעתי' ללמד (כנ\"ל בסי' נ\"ט) דהיינו שעתיד להיות ממנו התהוות מציאת החכמה מאין ליש ועדיין לא נמצא כו' וכמו פי' אהיה אנא זמין לאתגלא' כו' שהוא בבחי' הכתר שהוא בבחי' ההעלם וידוע דהחכמ' נק' ראשית הגלוי ונמצא שב' הענינים הנ\"ל ב' הפכי' הם ובאמת שניהם אמת דודאי זה אמת דאות אל\"ף בכתר כדברי הזהר ואמנם ידוע שבחי' אור הכתר הוא בחי' ממוצע בין עצמות המאציל לנאצלים דהיינו שיש בו מבחי' האחרונה שבעצמו' ממש וממנו נמצא שרש וראש לנאצלי' כו' וע\"כ הוא המחב' לבחי' העצמו' להיו' נמשך למט' להיות בבחי' מקור לנאצלים וכדרך כל ממוצע שהוא מחבר העליון בתחתון ודרך פרט הנה בכתר עצמו כלול מע\"ס ובחי' כתר שבכתר הוא נחשב מסוף עולם הא\"ס ובחי' חכמה שבכתר נעשה מקור ושרש להתהוות הנאצלים כו' והוא הנק' ח\"ס דא\"א וע\"י כידוע והוא יוד שע\"ג הקו שבאלף שהוא בחי' חכמה שבכתר והוי\"ו הוא מדות שבחכמה שבכתר כו' (משא\"כ ציור אות היו\"ד בעצם הוא בבחי' חכמה וקוץ העליון שבו כתר שבחכמה כידוע וגם מילוי שלו וי\"ו דלית הוא ע\"ס דחכמ' שבאי' בגלוי אבל ב' יודין שבאלף שנק' חכמ' בראש וחכמ' בסוף הכל הוא בבחי' הכתר) ויו\"ד שתחת הקו הוא חכמ' בסוף שנמשך מן המדות שבח\"ס"],[1700400239,"הנק' בחי' יסוד שבחכמ' דא\"א וכה\"ג ואמנם מפני שעתיד לבא ממני מציא' החכמ' בגלוי שהוא בחי' אור אבא דאצי' ע\"י מזל ונוצר כמשי\"ת בפי' אאלפך כו' לכך גם זה אמת דהאלף בחכמ' כלומר בחי' מקור להתהוו' החכמ' שעתיד להיות ממנו התהוות החכמ' מאין ליש כנ\"ל בפי' אהי' כו' וזהו כללו' ענין אות האלף שהיא בבחי' ממוצע בין עצמו' אא\"ס שלמעלה מעלה גם מהיות בחי' מקור לחכמ' כמ\"ש אנת חכי' ולא בחכמ' ידיעא כו' ובין בחי' אור החכמ' עצמה שנק' ראשית הגלוי דהיינו שבה דוקא הוא ראשית גלוי אא\"ס והיינו ע\"י הממוצע הזה שהוא אות האלף שהוא מביא ומחבר לעצמו' אא\"ס להיות מקור להתהוות החכמ' וזהו אמיתית פי' דאאלפך שע\"י אות אלף עתיד להיות התהוות החכמ' מאין ליש וכמ\"ש והחכמ' מאין תמצא כידוע ונמצא יש באלף מעצמו' אא\"ס שלמעלה מן מקור החכמ' וגם מבחי' מקור לחכמ' והנה בחי' חכמ' שבכתר שהוא מקור להתהוות אור החכמ' דאצי' כנ\"ל נק' פלא ונק' אלף והן ב' הפכי' דפלא ל' נסתר שא\"א לבא לגלוי כלל והוא בחי' פנימי' ח\"ס דא\"א וע\"י כו' שנחשב עם בחי' הכתר עצמו שהוא מבחי' אחרונה שבעצמו' שלמעלה מהיות מקור לחכמ' כנ\"ל לכך נק' פלא כמו כי יפלא ממך כו' וכמו במופלא ממך אל תדרוש ונק' בלשון הגאונים שכל מופלא שכל הנעלם מכל רעיון כידוע ובחי' חיצוניו' ח\"ס הוא הנק' אלף אולפנא ענין לימוד שהוא סוד הבא לגלוי להיות מקור לחכמ' בגלוי ע\"י ונוצר כו' ומפלא נעשה אלף והוא עיקר ענין הממוצע כידוע ונמצא שאות היוד שע\"ג הקו שבאלף שהוא בבחי' חכמ' שבכתר יש בו ב' הפכי' הללו דפלא ואלף ובאמת אדרבה שניהם א' והא בהא תליא דמצד בחי' הצמצום וההסתר הנק' פלא הוא שבא לכלל אלף להיות מקור לגלוי חכמ' שהוא ענין אות היוד הקטן שתחת הקו חכמ' שביסוד דא\"א שממנו מתהווה החכמ' ממש מאין ליש והויו שהוא קו האמצעי שבאלף ממוצע לחבר היוד העליון דבחי' ח\"ס לחכמ' תתאה שביוד התחתון כי ע\"ג הקו הזה עומד היוד העליון ומתחבר בו ומתחתיו מתחבר יוד התחתון והקו הזה הוא בחי' המדו' שבחכמ' דא\"א כו' (כמבואר במ\"א בביאור מאמר הזהר כי עשית פלא באריכו' וזהו הקצור העולה משם) דבחי' נקודה דיוד העליון הוא הצמצום דעצמו' אא\"ס שמתצמצם בעצמו עד שלא יהיה אור רק בבחי' נקודה א' לבד בהעדר ההתפשטו' לגמרי שאם הי' בבחי' אור התפשטו' לא הי' יכול להיות גם מקור למקור להתהוות חכמ' כו' וה\"ז עד\"מ צמצום כל עצמות המשפיע שמצמצם ומניח כל שכל עצמו ולא נשאר אצלו רק כנקודה א' לבד כדי שיוכל להיות מקור אח\"כ להשפיע לכלי התלמיד המקבל שאינו בערך לגביו כלל ונק' צמצום המשפיע כדי להשפיע והמקבל גם הוא מתצמצם כל עצמותו עד שאינו רק כנקודה א' לבד נק' צמצום כדי לקבל כדי שאח\"כ יוכל להיות משפיע וכל שהוא בא בבחי' הצמצום יותר בעצמו לקבל יקבל הרב' יותר ויוכל להיות אח\"כ משפיע ברבוי התפשטו' יותר כידוע וב' הענינים הללו הן ביוד העליון שע\"ג הקו שנק' פלא כנ\"ל שבו צמצום כל עצמו' המשפיע שהוא עצמו' המאציל כמו שהוא בבחי' כתר שבכתר שנחשב מן העצמו' אמנם צמצום זה שנשאר רק כנקוד' א' מן העצמו' אינו רק בשביל שיוכל להיו' מקור להשפיע והוא להיות מקור לחכמה שנבדל בערך מהיות מקור כו' רק ע\"י צמצום זה דוקא וגם יש ביוד זה העליון בחי' צמצום של המקבל והוא מה שיוכל להיות מקור לחכמ' כנ\"ל הנק' אלף אמנם נעשה בבחי' נקודה למא' אפי' אור צח ומצוחצח אוכם הוא לגבי עה\"ע שעה\"ע הוא אא\"ס שבפנימי' הכתר ובכלל הוא בחי' כתר שבכתר ופי' אוכם רק כנקודה כדי שיוכל להיות משפיע במדו' שבחכמ' שזהו הוי\"ו שבאלף והמדו' בחי' ממוצע לחבר"],[1700400240,"ביוד התחתון שיהי' בחי' משפיע ממש לחכמ' שתמצא מאין ליש בגלוי אור האצי' כנ\"ל (וכמ\"כ ביוד התחתון יש ב' ענינים האלה צמצום כדי להשפיע וצמצום כדי לקבל אלא שהוא בהיפך דתחל' מצמצם א\"ע כדי לקבל והוא שנאחז היוד בקוצי בקו האמצעי מלמטה למעלה ואח\"כ צמצום כדי להשפיע שהוא נקודה דיוד שתמונתו כדלית קטן לכך הוא בהיפך מיוד העליון לפי שהיוד העליון הוא הבא מכח המשפיע בעצם רק שהוא כמו שליח ממוצע שיש בו ג\"כ בטול וצמצו' לקבל כו') וזהו ששניהם ענין א' והא בהא דוקא תליא דמשום שהוא פלא נעשה אלף וזהו כי עשית פלא וכן עושה פלא דיש בו ב' פרושים ושניהם ענין א' דעושה וממשיך לפלא היינו מה שמתצמצם להיות נק' פלא ונסתר כו' והב' שיהי' נמשך מפלא אלף מפני שזהו צמצום כדי להשפיע כנ\"ל והכל א' וד\"ל ויובן זה בתוס' ביאור ממשל כח המשכיל כל שכל ההיולי שע\"ז אמר יהב חכמתא לחכימין דהיינו שנתוסף אור בכח המשכיל להשכיל לעומק ולרוחב יותר כמו בשינוי שבין קטנו' וגדלות המוחין דאדם מבן ז' עד בן ע' כידוע ואנו רואי' שבטרם שיתחכם מכח הנוסף בכח המשכיל כמו בהיותו בן ז' ואחר שיתחכם מכח זה בהיותו בן ע' אין בכח זה שינוי בעצם כלל רק במה שיצא מן ההעלם לגלוי בלבד שבהיותו בן ז' היה תוס' כח זה רק בהעל' בכח ולא בפועל הגלוי התחכמות ובהיותו בן ע' נשלם לבא כל כח זה לגלוי התחכמות (כמו בוצין בוצין כו') לפי שגלוי התחכמות הוא רק חיצוניות ההשפעה שמגלה מכח חכמתו ואמנם אם בזקנותו דוקא שקנה חכמה ממקורה הרי בא כח הנעלם הזה שהי' בקטנותו בתכלית הקטנות לידי גדלות ביותר זה שינוי בעצ' כח המשכיל וע\"ז אמר והחכמה מאין תמצ' וכן יהב חכמתא כו' וכמו וה' נתן חכמ' לשלמה שזה אור חדש בכח המשכיל שלו כו' וכך יובן בבחי' ח\"ס דא\"א דמה שממנו בא מקו' לגלוי אור החכמ' דאצי' (ע\"י יוד התחתון) זהו כמשל כח השכל הנעלם דחכמה שכבר במציאת שבא לגלוי התחכמות דכל מה שבכחו יש ודאי עתיד להתגלות ונק' מקור לגלוי לבד אבל מקור גם לכח ההעלם דחכמה הוא בחי' פנימי' ח\"ס שנק' פלא דהיינו שנתוסף אור וכח חדש בעצם כח החכמה כמשל השינוי חדש בגדלו' השכל כזקן שקנה חכמה וכענין יהב חכמתא כו' והא בהא תליא דכאש' נתוסף כח מעצמו' המאציל בח\"ס שהו' חכמ' שבכת' ממילא נעש' מקו' לחכמ' בגלוי יותר לפי ערך א' ממש וד\"ל:\n(סג) <b>ובכל</b> זה יובן ענין ה\"א דהגדול והגבי' כו' שהו' בבחי' ג' קוין שנמשך מן הכתר חח\"ן ובג\"ה ודת\"י ומבואר (בפרדס) דהמשכה זו דג' קוין בא רק מבחי' חיצוניות הכתר והוא בחי' חכמה שבכתר בכלל אבל פנימי' הכתר נבדל בערך מהיות מקור לג' קוין (כמבואר בזהר ע\"פ והבדילה הפרכת ותרגומו פרסא בין קדש לקה\"ק שזהו בין כתר דכתר לחכמה שבכתר והוא בחי' קרומא דאוירא כו' כמ\"ש במ\"א) והענין הוא כידוע בדברי רז\"ל דבמקו' גדולתו שם אתה מוצ' ענותנותו ויש להבין למה דוק' במקום גדולתו שהרי דקדק לומר שם אתה מוצא שם דוקא וכי אינו ענין שלא במקום גדולתו אך הענין הוא דהענוה הוא רק בחי' צמצום והנחת עצמו כב\"י שזהו עיקר מדת הענוה למטה כמו ומשה עניו כו' בלתי מרגיש א\"ע כלל להיותו בבחי' מ\"ה בטול עצמו דחכמ' והענוה סימן לבחי' תכלית הבטול והאין דחכמ' דכל שיש בו יותר בחי' הבטול עצמו דמ\"ה ואין עצמו ממילא נראה בו בחי' תכלית הענוה שלא להרגיש עצמו מכל וכל לכך א' דיהב חכמת' לחכימין דוקא שיש בהן בחי' הבטול שהוא הענוה אבל להיפך כל שמורגש בישות יותר יורחק ממנו שפע החכמ' כמו לא בים היא במי שמרחי' דעתו עליה כים ולא תמצאנו בגסי הרוח כו' כידוע והדוגמ' מזה יובן למשכיל"],[1700400241,"למעל' שזהו בחי' יו\"ד העליון שע\"ג הקו דאלף הנ\"ל בהיות ידוע שעל החכמ' נא' לשון עשי' כמו כולם בחכמה עשיתומאחר שבחכמ' עשה הכל הרי גם החכמ' נק' עשי' כמשל שכל וחכמ' שבעשי' שגם השכל שבעשי' עשי' נחשב כמ\"ש במ\"א ואפי' חכמ' עליונ' דאצי' נחשב עשי' מאחר שהאצי' עצמו עשי' נחשב וגם בחי' מקור החכמ' דאצי' הנק' פלא הנ\"ל הרי נא' עושה פלא וכנ\"ל והוא במה שמתצמצם בעצמו להיות מקור לחכמ' נק' עשי' דהלא ידוע דגם בחי' החכמ' היותר עליון כמו חכמ' הקדומה שבעצמו' המאציל שנק' חכים ולא בחכמה ידיעא ונק' חכמ' דא\"ק גם ע\"ז אמר לית מחשבה ת\"ב אפי' מחשבה דא\"ק וכה\"ג וד\"ל ולהיות כן במה שהוצרך לצמצם א\"ע כ\"כ בדילוג הערך נק' ענוה יתירה והוא כמו ענין צמצום הנק' יוד שבמשפיע המופלג בחכמה בשביל שפע קטן הערך מאד שאין זה רק ענוה יתירה אבל באמת ענוה זאת גורמת הריבוי וההתפשטו' של השפע אח\"כ ברוב גלוי גדולת החכמ' במקבלים וכנ\"ל בענין צמצום המשפיע רק כדי להשפיע דהצמצום הוא עיקר הסיבה לשפע כך הענוה הוא עיקר הסיבה אל הגדולה והתפשטו' שאחר כך וזהו במקום גדולתו דוקא שם אתה כו' פי' במקום גדולתו במקום שצריך להיות בחי' התפשטות אור ושפע כמו להיות נק' חכים ומבין וחסדן כו' שנקרא שבח וגדולת אא\"ס לגבי המקבלים שם דוקא בהכרח הי' שימצא ענוה יתירה בתחלה שע\"י ענוה זו דוקא הוא שבא בגלוי מהעלם העצמי' שהוא בחי' הצמצו' שבעצמו' מטעם שבעצמותו הוא אח\"פ בתכלית מרומם ומובדל בערך מהיות גם מקור למקור לחכמ' הקדומה דא\"ק כנ\"ל וגם לא להיות מקור דמקור לרצון ותענוג וכל ספי' ומדה וכמ\"ש ולאו מכל אינון מדו' כלל וכידוע רק ע\"י הענו' והצמצו' בא לכלל בחי' גדול' והתפשטות זו לכך דקדק לומר במקום גדולתו שם דוקא כו' וד\"ל (ובאמת פי' זה יוצא מידי פשוטו דבמקום גדולתו משמע דלפ\"ע הגדולה בעצם כך יוכל להיות עניו לצמצם א\"ע וקאי גדולה זו על גדולת העצמו' דוקא וכמו המלך שהוא גדול בעצם כך יוכל להשפיל א\"ע יותר וכידוע דכל הגבוה גבוה יותר יוכל להשפיל א\"ע והיינו לפ\"ע הגדולה שבעצמו' היא הענוה ולא שע\"י הענוה יבא הגדולה שאין זה עולה כפי הפשט כלל אך הענין באמת דלפ\"ע עצם גדולת העצמו' שלפני הצמצום דלגדולתו אין חקר כך יהי' ערך הענוה והצמצום דפלא הנ\"ל ולכך נק' אדון הנפלאו' כו' ויובן זה יותר לפי אופן המשל הנ\"ל בענוה גשמי' למטה שהוא אמיתית הסימן לתכלית בחי' הבטול ואין בעצם כו' כנ\"ל כך היא למעלה דלפ\"ע בחי' האין האמיתי שבעצמו' אא\"ס כך הוא בחי' ענוה שלו במה שמצמצם א\"ע ונמצא דיוד זה העליון הוא המורה על עצם גדולתו שהוא בחי' אין האמיתי כו' כמו שהוא בעצמו ממש כענוה דמשה שהורה על עצם בחי' אין ומ\"ה שבנפשו וד\"ל) וזהו פי' הגדול כו' בה\"א הידוע דהנ' ידוע שהפתח מורה על בחי' הפתיח' והגלוי לחוץ דוקא והקמץ מורה על בחי' הסתימו' וההעלם בעצמו' דוקא ולזה הטע' הקמץ בכת' ופתח בחכמ' כמו פיה פתח' בחכמ' כו' ואמנ' בפתח דחכמ' יש ב' מדריגו' א' מן ההעל' לגלוי ממש והוא מ\"ש והחכמ' מאין תמצא ליש כו' והוא בחי' חיצוניות ח\"ס דא\"א וע\"י הנ\"ל שנק' חכמ' שבכתר בכלל כנ\"ל והב' בחי' מקור הנעלם שהוא מקור להיות פתיחת החכמ' מח\"ס והוא ע\"י בחי' הצמצום שמצמצם בעצמו דוק' הנק' פלא שהוא עיקר יוד העליון שע\"ג הקו באלף והוא עיקר אות הא' בכלל וזהו פי' אאלפך חכמה שעתיד להיות מקור לחכמ' ע\"י צמצומים רבים שביוד זה הנה זהו ג\"כ נכלל בה\"א זה דהגדול לפי שממנו עכ\"פ עתיד להיות הסתעפות הקו הימין חח\"ן דאצי' דהיינו כשיומשך מפלא אלף וכנ\"ל (והוא ע\"י הענוה מתוך הגדול' שקדמה כנ\"ל בפי' הב' או במקום שצריך להיות גדול כפי' הא' דלעיל) אבל יהי'"],[1700400242,"איך שיהי' מפלא נעשה אלף דוקא משום דהא בהא תליא שהצמצום הוא כדי להשפיע מקור לחכמה שבקו ימין כו' וזהו ה\"א דהגדולבפתח דוקא שמורה פתיח' וגלוי לחוץ אעפ\"י שעדיין סתום הוא כמו שא' אאלפך עתיד ללמד ולא השפיע ולמד עדיין מ\"מ מפני שסופו ללמד ולהבי' לגלוי נק' גם הוא בבחי' גלוי פתיחה וכענין אהי' נא זמין כו' וד\"ל ומה שהקמץ בכתר הוא דוקא בבחי' כתר שבכתר עצמו שנשאר סתום לעולם בסתימו' העצמו' שנק' סדכ\"ס במה שהוא נחשב מבחי' האחרונה שבעצמות ממש דנק' נורא תהלות דלא ידע ליה בר איהו כו' (ומשם נמשך ויו דוהנורא בבחי' שרש קו האמצעי מפני שעולה לפנימית ועצמות יותר שנק בריח התיכון כמ\"ש בפי' המלות ועזוז נוראותיך כו') וכמ\"ש בפרד\"ס דפנימי' הכתר בכלל נבדל בערך מהיות מקור לג' קוין דאצי' אך מ\"מ משם נמשך ע\"י צמצום הנק' ענוה כנ\"ל וכן שרש קו השמאל בג\"ה מה\"א דהגבור שהוא פתח דח\"ס להיות מקור לקו השמאל בג\"ה (ובכלל הן ג' מדות חג\"ת דכתר חסד בה\"א דהגדול וגבורה בה\"א דהגבור ות\"ת בוי\"ו דוהנורא) והוי\"ו דוהנורא כולל שניהן והוא ענין הקו שבאלף שמקבל מיו\"ד העליון שעליו ומשפיע ליוד התחתון שבו שממנו יבא כל גלוי מאין הנעלם דכתר כו' שיוד התחתון נק' בחי' יסוד שמביא המדות לגלוי לחוץ כידוע כך יוד זה שתחת הקו דאלף מביא לגלוי מאין הכתר הנעל' כל בחי' המדות חג\"ת שבח\"ס שבכתר שמקבל מסדכ\"ס הנק' רדל\"א כו' שמשם עושה פלא כמ\"ש נורא תהלות עושה פלא כו' ונמצא שהקו שבאלף ממוצע הוא בין יוד העליון ליוד התחתון שמקבלים מיוד העליון ונמשכים ביוד התחתון והן עיקר שרשי צינורות השפע לג' קוין דאצי' ויוד העליון הוא ממוצע בין העצמות לנאצלי' בכלל והוא במה שיש בו ב' מדריגות דפלא ואלף שגם שהן ב' הפכי' אבל באמת שניהם ענין א' דוקא והא בהא תליא לפ\"ע כנ\"ל באריכות וד\"ל (ומ\"ש לך ה' הגדולה והגבורה בה\"א לבסוף דוקא היינו ענין ה\"א דהגדול בתחלה בפתח אלא ששם הוא בבחי' הסתימות ושרש ומקור לגדולה וגבורה הבאי' בגלוי באצי' ובה\"א דלבסוף הוא בא בגלוי התפשטות ומ\"ש לך ה' הגדולה דנעוץ סופן בתחלתן כו' (דלכך ה\"א דהגדול בפתח מפני שעתיד לגלות אור הגדולה ואמנם מ\"ש לך ה' הגדולה היינו שעולה הגדולה דקו ימין ונכלל בעצמות ממש שלמעל' גם מהיות בחי' מקור למדות דכתר שמקבלי' מח\"ס כו' הרי זה בבחי' פנימית הכתר בכלל שהוא בחי' כתר שבכתר שזהו בקמץ ולא בפתח כנ\"ל ע\"כ גדולה בקמץ תחת הלמ\"ד היפך פתח דהגדול כו' וד\"ל) וביאור זה יובן עפ\"י הנ\"ל באות האלף שיש בו ב' יודין וקו באמצע כך יתפרש לפי דעת המקובלים שאות אלף בחכמה שב' יודין והוי\"ו הכל בחכמ' עצמה והיינו כמו בציור היו\"ד שקוץ העליון שבו כתר דחכמה כו' וקוץ התחתון שבו הוא בבחי' יסוד אבא כידוע וביאור הדברים ידוע שזהו עד\"מ שאנו רואי' הברקת אור השכל האנושי באדם כשנופל לו שכל והמצאה פתאום שזהו כמו חץ הנזרק כו' כמו ויצא כברק חיצו (בל\"א בליעצט כו') ובודאי כח עליון זה השופע וממשיך להברקת גלוי נקודה זו הוא בהעלם ע\"ג אור הגלוי הזה והוא לא בהסתלקות לגמרי כי אדרבה הרי הוא שכל זה עצמו שבא בגלוי הברקה רק שהוא עומד כמרחף על המוח (בל\"א שוועבט איברען מוח) ולכך קוץ זה התחתון דיו\"ד נק' יסוד אבא שז\"ש כברק חצו והמרחף הוא המשפיע ממש הוא הנקודה העצמי' דיו\"ד אך קוץ העליון שנק' כתר דחכמה הוא מקור של כח זה העליון השופע ומרחף על המוח להיות שבודאי מכח הנעלם שבעצמו' כח המשכיל נמשך אור וכח שכל זה שבהעלם שהוא משפיע לגילוי ההברקה וזהו ג\"כ ענין ב' יודין דאלף דיוד העליון חכמ' שבחכמה או כתר דחכמה הוא שרש"],[1700400243,"כח המשפיע שבהעל' כח העצמות הוא עדיין והוי\"ו הוא המשכה שנמשך בקו להיות משפיע כמו כח המשפי' שכל לגלוי המרחף על המוח והיוד התחתון הוא גלוי שכל המבריק כו' (וכמ\"ש במ\"א בענין אור מים רקיע גם בחכמ' יש בו אור טרם שיומש' להיו' מקור לגלוי ומקור לגלוי נק' מים כו') וזהו לך ה' הגדול' בה\"א לבסוף כי יו\"ד דשם הוי' בחכמה הוא כלול מנ' מדריגות כנ\"ל והבטול והתכללות דלך הוי' ה\"ז עולה בשרש הראשון לחכמ' קודם שיצא להיות מקור לחכמה שהוא כתר שבכתר כנ\"ל וד\"ל):\n(סד) <b>אך</b> הנה יש להבין לכאורה איך יוכך להיות בחי' דילוג גדול כזה מעצמות המאציל להיות מקור לחכמה גם ע\"י בחי' צמצום דיו\"ד שע\"ג הקו שבאלף הנ\"ל מאחר שאין ערוך אליו כלל וכלל כנ\"ל אמנם הנה לזה אמר ונוצר חסד לאלפים פי' ונוצר אותיות צינור כידוע והוא אותיות רצון שהוא אור הכתר כמ\"ש כצנה רצון תעטרנו וכתר זה שנק' רצון הוא בחי' כתר שבכתר שלמעל' מבחי' חכמה שבכתר שנק' מקור לחכמ' הגלוי' שביוד דאלף כנ\"ל דכתר שבכתר הוא מבחי' העצמות שלמעלה מבחי' מקור לחכמה כו' אך אור רצון זה מתצמצם במאד ונעשה ממנו מקור לחכמה ביוד דאלף כנ\"ל שמפלא נעשה אלף כך מרצון נעשה צינור והוא עד\"מ הצינור הדק שבו מצומצ' הילוך השפעה של המים שבחביו' הגדולה לתוך כלי קטן וצר לפי שלא יכיל הכלי קטן לקבל מהחבית הגדול' כ\"א ע\"י צינור דק מאד כך א\"א שיהי' המשכ' מעצמו' אור הכת' שנק' רצון הנ\"ל כ\"א ע\"י צמצום צינור שהוא אור דק ומצומצם וצר מאד בכדי שיוכל להיות מזה יניקו' אור ומקור לבחי' אות האלף בכלל שהוא מקור לחכמ' כנ\"ל (וכענין המבוא' במ\"א בפי' ותמלא כדה ותעל שהן כ\"ד שפרים דאורייתא דמח\"ע נפק' וחכמ' הקדומה שבעצמו' נק' ים הקדמוני וכמשל השואב בכד קטן מים הגדול כו' משום דנובלות חש\"מ תורה כך ע\"י צינור דק נמשך מקור לחכמ' דאצי' מים הקדמוני שבעצמות כו' וכמשל גידי הארץ שנובע המים בהן בהעלם ודקות מן התהום רבה אך נק' מעיין סתום וחתום וביציאתו בגלוי לנהר נק' מעיין גלוי כו' כך צינור דמזל ונוצר שהוא מקור הנעלם להיותו מקור למקור הבא בגלוי שהוא בחי' חכמה שבכתר כנ\"ל וד\"ל) וזהו פי' ונוצר חסד לאלפים פי' אלפים כמ\"ש אאלפך חכמה כו' לשון להבא שעתי' ללמד כו' דהיינו שעתי' להיו' נמש' ממנו מקור לחכמ' ועדיין לא נמשך כו' והוא בחי' פלא הנ\"ל שהוא פנימי' ח\"ס דא\"א שנחש' עם בחי' כתר שבכתר (שע\"ז אמר בע\"ח דאור הכתר אינו נמנה בע\"ס כו') שנבדל בערך מהיות מקור לחכמה והוא שכל מופלא שלא בא לגלוי לעול' ולפ\"ז כאשר נא' שזהו פי' לאלפי' שהוא אאלפך ולא ע\"י האלף עצמו שנק' אולפנא כשנעשי' מקור התהוות החכמה כשמפלא נעשה אלף א\"כ פי' ונוצר חסד לאלפים היינו שונוצר זה הוא צינור המשפיע לאאלפך שהוא בחי' פלא דפנימית ח\"ס הנ\"ל וכענין עושה פלא כנ\"ל ונק' מקור לפנימי' ועצמו' הכתר כמו פנימי' ח\"ס הנ\"ל וד\"ל ובאמת יש לזה סתירות גדולות הא' מאשר ידוע שיש ב' מדריגות בחסד עליון שבכתר א' ורב חסד שקודם במעלה לונוצר חסד זה והוא בחי' רב חסד דעתיק שמאיר בגלגלתא דא\"א כו' (וגבורה דע\"י מלובש בח\"ס דא\"א שנק' טלא כו' ומשם שרש לקו השמאל בג\"ה ע\"י מזל ונקה כמ\"ש אני בינה לי גבורה דע\"י כמ\"ש בע\"ח) והב' מזל ונוצר זה שהוא מזל הח' בי\"ג ת\"ד דא\"א כו' ויש מדרגה שנק' חפץ חסד כמ\"ש בי\"ג מדה\"ר דמיכה כי חפץ חסד הוא החפץ הוא פנימי' הרצון (וידוע דע\"י וא\"א הוא בחי' הענג ורצון"],[1700400244,"העליון והענג פנימי' הרצון ולכך נחשב בחי' א\"א שרש לנאצלי' ובחי' ע\"י נחשב מסוף עולם הא\"ס דרך כלל) וחפץ חסד הוא מחיצוניות העונג ופנימי' הרצון ע\"כ הוא בחי' ממוצע בין רב חסד דע\"י (כמו האהבה וחסד שבתענוג שהתפשטותו בלי שיעור כמ\"ש במ\"א) לונוצר חסד שונוצר הוא היפך אותיות רצון בחילופי אתוון בצירופ' והוא להיותו בא בבחי' צמצום אור וחיות מן הרצון העצמי שהוא עצמות אור הכתר כנ\"ל שהוא בחי' רב חסד דע\"י שבגלגלתא דא\"א כו' לפי שרב חסד דע\"י נחשב בבחי' א\"ס ממש וצינור זה בא בבחי' הצמצום לגבי המקבלי' ע\"כ צריך לבחי' ממוצע לחבר אור חסד עליון שבעצמות להיות מקור לנאצלים ע\"י מזל ונוצר והוא בחי' חפץ חסד הנ\"ל שמביא וממשיך מרב חסד לונוצר חסד [ועד\"מ חפץ חסד למטה הוא מי שיש לו עונג נפלא בשפע חסד שמחמת זה יחפוץ תמיד לעשות רב חסד הרי הרצון וחפץ הזה כלי לבחי' פנימי' העונג שמלובש בזה ושפע אור החסד שנמשך מחפץ ורצון זה בא בצמצום לפי המדה הגזורה ע\"פ שכל וטעם לרצון שנק' ח\"ס כו') ולפ\"ז יש מכאן סתירה גדולה לענין הנ\"ל בפי' ונוצר חסד לאלפים לאאלפך לעצמות ח\"ס כו' שהרי מזל ונוצר הוא מקבל מרב חסד דעצמות הכתר ע\"י צמצום כנ\"ל ואיך יהי' מקור לפנימי' ועצמות הכתר כמו פנימי' ח\"ס כו' והסתירה הב' מאשר ידוע ומבואר בע\"ח בכמה דוכתי ובשרש הב' מזלות דונוצר ונקה כו' שהוא מבחי' מותרי מוחין דח\"ס דא\"א דהיינו רק מבחי' השערו' שצומחין ממותרי מו\"ס כו' וע\"כ נק' מזלות כמ\"ש בכמה דוכתי דאור אבא דאצי' יונק ממזל הח' ונוצר כו' ואור אימא ממזל הי\"ג ונקה כו' וידוע שהשערות אין בהן רק חיות מצומצם מאד בחלל שלהם הצר והן נבדלין מעצם האדם עד שלא ירגיש כאב כלל בחיתוכן כו' וכמ\"ש במ\"א ולזאת איך יתכן לומר שמזל ונוצר יהי' מקור למקור החכמ' שהוא עצמו' ח\"ס מאחר ששרש יניקתו אינו אלא מבחי' מותרי מו\"ס לבד איך הטפל יהי' מקור ועיקר (וא\"א לומר דפי' אור אבא זה שיונק ממזל כו' הוא פנימי' אור אבא שמקבל מפנימי' ע\"י שהוא רב חסד הנ\"ל דבי' אחיד אבא כו' דא\"כ איך א' שיונק ממזל הח' ונוצר שהוא ודאי רק מבחי' חיצוניו' דח\"ס דא\"א כידוע) אלא מוכרח לומר בפי' ונוצר חסד לאלפי' שאין הכונה על מו\"ס דא\"א עצמו שזהו אאלפך כנ\"ל אלא הכונה רק על בחי' האלף עצמו שהוא בחי' גלוי אור ושפע החכמ' מאין והעלם הכתר ששרש זה הוא מזל ונוצר חסד והיינו כמ\"ש דאור אבא דאצי' שהוא בחי' גלוי אור חכמ' דאצי' יונק ממזל הח' ונוצר כו' שאינו רק מחצוניות ומותרי ח\"ס דא\"א כנ\"ל והענין הוא כידוע דחו\"ב דאצי' כבר נאצלו מאין העצמות לבחי' יש בבחי' מציא' דבר מה וכענין קנה חכמה קנה בינה ב\"פ קנה גי' יש [כנ\"ל באריכות] וע\"ז נא' והחכמ' מאין תמצא במציא' יש ע\"י מזל ונוצר שהוא צינור דק שנובע בהעלם גדול כו' כמו דרך שערה חלולה כו' ע\"ד הנ\"ל בבחי' ח\"ס עצמו וכמ\"כ שרש יניקה לאור הבינה דאצי' ממזל ונקה ובחי' חו\"ב דאצי' הן הנק' אלפי' ב' אלפין ע\"ש אולפנא לימוד וגם מה שפירשו אאלפך ל' עתיד יתפרש זה גם בבחי' מקור חכמ' דאצי' שבאה בגלוי מן העלם דמזל ונוצר הרי ממזל ונוצר עתיד לאתגלאה להיות גלוי החכמ' בבחי' יש בבחי' האצי' (וע\"ד הנ\"ל בפי' אאלפך על ח\"ס דא\"א שעתיד להיות מקור לחכמ' כך יתפרש כפשוטו) וזהו אאלפך שעתיד ללמוד ולא למד עדיין היינו בחי' מזל ונוצר זה שיש בכחו ללמוד כו' דהיינו להשפיע גלוי אור החכמ' בבחי' יש דאצי' כו' ועדיין לא בא האור בגלוי גמור רק שבא האור בבחי' יניקה לאור אבא שהוא בהעלם דרך צינור כו' כנ\"ל ונמצא המזל עצמו"],[1700400245,"נק' אאלפך והחו\"ב דאצי' שכבר נתגלו וקבלו האור מאין ליש נק' אלפי' וזהו ונוצר חסד לאלפי' דחו\"ב שזהו בחי' אור הכתר בחו\"ב (דלא כפי' דלעיל לאלפי' לאאלפך כו') (ובאמת פי' זה יותר מתיישב בלשון אלפי' דלפ\"ז אאלפך הוא במזל ונוצר מקור החכמ' הגלוי' אבל עצם החכמ' הבא' בגלוי מאין ליש ממש הוא הנק' אלף באמת כי פי' אלף לימוד הוא לימוד הבא בגלוי משא\"כ אאלפך אינו אלף עדיין רק שעתיד ללמד כנ\"ל ולפי' דלעיל דקאי על אאלפך אין זה אלף עצמו עדיין במקרא מפורש לאלפי' כו' והנה באמת גם הפי' הראשון אמת אך הוא מדבר במדריגה עליונה יותר והוא גם בעצמו' חו\"ב דא\"א איך שהן מקבלים מרב חסד דע\"י ע\"י ונוצר חסד ובחי' עצמו' חו\"ב דא\"א נק' אלפי' אולפנא בחי' גלוי לגבי העלם כתר שבכתר ששם הוא בחי' רב חסד דא\"ס וע\"ז נא' והחכמ' מאין כו' פי' ח\"ס עצמו מאין העצמי דעצמו' הכתר כו' כמא' דאפי' אור צח ומצוחצח שהוא עצמו' ח\"ס אוכם הוא לגבי טה\"ע כתר שבכתר כו' אבל אאלפך הוא בחי' מקור לח\"ס עצמו ע\"י צמצום ונוצר אמנם לא נק' ונוצר זה בחי' מזל כלל אלא הוא בחי' צמצום ההמשכה מרצון העליון שהוא חפץ חסד שנמשך מרב חסד דע\"י כנ\"ל כי בחי' מזל הוא בא בבחי' שערו' שאינו רק מחיצוניו' דמו\"ס דא\"א כנ\"ל ונמצא שני הפי' אמת ומתיישבין בלשון הכתוב לאלפי' שהן אלפין ממש אלא שזהו קורא אלפין לחו\"ב דאצי' שבגלוי וזה קורא לחו\"ב דא\"א עצמו שם אלפי' כנ\"ל וד\"ל [ולפ\"ז מ\"ש ועושה חסד לאלפי' דקאי במזל ונקה שרש לבינה והחכמ' כלולה בה משום שנק' מקרא קודש וכמו וחכם בבינה בחי' ע\"ב דס\"ג כו' יתפרש ג\"כ בב' אופני' הנ\"ל בבינ' דא\"א עצמו ובבינ' דאצי' אך בבינ' דא\"א איך שייך עשי' שהוא ההתפשטו' מאין ליש בבחי' מקור למקור (משא\"כ ונוצר שהוא כולל גם לבינה שבחכמ' דא\"א כמו הבן בחכמ' ס\"ג דע\"ב שייך שחם בחי' בטול היש לאין מחמת אור אין העצמי גם בבינה דו\"ס כו') אמנם מבואר בפי' המלות בסידור בפי' ברוך ואמר ועושה שהוא חו\"ב דא\"א כו' והיינו ועושה חסד כו'):\n(סה) <b>ומעתה</b> יובן בענין ציור תמונת האלף שהוא ב' יודין ווי\"ו באמצע כנ\"ל שאין היוד העליון שבו בבחי' אאלפך חכמ' מקור לח\"ס כו' אלא יתפרש הכל בבחי' החכמ' עצמה בין בח\"ס בין בחכמ' הגלוי כו' דהנה היו\"ד הוא בחי' חכמה שבחכמ' והוי\"ו הוא מדות שבחכמ' והיוד התחתון הוא בחי' השפע' היסוד דחכמ' וביאור הדברים בחכמ' הגלוי' ידוע עד\"מ מהברקת אור נקודת המושכל בגלוי נק' יוד העליון והוא בחי' חכמ' שבחכמ' שהוא עצם נקודת המושכל כמו שבא מן ההעל' לגלוי כו' ובחי' התפשטו' והמשכה שלו לגלוי יותר הוא בחי' מדו' שבחכמ' (והוא שכל המטה כלפי חסד או דין אע\"פ שאין טעם ושכל מושג לדבר עדיין כמו שתיק רב דלעיל ונק' ו\"ק דאבא כמ\"ש במ\"א) והיוד התחתון הוא בחי' השפעת יסוד דחכמ' בבחי' מל' דאבא שהוא בחי' אותיות דחכמ' שנמשך מזה בבינה להיות הנקודה בהשגה לאורך ורוחב כו' [כמו קוץ התחתון דיוד כנ\"ל] ועד\"ז ממש יתפרש ציור האלף בבחי' ח\"ס עצמו אלא ששם הוא בחי' ההעלם דכתר עליון הנק' רצון וכידוע שהחכמ' וטעם כמוס לרצון נק' ח\"ס כענין המא' שתוק כך עלה במח' כו' היוד העליון הוא בי' חכמ' שבח\"ס והוי\"ו הוא מדו' דח\"ס והיוד התחתון הוא בחי' יסוד דח\"ס כו' והכל הוא בבחי' ההעל' דרצון עדיין שלמעלה מן השכל הגלוי כו' אבל הנה פי' ונוצר חסד לאלפים לב' הפרושים דאלפים הנ\"ל בין בח\"ס עצמו בין בחכמה הגלויה הוא למעלה גם מיוד העליון דאלף ונק' אאלפך חכמה בין לח\"ס בין לחכמה הגלוי' וד\"ל ונמצא"],[1700400246,"מובן מכל הנ\"ל דב' הפירושים בנוצר חסד לאלפים עולה בסגנון א' ממש רק שזה מדבר בח\"ס מקור החכמה וזה מדבר בחכמה הגלוי' ישיניהם נק' אלפים ולא אאלפך כנ\"ל ואמנם יש לפרש עוד דבאמת אינם שני ענינים מחולקים כלל אלא שניהם מדברים בשרש וענין א' ממש והוא בהקדים תחלה ענין א' בבחי' שרש יניקות המזל שנק' שערות כו' דהנה מבואר בע\"ח דבחי' מותרי מו\"ס שיוצאין ובוקעין בבחי' מותרות ונובלות שמהן צומחין השערות שרשן למעלה יותר מגוף המוחין דח\"ס וראי' משרש י\"ג ת\"ד שהן למעלה מבחי' ח\"ס כמ\"ש ויעבור ה' על פניו כו' (וזהו נושא עון אעפ\"י שעפ\"י תורה אין יסורין בלא עון כו' ושרש התורה בח\"ס מקור החכמה אך י\"ג מדה\"ר שרשן מעצמו' הכתר כו') והטעם מבואר במ\"א שזה שיוצא בבחי' בקיעה וצמיחה מן המותרו' הוא מפני שנתוסף רבוי אור וחיות בגוף המוחין עד שלא יכילם ע\"כ יצאו המותרות בבחי' בקיעה כו' כמשל חבית הגדול' שמלאה ביותר יבקע החבי' ויצאו מים דרך בקיעה בסדקין שבקיעה זו מורה בחי' מילוי ביותר שלא יכיל כלי החבית א\"כ אותן מים שלא יכיל עוד בכלי הן שבוקעין ויוצאין בסדקין כו' וכך בחכם גדול שנתוסף כח חכמ' בכח המשכיל יצא ויבקע מותרי מוחין ומותרות הללו גבוהי' יותר מעצם המוחין שיש בו מכבר לפי שזהו בחי' תוס' אור שלא יכיל המוח הוא שיוצא כו' (וכן כמו בקיעת אור שחר שהשמש בא ומאיר בגבורתו אז יבקע העובי של הרקיע החשוך ויאיר שם ונק' בקיעת אור השחר כמ\"ש אז יבקע כשחר כו') וזהו טעם זקן שקנה חכמ' ממקורה שלמעלה מח\"ס שהוא כח המשכיל להשכיל מהעלם אל הגלוי כידוע בענין יהב חכמתא לחכימין שזהו ענין תוס' כח בכח המשכיל שנק' חכימין כו' ולזה אמרז\"ל דרך שבח נובלות חש\"מ תורה נובלות דוקא לפי שנובלות הללו שרשן למעלה מחש\"מ עצמו הנק' ח\"ס דא\"א או חכמ' הקדומה דא\"ק וכה\"ג וכמ\"ש במ\"א באריכו' וד\"ל ובהקדמה זו יובן גם כאן בפי' ונוצר חסד לאלפי' דב' הפרושי' הנ\"ל ענין א' ממש הוא דהיינו שנוצר זה נק' מזל הבוקע ויצא בבחי' שערו' ממותרי מו\"ס לבד ועכ\"ז שרשו הגבה למעלה מגוף המו\"ס עצמו דהיינו ששרשו בעצמו' הכתר הנק' גלגלתא דא\"א דחפיא על מו\"ס כידוע והוא בבחי' רב חסד דע\"י שבגלגלתא דא\"א כנ\"ל ונמצא ב' הפרושי' א' הוא ממש דלאלפי' קאי גם בח\"ס עצמו ואעפ\"כ נוצר זה הוא בחי' מזל דא\"א ולפי שבשרשו הוא מבחי' גלגלתא דחפיא על מ\"ס ע\"כ הוא בחי' משפיע ג\"כ לא\"ס עצמו וגם ע\"ז אמר והחכמ' מאין כו' ובחי' ח\"ס שמקבל מהכתר עצמו ע\"י צינור דונוצר לפי שזהו מה שלא יכול המוחין להכיל הוא שיוצא בבחי' מזל דשערו' כו' כנ\"ל וד\"ל [וזהו פי' והחכמ' תחי' בעלי' פי' בעלי' דח\"ס גם במקור דמקור חוצבה באין האמיתי דעצמו' הכתר ממש לפי שמגיע זה עד בחי' מקיף דמקיף דיחידה כמו בר\"ע שזלגו עיניו דמעו' מדחיקת המוח שלא הי' יכול להכיל העונג שבשכל זה מגודל עצם העומק שבפנימי' סודות התורה דלאו כל מוחא סביל כו' נמצא יציא' הדמעות שרשן במקור דמקור של הסוד הזה כו'): והנה אחר כל ההקדמות הנ\"ל יובן פרטי ענין ועד בחלופי אתוון דאחד ותחלה יש להבין בחילוף אות אלף דאחד שנמשך מיחו\"ע ליח\"ת בועד נעש' אות וי\"ו ואח\"כ מן החית דאחד נעשה עין כו' בהיות מבואר למעל' בציור אות האלף ומזה יובן ענין אות אלף דאחד עפ\"י המבואר למעלה בפי' ונוצר חסד לאלפים כו' ותחלה יש להבין סדר הצרופי' דאותיו' אחד ביח\"ע ואח\"כ יובן איך שנעשה בחלופי אתוון ביח\"ת תיבת ועד כו' דהנה כל ענין הנ\"ל בפי' נוצר חסד לאלפי' אין זה רק מה שאות האלף בכלל הוא בחי' ממוצע להתחברות עצמו' אא\"ס שבפנימי' הכתר להיות מקור לחכמ' מאין ליש"],[1700400247,"ע\"י מזל ונוצר כנ\"ל ומעתה לכאורה יש להבין מה שכולל לחו\"ב יחד באמרו לאלפים ובענין אאלפך כו' חלקם לשנים באמרו אאלפך חכמה ואאלפך בינה ולא כללם יחד אאלפך חו\"ב כו' ולכאורה יש לתרץ שיש הפרש גדול בין שרשי המוחין דחו\"ב שהן ב' מזלות דונוצר ונקה להמוחין דחו\"ב דאצי' שב' מזלות הנ\"ל הן מחולקי' כ\"א במהות בפ\"ע כידוע דמקור הראשון הממשיך התהוות התחכמות הנק' הבנה במוח החכמה הוא מקור מיוחד בפ\"ע ואין לו חיבור ושייכו' כלל עם מקור השני הממשיך התהוות מוח ההשגה והרחב' השכל בהסבר לאורך ורוחב (כנ\"ל בסי' נ\"ט) ולכך נק' זה מזל הח' וזה מזל הי\"ג כי שני מקוריי' מחולקי' הם ולכך א' אאלפך חכמה בפ\"ע ואאלפך בינה בפ\"ע דיוכל להיות זה בלא זה לכך כפל לומר אאלפך בינה כו' (כנ\"ל שם באריכות) ואעפ\"י שזה נק' מזל העליון וזה מזל התחתון ועליון ותחתון היינו בחי' משפיע ומקבל וזהו הוראה על היחוד והתכללות דב' מזלות הנ\"ל וכמבואר במ\"א בענין הכל תלוי במזל אפי' ס\"ת בהיכל שהוא שרש יחוד עליון דאו\"א כשמתכללי' ב' המזלות שרשי המוחין דאו\"א (ונק' מזל סתם כנ\"ל שם) הענין הוא דמתחלה מחולקי' הן כנ\"ל ומתייחדי' ומתכללי' אח\"כ וזה נק' מזל העליון כו' אמנם אחר היחוד והחבור חוזרין ומתחלקין זה בפ\"ע משפיע למוח החכמ' וזהו בפ\"ע משפיע למוח הבינה כי א\"א שישפיע כל א' למטה כ\"א כשיוכללו יחד תחל' וחוזרים ומתחלקים ונמצא אין היחוד תדירי כו' אבל יחוד דחו\"ב דאצי' נק' יחוד תדירי ותמידי כמ\"ש בזהר דאו\"א זוגייהו תדיר ונק' תרין רעין דלא מתפרשין לעלמין לעלמין ממש והטעם הוא מפני שההמשכה מחכמה דאצי' לבינה שהוא מאין ליש ממש זה צריך להיות בתמידות בלי הפסק כלל ולכך כוללם יחד במקרא באמרו נוצר חסד לאלפי' שהן חו\"ב יחד משא\"כ במזלות שלהם אין היחוד תמידי רק לפרקים (כמו בגבורת גשמים שאמר בזהר שהוא בשרש המוחין דאו\"א והוא מזל ונוצר כמטר שיורד בבחי' קו כנ\"ל בענין יורה ומלקוש וד\"ל) אך עדיין אין זה מתורץ במה שמצינו גם בחו\"ב שבא מאין ליש בגילוי חלקם לשנים ולא כללם יחד באמרו קנה חכמ' וקנה בינה וב\"פ קנה גי' ש\"י שהוא יש כו' דהיינו בבחי' חו\"ב שכבר נמשך מאין ליש כידוע ועוד יש להבין מה שסותר לזה במ\"ש אם אין חכ' אין כו' (כנ\"ל שם) אך האמת הוא דגם במקרא חלק לשנים רק באופן אחר והוא הכל בבחי' התכללו' דחו\"ב יחד והיינו באמרו ונוצר חסד לאלפי' שנכלל בינה בחכמ' ובמה שכפל עוד לומ' במ\"א ועושה חסד לאלפי' שזהו במזל ונקה שרש הבינ' ונכלל בזה החכמ' וא\"כ יש כאן התחלקו' ונוצר ועושה וכל א' כלול משניהם יחד אלא שבזה החכמ' עיקר והבינה נכלל בה כענין הבן בחכמ' ובזה הבינה עיקר והחכמ' נכלל בה כענין וחכם בבינה וכנ\"ל (שם) בענין רואין את הנשמע ושומעין כו' שיש כאן ב' מיני התכללו' ושניהם אמת משום דלפעמי' מקבלי' חו\"ב יחד ממזל העליון ונוצר ולפעמים מקבלים שניהם יחד ממזל ונקה ועוש' לכך נזכ' בשניה' לאלפי' וזה דוק' ביחוד המזלו' שכלול כ\"א מזולתו ע\"כ מקבלים ממזל ונוצר ונכלל בזה מזל ונקה ולפעמי' מזל ונקה משפיע לחו\"ב ונכלל בזה מזל ונוצר (כענין יו\"ט שנק' מקרא קדש כו' דמוחין דאבא נכללים בהעלם באימא ובשבת הוא להיפך שמוחין דאימא נכללים באבא וכמ\"ש בזוהר ע\"פ והובא את בדיו בטבעו' כו') כי הנה לפעמים נק' או\"א קדושים כשמקבלים מבחי' אין דונוצר ואז נא' והחכמה מאין כו' וכשמקבלים ממזל ונקה אז גם החכמ' נק' בבחי' עשי' כמו עושה בראשית דבראשית נמי מאמר הוא משא\"כ כשמקבלים שניהם מאין דונוצר גם בינה בבחי' אין כמ\"ש ואי זה מקום בינה כו' ומעתה יתורץ הכל דכאשר ב' מזלות כל א' בחי' משפיע בפ\"ע אז גם חו\"ב מחולקי' החכמה נק' אין ובינה נק'"],[1700400248,"יש כל א' כפי מקורו כו' אך כשמתייחדי' הב' מזלות יש בזה ב' אופנים והכל בהתכללות דחו\"ב א' שמקבלי' שניהם יחד מנוצר ואז שניהם בבחי' אין וכמ\"ש והחכמה מאין ואיזה כו' וע\"ז אמר אאלפך חכ' אאלפך כו' לשון עתיד כנ\"ל וכאש' שניה' מקבלי' ממזל ועושה גם החכמ' בבחי' עשי' דבינה להיות מאין יש דוקא כמו אומר ועושה או עושה בראשית ע\"ז א' קנה חכמ' קנה בינה וב\"פ קנה גי' יש שהוא בחי' יש דמזל ונקה שמקבלים שניהם משם (ומ\"ש אם אין חכמ' וכו' קאי בב' האופנים בין כשמקבלי' שניהם בבחי' אין והעלם דונוצר בין כשמקבלים שניהם בבחי' יש דונקה כמו ב' האופני' דונוצר כו' לאלפים ועוש' כו' לאלפי' הנזכר בכתוב וד\"ל):\n(סו) <b>וזהו</b> ענין אות האלף דאחד ומאות אלף זה נעשה חית בסדר צירופי' דאחד דהנה ידוע בכונות דאחד א\"ח דלית היינו בחי' ט\"ס דז\"א כו' ובאמת קאי תיבה זו דאחד הכל בבחי' יח\"ע דחכמ' עלא' בב' האופני' דלעיל בשרש ציור האלף בכללותו אם בבחי' ח\"ס עצמו או בבחי' חכמ' גלוי' דאציל' ולפ\"ז אלף דאחד הוא כולל כל מה שמבואר למעל' בציור ב' יודין והוי\"ו שבו וכללו' ענינו הוא בחי' הממוצע לחבר עצמו' אא\"ס שבכתר שיתגלה בבחי' החכמ' מההעלם שבעצמותו ממש (שהוא מפלא אלף כנ\"ל) וכנ\"ל שזהו ענין נוצר חסד לאלפים וכשבא מן ההעלם דצינור לגלוי ממש נק' אולפנא לימוד כו' ואמנם הנה יש בזה ב' מדרגות הא' גלוי אור הנגלה מן המשפיע אל המקבל שהוא כציור וי\"ו שהולך ומתקצר למט' ביותר לפי שלא יגיע סוף השפע למקבל כ\"א בצמצום גדול מאד (וכמ\"ש במ\"א בענין עטרת יסוד כו' ע\"פ ולא יכול יוסף להתאפק בחי' וי\"ו זעירא שזהו מה שנשאר אצל המשפיע לגלות אור הנצשך רק לפ\"ע מדת כלי המקבל ולא יותר וכמ\"ש בזוהר בפי' ומספר רובע ישראל כו') והב' כאשר כבר נמשך אור השפע במקבלים וקיבל כל אור השפע בבחי' גלוי מאין ליש גמור שזהו עיקר ענין הלימוד כשנתקבל במקבל דוקא והמשפיע אור ולא נתקבל עדיין הגם שנק' מלמד אינו שלימות עדיין עד שנתקבל במקבל בבחי' יש גמור מוגבל לפי אופן המקבל וכמו מכל מלמדי השכלתי שהן נו\"ה שנק' מלמדי וכן למודי הוי' כידוע וכך הוא ענין האלף אולפנא שיש בזה ב' מדרגות א' מן המשפיע אל המקבל שנתצמצם כמו וי\"ו והב' כשנתקבל במקבל שנתגלה לפי אופן כלי ההגבלה שזהו עיקר הגלוי ונק' יש במוגבל משא\"כ גלוי אור המשפיע הגם שנק' יש לגבי העלם עצמות המשפיע אבל לא בא למטה עדיין ויובן זה במ\"ש להנחיל אוהבי יש שיש בזה ב' מדרגות הנ\"ל והא' הוא יש דעוה\"ב שהנשמות נהנין כו' היינו יש דמשפיע אל המקבל והן ש\"י עולמות דקנה חו\"ב גימ' יש כנ\"ל והב' יש דמקבל כאשר הנשמות נהנין כו' ומקבלי' לפי אופן כלי השגתם שאז בא מאין ליש גמור ונק' צמצום המשפיע בהילוך אור שפעו למקבל בחי' אין ליש וד\"ל ועד\"ז ממש יובן בין אות האלף דאחד לאות החי\"ת שהחי\"ת הוא בחכמ' והאלף הוא בבחי' יש דמשפיע אל המקבל שנק' אולפנ' כו' ולכך הוא בציור ב' יודין יוד התחתון הוא בחי' גלוי השפע מן המשפיע אל המקבל ע\"י הוי\"ו שהוא אמצעי כנ\"ל וזהו עיקר ענין אות האלף ושלימותו כשבא לכלל שפע לחוץ (וכמ\"ש דרדקי אלף בי\"ת אלף בינ' כו' וכן בחכמ' יבנה בית כו' כמו שמקוצו של יו\"ד התחתון נמשך לבינה אך תחלה צ\"ל בחכמ' עצמה בחי' כח זה הנמשך למטה) והוא בחי' יש דמשפיע הנ\"ל ובחי' יש דמקבל הנ\"ל הוא ענין החי\"ת דחכמ' הנ\"ל דהיינו כאשר האור בא במקבל בכלי קבלתו שנק' לימוד שלמד לזולתו אז נק' חכמ' לשון נוקבא משא\"כ המשפיע את השכל נק' חכם לשון דכר כמו כל דבר חכמ' שכבר נמשך במקבלים נק' חכמ' בה\"א שהוא"],[1700400249,"לאחר שנתגלה מהות מציא' החכמ' בפועל גמור וע\"ז נא' והחכמ' מאין תמצא מבחי' אין והעלם דמשפיע בא בגלוי יש דמקבל והיינו תמצא במציאת דבר חכמ' משא\"כ טרם שנתקבלה למקבל אינ' במציא' חכמ' בגלוי כי נמשך לפי אופן מדרגת המשפיע כציור וי\"ו כנ\"ל וזהו ענין חי\"ת דחכמ' שזהו כאשר החכמ' באה במקבל לגלוי אורך ורוחב כו' וזהו בציור אות החי\"ת שהוא ציור פתח כצורת הפתח ממש במשקוף וב' מזוזו' והיינו עד\"מ הפתח שבו יוצאי' לחוץ ובו נכנסי' לפנים כי הוא חלל פתוח לכל כך ענין החכמ' שבא' בגילוי לחוץ במקבלי' נק' פתח העליון שנפתח גלוי אור ח\"ע הנעלם ונק' פתחי חכמ' שהכל נכנסי' בהם לקבל וגם ע\"ש יציאת האור שם מהעלם לגלוי לחוץ (כמו פתח ר' פלוני) והנה כתיב פיה פתחה בחכמה והוא הפה שהוא הפתח שהחכמ' נפתח שם בגלוי הדבור וכל זמן שלא נתקבל השכל בגלוי יש דמקבל כנ\"ל לא יוכל לגלותה בפתח דפה לדבר לזולתו משום דהא בהא תליא וכמשי\"ת בענין חית דלי\"ת כו' (ומשה היה כבד פה להיותו בפנימית אור אבא שלמעלה מבחי' גלוי אור החכמה לחוץ בחית שנק' פתח ונק' פה וע\"כ א' לו מי שם פה לאדם שהוא גלוי פתיחת החכמה כו' וכמ\"ש במ\"א) ואמנם אע\"פ שזהו ירידה גדולה להיות גלוי אור ח\"ע בפתח דציור חית (וכידוע דקמץ בכתר ופתח בחכמ' דהיינו כתר דחכמה בקמץ בסתימות והעלם וגלוי יסוד ומל' דחכמה הוא בפתח והן ג' קוין ימין ושמאל ב' מזוזות וע\"ג המשקוף ובהיות שזהו ההשפעה הבאה למטה גם בחלל בפתח הרי יוכל לבא השפע למטה מטה אל העומדי' בחוץ וכמ\"ש חכמות בחוץ תרונ' גם לחיצוני' בהיכלות הקליפות וכמ\"ש במ\"א בענין חמץ ומצה דבחי\"ת דחמץ לפתח דחטאת רובץ כו' אך זהו בבחי' ח\"ת דמל' בעה\"ד טו\"ר כו' אבל ביח\"ע דאצי' אין שם שרש יניקה כלל לחיצוני' ע\"כ מא' דאחד נמשך חי\"ת כמו משה שהי' כבד פה תושבע\"פ כו' אך מ\"ש מי שם פה לאדם מפני שבפה דחכמה אין שם יניקה לחיצוני' ג\"כ כמ\"ש פיה פתחה בחכמה לפי שבה\"א יש חלל קטן בין הגג לרגל הקצר כו' (וכמ\"ש בפי' המלות דמזמור לתודה כו' בענין מצה בה\"א כו' והוא בחי' הבטול שבח\"ת וזהו ותורת חסד שיכול לברר הכל בבטול היש לאין דבח\"ת אתברירו וזהו תושבע\"פ כמבואר שם באריכו') וז\"ש למען תהי' תורת ה' בפיך וכן אשים דברי בפיך לא ימוש כו' מפיך דוקא שהעיקר מצות ת\"ת בדבור בפה וכמ\"ש כי על כל מוצא פי ה' יחי' האדם הרי בחי' חכמ' בראש דאדם מקבל אור וחיות מן הפה וכמא' רז\"ל למוציאהן בפה דוקא משום דבאמת נעוץ תחלתן בסופן דוקא וכאשר נעשה מן האלף דמשפיע חי\"ת בגלוי למקבל כנ\"ל עדיין אין עיקר השלימות אלא לבסוף יותר והוא כאשר בא בפה בדבור שיוכל לגלות הדבר חכמה שקיבל לחוץ ולא יטה ימין ושמאל כו' אז ממוצא פי הוי' שבדבור דוקא יחי' האדם בחי' חכמ' שבראש וזהו שמן החי\"ת נעשה דלי\"ת בצרופי אותיות דאחד שהדלי\"ת הוא בחי' הדבור שבחכמ' כמו פיה פתחה בחכמ' כנ\"ל והוא דלית רבתי להיותו בבחי' גדלו' הדבור כמו שהוא בשרשו בגלוי אור חכמה הקדומה שנעוץ תחלתן בסופן (ונק' רוח ממללא בחי' מדבר שזהו עיקר שלימות דבחי' אדם כידוע) וזהו כללות ענין סדר צרופי אותיות דתיבת אחד א' ואח\"כ חי\"ת ומחית דלית רבתי ופרטיו' ענין החי\"ת ודלי\"ת ית' בסמוך וד\"ל (ובכ\"ז יובן מ\"ש והחכמה תחיה בעליה פי' בעליה דחכמה שהוא בחי' המשפיע לחכמה מאין והעלם מקור חוצבה כו' והוא מפני שהחכמ' בה\"א הוא גלוי אורה למקבל כנ\"ל ומה גם כשבא בגלוי גמור שבפה שמזה יחי' האדם כנ\"ל לכך החכמ' בה\"א דוקא תחי' לבעלי' דחכמ' כו' דנעוץ תחלתן בסופן דוקא כנ\"ל אך היא גופא יש להבין למה יהי' כח ועוז יותר בגלוי מעצם דח\"ע שבראש עד שתחי' לבעלי' ואם מפני"],[1700400250,"שנעוץ תחלתן בסופן הרי כך נעוץ סופן בתחלתן ולמה יהי' כח הסוף גדול מן התחלה ואדרבה הרי עיקר הדבור בה' מוצאו' הפה הוא נמשך מן החכמ' שבראש כידוע דאבא יסד ברתא וכמו מצרף לחכמ' ולכך נק' מדבר רוח ממללא כמשי\"ת בסמוך אך באמת אינו מובן גם מ\"ש מי שם פה לאדם דאדם הוא בחי' חכמ' אדם שנק' מדבר ואם אין לו פה מצד עצמו לא נק' אדם כלל וא\"כ איך אמר מי שם פה לאדם הלא אנכי דווקא אך הענין הוא דפה זה הוא מה שיש בכח הפה לברר ברורים דעה\"ד להבדיל הפה בין טו\"ר וכענין תושבע\"פ מל' קרינן לה כמו מתניתין מלכתא כמלך שגוזר כו' כידוע ומבואר במ\"א עד\"מ חכם גדול שאינו יכול לפרנס א\"ע בחכמתו או לתקן בחכמתו דבר שנתקלקל אינו חכם כי לא עמדה לו חכמתו להחיות נפשו או לתיקון דבר המעוות כו' אעפ\"י שבקי בכל חכמ' כי עיקר שלימו' החכמ' באה במה שיוכל בחכמתו למצוא טרף לנפשו כו' וזהו פי' הפשוט דוהחכמ' תחי' בעליה כידוע והדוגמא מזה נק' תורתו אומנתו פי' כלי אומנתו להחיות לבעליה דחכמ' והוא בבחי' הבירורי' שבחכמ' תתאה שבדבור לברר ולתקן כו' נק' כלי אומנות להחיות שרש חכמתו הנק' בעניה שזה מגיע בשרש ומקור הראשון דכתר בבחי' העצמו' שבה למעלה מהיות מקור לחכמ' הנ\"ל ע\"כ תחיה בעליה דחכמ' שנתוסף כח ושרש עצם חכמתו שנק' ח\"ס כו' וז\"ש יהב חכמתא לחכימין דוקא שהוא ח\"ת שבפה לברר וזהו כי לא על הלחם שהוא בחי' החכמ' בשרשה במזלא גי' לחם יחי' האדם בחי' החכמ' שבראש אלא על כל מוצא פי הוי' דחכמ' שבדבור לתקן עה\"ד כו' שנק' תורתו אומנתו יחי' האדם אמנם מי הוא הנותן כח בפה זה מאחר שזה בא מלמעלה מבח' אדם אחר שממנו יחי' האדם ויקבל כו' הנה לזה אמר מי שם פה זה לאדם לא האדם בעצמו מאחר שיחי' ויקבל ממנו אלא אנכי שהוא אור א\"ס שבעצמות הכתר הנק' אנכי כו' וזהו טעם עיק' מצות ת\"ת בפה וגם משה שהיה כבד פה מצד שרשו בפנימי' ח\"ע א' לו אנכי אהיה עם פיך כו' וגם במ\"ת נא' תורה צוה לנו משה בע\"פ כו' ובכ\"ז יובן בתוס' ביאור ענין חית ודלי\"ת רבתי שהעיקר הוא בדלי\"ת רבתי שהוא כח הדבור שלא כמ\"ש בסמוך דשרש כח הדבור מן החכמה לבד כו' וד\"ל:\n(ס\"ז) <b>ומעתה</b> יש להבין בתוס' ביאור בפרטיות ענין החי' והדלי\"ת רבתי דאחד הנ\"ל ומשארז\"ל על אות החי\"ת ודלי\"ת תמליכהו בז' רקיעים וארץ וד' רוחו' כו' והנה יש להקדים תחלה בביאור ענין הדלי\"ת רבתי שהוא בבחי' עולם הדבור למה הוא דלי\"ת רבתי וידוע דאבא יסד ברתא ששרש בנין הדבור נמשך דוקא מן החכמ' וכמ\"ש ה' בחכמ' יסד ארץ כו' אך הנה ידוע שיש ב' מדריגות בדבור א' מקור ושרש כח הדבור בעצם כמו שהוא נמצא מאור החכמ' דאבא יסד כו' והב' בחי' צרופי אותיות הדבור כמו שהן באין בגלוי בה' מוצאו' הפה ותחלה יש לבאר מדרגה הב' הזאת שבדבור שהוא בחי' התחלקות צרופי אותיות הדבור העליון כמ\"ש בס\"י וקבען בפה כו' והן רבוי שינויי הצרופי' לאין שעור כמ\"ש בס\"י ה' אבנים בונו' ק\"ך בתים שהן אותיות שנק' אבנים וה' אותיות יש בהן ק\"ך צרופי' כמו שם אלקי' בכלל הן ה' אותיות ויש בהן ק\"ך צירופי' שהן כללות ההשתלשלו' דג' עולמות בי\"ע (וממ\"ח צרופי' האחרונים מקבלים החיצונים הנק' אדמת בני חם כו') (וכתיב צדיק מושל ביראת אלקים שיכול לשנות בק\"ך צרופים דאלקי' כמו רחב\"ד שאמ' מי שאמר לשמן כו' כמ\"ש במ\"א) וצרופים הללו מתחלקים לאין שיעור כלל כמ\"ש בס\"י מכאן ואילך צא וחשוב עד אין שיעור"],[1700400251,"כו' (וטעם שאין מספר הוא לפי שאין שיעור לקדמות השכל לצרף באופנים שונים כמ\"ש מצרף לחכמה כו') אך מ\"מ מה שבא ונמשך באופן צירוף מיוחד ממנו נברא בריאה פרטי' וכל אות ואות הוא בחי' המשכ' מיוחדת בפ\"ע כידוע דכל מלאך נברא מאות וצירוף מיוחד פרטי' ולזה אנו רואים בבחי' התחלקו' המדרגות בנבראי' שאין כל א' דומה לחבירו הגם שהוא במין א' כמו בחלקי דצח\"ם שאין דומם זה דומה לחבירו גם במין א' כמו במיני האבנים ובמיני המתכות ובמיני עפר רבים הן בהתחלקות שונות וכן בבחי' הצומח אין עשב דומה בצורתו ופעולתו לחבירו וכן בחלקי החי' גם במין א' אין א' דומה לחבירו וכן במדבר זה טבע שכלו כך וזה טבע שכלו להיפך גם שהן משרש א' אם מחסדי' לטוב או וכו' וכן במדו' האדם אין א' דומה לחבירו גם באותן שהן ממדרגה א' מחסדי' או מגבורו' וכ\"ז מפני שגם למעלה בשרש הרוחני של הגשם דדצח\"מ בא בהתחלקו' צירופי' בהמשכו' שונות והוא מצד ריבוי שינוי צירופי אותיות שמתחלקים לאין שעור כנ\"ל וע\"ז א' דוד מה רבו מעשיך שרבו למעלה לאין שיעור כו' וכך הוא במחנות שכינה במלאכי' עליונים כמחנה גבריאל מסטר' דגבורה כן במחנה מיכאל מסט' דחסד מתחלק לאין שעור כו' הגם שכולן מסט' דחסד וכמ\"ש היש מספר לגדודיו הו' ואע\"פ שנזכר מספר אלף אלפין ישמשוני' ורבוא רבבן כו' אבל לגדודיו אין מספר (וכמ\"ש ביאור זה במ\"א בענין שעור קימה של יוצר בראשית רל\"ו אלפים רבבות פרסאות כו') וכך הוא בכל עולם ועולם לפי ערכו עד עוה\"ז השפל דד' חלקי דצח\"מ ג\"כ מתחלקי' לרבוא רבבות מדרגות חלוקות כל א' למינהו כנ\"ל וד\"ל והנה ידוע ומבואר במ\"א בטעם ריבוי התחלקות הנ\"ל שבכל עולמות אינו רק מצד בחי' ההתכללות דע\"ס דאצי' באו\"כ שמפני ריבוי מיני ההתכללות יבא דוק' סיבת ריבוי ההתחלקות דע\"ס דאצי' לכמה אופנים שונים וכידוע שנחלק כל ספי' לי\"ס וי' לי' עד שיש ת\"ר אלף בו\"ק כו' ומבחי' ריבוי ההתחלקות דע\"ס דאצי' בא ריבוי ההתחלקו' צרופי אותיו' הדבור העליון כידוע דהמדות דאצי' נמשכי' לבחי' הדבור כמ\"ש בס\"י וקבען בפה כו' ומהתחלקות צרופי דבור העליון שזהו בחי' מל' דאצי' כידוע הנה מזה בר רבוי ההתחלקות המשכות שונות בג' עולמות בי\"ע עד עוה\"ז השפל כנ\"ל (אך הנה י\"ל איך יולד דבר מהיפוכו שמן רבוי ההתכללות יבא דוקא רבוי ההתחלקות דלכאורה ההתכללות וההתחלקות הן ב' הפכים ממש ואיך יולד דבר מהיפוכו כו' והנה הביאור לדבר זה ידוע בענין בחי' התיקון והתוהו כו' שע\"ס דתהו היה בהתחלקות ואח\"כ היה בחי' התיקון שהוא בחי' ההתכללות דע\"ס זע\"ז כמו גבורה שבחסד עם חסד שבגבורה כו' וכללות הענין הן י\"ב גבולי אלכסון כידוע ובאמת יש כאן ג\"כ קושיא דלעיל איך יהי' ההתכללות דתקון היפך ההתחלקות דתוהו שהיו זה תחת זה כידוע ומבואר במ\"א שההתחלקו' דוק' עוש' ההתכללו' עד\"מ כאש' יחולק דבר מה לחלקים רבים מאד אז יותר יוכל להיות ההתכללות במיני מזיגות והרכבות החלקי' הרבים בכל מיני אופנים שונים וכל שלא יחולק כ\"כ לא יוכל להיות הרכבת ומזיגת אופני' פרטיי' כ\"כ כמו צירופי אותיות הדבור כל שהן רבי' יותר יותר יהי' ריבוי אופני צרופיהן א\"כ לפ\"ע ריבוי ההתחלקו' דוקא יהי' ערך ריבוי ההתכללות והמזיגות דבר והיפוכו בכמה אופני' שוני' וכמו בהרכבת ד\"י גשמיי' כל שיחולק הדבר יותר יותר יוכלו להרכיבו בכמה הרכבות שונות כו' ומזה יובן ממילא שאחר ריבוי ההתכללות יבא מזה דוקא ריבוי ההתחלקו' ג\"כ לפ\"ע א' ממש וכמו"],[1700400252,"שאנו רואי' בדבר המורכב ביותר שיוכל לחלקו יותר לחלקי' רבים ונמצא ההתכללו' עושה ריבוי ההתחלקו' ואינו דבר והיפוכו דהיינו הך ממש כמו שמן ההתחלקות נעשה ההתכללות כך מן ההתכללו' נעשה ההתחלקו' והא בהא תליא לפ\"ע ממש דהיינו לפי ערך ריבוי ההחלקו' יהי' ערך ההכללות ולפ\"ע ההתכללות יהי' ההתחלקו' אחר בחי' ההתכללות דתיקון שבע\"ס דאצי' והוא מה שנמשך אור האצי' בבי\"ע בו' ימי המעשה כל יומא בעבידתי' דוקא כמ\"ש בזהר וכה\"ג וס באצי' עצמו נמצא ריבוי ההתחלקו' בכל ספי' עד אין שיעור כו' וכידוע בענין נקודה ספירה פרצוף כו' וכן בבי\"ע פני ארי' להימין כו' ולא ישנו תפקיד' כי כל א' למינהו דוקא כמו שלא יהופך למט' בטבע השור לטב' הארי' וכה\"ג עד דצח\"מ דעוה\"ז שאין כל א' דומ' לחבירו וכמ\"ש למינהו בכל הברואי' הנה כ\"ז אינו בא רק דוק' מסיבת בחי' ההתכללות דתקון שהו' כמו חלוף האורות בכלים כמו אור החסד בכלי הגבו' וכה\"ג וכללות ענינו הוא יב\"ג אלכסון שבו\"ק דז\"א כמ\"ש בפרד\"ס וד\"ל (אך א\"כ לכאורה מהו ההפרש בין בחי' התחלקות דבחי' התהו זת\"ז שהי' מחמת שבה\"כ כידוע ובין בחי' התחלקות שלאחר התכללות דתיקון שאין בזה בחי' שבירה כלל הענין מבואר במ\"א דהתחלקו' דתהו היה בבחי' נקודו' דהיינו בבחי' עצמיו' דכתרים שהוא ההתחלקו' מתחלת ההוי' כו' אבל התחלקות שבאה אחר התכללו' זה בא מכחו של בחי' ההתכללות דוקא שאינו התחלקו' מתחלת הוי' כו' אדרבה מהיחוד יצאו לחלק עד\"מ עץ המורכב מאש ומים שמחלקן לחלקי' וכמ\"ש בס\"י טרף אש ומים ובללן יחד כו') והנה ידוע דאופני ההתחלקו' בשכל ומדו' שבאדם יוכל להיות עד אין שיעור כמו שאנו רואי' שבטבע א' דמדה א' כמדת הנצחון וכה\"ג יש בה ריבוי התחלקות מיני מדרגות בבני אדם זה טבע נצחונו כך וזה כך ויולדו דור אחר דור כמה אלפי' רבבות בני אדם וכל א' אינו דומה לחבירו במדת הניצוח וכן במדת התפארות יתחלק לאין שיעור וכן במדת החסד והגבורה לטוב ולרע אין שיעור לאופני התחלקותן בטבעי בנ\"א דור אחר דור וכן בשכליי' דבנ\"א דור אחר דור בא בריבוי אופנים שונים גם במדרגה א' כמו בטבע החסד שבחכמ' להטות כלפי חסד וזכות כמו חכמי' המה להטיב כו' מתחלק בכמה רבבו' בנ\"א באופני' שונים שאין א' דומה לחבירו כנ\"ל וכן ברצון ותענוג יש מתענג ורוצה כך כו' וזולתו לא יתפעל מאותו תענוג כלל הגם שהן במדרגה א' מסט' דחסד או דין וכה\"ג וד\"ל וכך יובן למעלה בע\"ס דאצי' שהוא בחי' המוחין ומדות דז\"א דאצי' שנק' אדם העליון כידוע שיבא בריבוי התחלקו' באופנים רבים במדות דחג\"ת נה\"י לאין שיעו' כלל עד שאין א' דומ' לחבירו גם בסט' דחסד לבד או גבורה לבד ולכך אין יום ושעה דומה לחבירו שבכל שעה יש צרוף חדש משם הוי' כידוע בענין יב\"ש הוי היום וכתיב דור הולך ודור בא כו' וכן דור לדור ישבח וכו' וכתיב וממשלתך בכל דור ודור הרי בכל דור ודור מתחדש האור ושפע דע\"ס דאצי' בבי\"ע ואין דור דומה לחבירו ובכל דור יש רבוא רבבות מדרגות כו' וכמ\"ש בזהר ע\"פ והימים ימי בכורי ענבים שאותו הזמן הי' עת המשכת בחי' גבורו' דאימא במדות דז\"א שנק' ימים בכלל ובפרט כו' וכה\"ג וד\"ל ואמנם הנה סיבת רבוי התחלקות הזאת באה דוקא מסיבות ריבוי ההתכללות דע\"ס דאצי' זע\"ז כנ\"ל (משו' דהא בהא תליא לפ\"ע ממש כנ\"ל) וסיבת ריבוי ההתכללות הוא דוקא ע\"י בחי' החכמה שכוללת הכל וכמ\"ש כולם בחכמה עשית וכמארז\"ל במאמר א' יכול להבראות והוא"],[1700400253,"מאמר דבראשית כידוע וזהו כללות תוכן הענין בביאור אות חי\"ת ודלי\"ת רבת' דאחד שהוא בחי' החכמה שעושה בחי' ההתכללות שלמעלה מן ההתחלקות ומזה יבא בחי' ההתחלקות אח\"כ וכך הוא ענין הדלי\"ת רבתי שהוא כח ועצם הדבור הכולל כל צרופי אותיות הדבור שלמעלה מהתחלקו' צרופי הדבור כו' ולכך הן באין כסדרן בצרוף אותיות דאחד א' כתר דחכמה וחכמה שכולל ההתחלקות עד כח ועצם הדבור שכולל התחלקות הדבור בפרטי פרטיות והכל בבחי' יח\"ע דאצי' עצמו וד\"ל):\n(סח) <b>והנה</b> להבין כ\"ז בתוס' ביאור איך שהחכמה היא הכוללת כל מיני ההתחלקות וגם כח הדבור כו' הנה התחלקות המדות מבואר למעלה בבחי' המדות שבאדם איך שאין א' דומה לחבירו וכמו שאנו רואי' בעבודה שבלב בתפלה שיש מתפעל כך ויש מתפעל כך וכמ\"ש ותוכן לבות ה' כו' ותוכן רוחות ה' פי' לבות הן התפעלו' המדות שבלב יש מתפעל בחדוה ויש מתפעל במרירות וגם שהתפעלות שניהם מדבר א' והוא משום שבהתפעלות המדות שבשכל יש מתפעל כך בשכלו וזה כך אעפ\"י שהשכל א' והיינו ותוכן רוחו' ה' שאין דעותיהן שוות וכידוע שיש ב' מיני מדות מדות שבלב ומדו' שבשכל וכל מיני התחלקו' המדות שבלב בכמה אופני' שונים הכל הוא רק לפי אופן ריבוי התחלקו' המדות שבשכל דוקא ולכך השוון כא' תוכן לבות ותוכן רוחות שהלב והרוח ענין א' שהן בחי' המדות רק שהמדו' בלב הן התפעלו' הלב ומדות שבשכל נק' רוח והוא התפעלות השכל ולמעלה ממקור המדו' שבשכל הוא בבחי' מוח החכמ' דוקא לפי שבבינה שהוא מוח ההשגה כבר יש מקור להתפעלות השכל לחסד או דין או אהבה ויראה או חדוה ומרירות וגם בבחי' תמצית ההשג' דבינה הנק' עומק המושג שהוא פנימי' בינה גם שם מוכן ועומד להתפעל באופן מיוחד רק שכלול עדיין כעובר במעי אמו ויוצא מיד לגלוי מאחר שנק' אם הבנים כידוע משא\"כ בנקוד' דחכמ' אין שם גם בהעלם להיות התפעלות מיוחדת כחדוה או מרירות רק ההתפעלות בנקוד' חכמ' שנק' ראי' כידוע היא היולית לא נודע עדיין באיזה אופן יבוא גם התפעלות השכל כשיבא בהשגה ולזאת ממילא מובן שהחכמ' כלול הכל בה מה שעתיד לבא לידי גלוי במוח ולב והוא אמיתי' המקור לכולם יחד ולפ\"ז יובן גם בענין בחי' התכללות המדות שהוא כאשר יבא אור המדה במזיגה והרכבה מחו\"ג וכה\"ג שהוא ג\"כ באופן מיוחד הוא מורכב וא\"כ יש כמה מיני הרכבות ומזיגות לאין שיעור כנ\"ל הנה ודאי הכל ימצאו בגלוי כאו\"א בפ\"ע במדות שבלב ובמדו' שבשכל וגם בעומק המושג כאו\"א יש לו מקום שם בהעלם שמיד יבא לגלוי כנ\"ל אבל בנקוד' חכמ' לא שייך לומר כלל שכלולי' שם כל ריבוי אופני התכללות המדות גם בבחי' העלם אלא שהחכמ' הוא בחי' כח היולי שממנו יבא כל מיני התכללו' של המדו' בשכל שבמוח בלב אח\"כ אבל בחכמ' עצמה אין שם הבדל כלל בין חדוה למרירות גם בהיותן בבחי' התכללו' ומזיגה ולא יתכן שם לומר לא התחלקו' המדות ולא התכללו' שלהם באופני' שונים אלא כולם כא' ממש נכללים בה בבחי' כח היולי ופשוט מבלי ימצא עדיין להתחלקו' או התכללו' ע\"ד הדוגמא שצופה ומביט על דבר מה שנסקר כל חלקי' שבו כא' מבלי יש קדימה לזה החלק ע\"ז החלק כמ\"ש במ\"א שנק' מח' כללית ואמנם כאשר יסולק אור החכמ' אז מן החכמ' ולמטה מסתעף שיש ההתחלקות והתכללו' המדות דשכל ולב כאו\"א בפ\"ע כנ\"ל וממילא נמשכים בדבור בצרופי התחלקו' רבי' כנ\"ל וד\"ל והנמשל מזה ידוע למעלה במדות דז\"א ששרשם במדו' דבינה שנק' אם הבנים"],[1700400254,"שע\"ז א' לך ה' הגדולה כו' שהן בריבוי ההתחלקות ובריבוי ההתכללות כנ\"ל באריכות הנה גם בבחי' פנימי' בינה יש לכאו\"א מקור בפ\"ע אך ורק בבחי' נקודה דאור אבא שם הוא בחי' כח כללי שכוללם יחד בסקירה אחת מבלי ימצא מקור עדיין לבחי' התחלקו' והתכללות אלא כולם מתייחדי' שם כא' ממש וכמ\"ש כולם בחכמה עשית שבחכמה כולם כא' עשי' א' נחשב למעלה מן ריבוי התחלקות והתכללו' כו' וד\"ל אבל מן החכמ' ולמט' יבא דוקא רבוי ההתחלקות וההתכללות והוא מבינה ולמטה כמו במדות שבמוח ולב כנ\"ל והן רבוי הצרופים שבדבור העליון כו' ומעתה יש להבין איך שגם בבחי' הדבור יהיה מדרגות חכמה שהיא למעלה מן ההתחלקו' כו' והוא בחי' כח הדבור דוקא כמו שהוא נמצא מעצמות אור החכמה כנ\"ל ולא צרופי אותיות הדבור עצמן שהאותיות כבר בהתחלקות וממילא יבאו בכמה מיני התכללות שהן רבוי אופני הצרופי' שהצרוף הוא חבור האותיות (דהיינו ג\"כ ע\"ד הנ\"ל במדות שההתחלקות עושה ההתכללות וההתכללות עושה ההתחלקות והכל א' ממש כנ\"ל) וזהו פי' חי\"ת ודלי\"ת רבתי דאחד שהוא בחי' החכמה הגם שכבר באה מהעלם של המשפיע לכך הוא בציור חי\"ת עכ\"ז לגבי למטה הימנה היא בבחי' כח כללי שכולל כל מה שעתיד להיות התחלקות והתכללות כנ\"ל וזהו שאמרז\"ל שהח' כולל ז' רקיעים וארץ כו' שזהו כל חלוקי השפע של ז' המדות שבשכל ולב לדבור בעלמא דאתגליא שנק' ארץ כמו תוציא הארץ כידוע ואח\"כ יבא כללי' זה בדלי\"ת רבתי ג\"כ בבחי' זו ממש והיינו כח הדבו' דוקא כמו שהוא בעצם טרם שידבר הנק' רוח ממללא נפש המדברת כנ\"ל שכולל כל מה שעתיד להתחלק ולהתכלל בצרופי הדבור כא' ממש ע\"ד הנ\"ל בחית דחכמ' לגבי המדות שבשכל ולב וד\"ל: ולהבין בתוס' ביאור ההפרש בין כח הדבור להדבור עצמו הנה יש להקדים בענין ג' לבושי הנפש מדו\"מ ויובן ענין לבוש הדבור מלבוש המעשה דאנו רואי' בכח המניע תנועה שהתנועה והמעשה עצמה נפעל מכח הפועל והמניע בשינויי אופני רבי' לאין שעור להתפשטו' התנועה והפעולה אבל עכ\"ז ודאי אין ערך בזה שיוכל לבא לכל כח התנועה כמו שהיא בבחי' היולי בהתפשטות הפעול' גשמי' גם שיחי' אלף שנה לא יוכל להביא כל כח רוחני שביד שבבחי' כח היולי לידי פעולה גשמי' מאחר שזה רוחני וכח עצמי וזהו רק התפשטו' וא\"א שישיג גשם הפעולה לכח הפועל הרוחני וההיולי ולזה נקרא גשם הפעולה בשם לבוש חיצוני וכח המניעה התנוע' הגשמי' נק' בשם כח הפנימי דמעשה שאינו נק' לבוש וכך הוא בדבור בחי' התפשטות הדבור באותיות אין לו ערך לעצם כח הדבור הרוחני שנק' רוח ממללא או נפש המדבר' שגם באלף שנה לא יוכל להביא כל כח הדבור הרוחני ההיולי שבנפש לפועל הדבור בה' מוצאות כי עצמו' כח הדבור ההיולי הוא כח רוחני שבנפש הרוחניות מה שיוכל להמשיך תמיד לפעול בצרופי' שבדבור הגשמי (כידוע דיש כ\"ב אותיו' רוחניי' בנפש ונק' כ\"ב כחות תנועה כו' ונק' דבור הרוחני ומה שיוצא בה' מוצאות נק' דבור ומבטא גשמי שהרי אין סיבת הדבו' בתינוק קטן מצד עצם המוצאו' כידוע דא\"כ הי' יכול לדבר קודם שיושלם ימי היניקה אלא כשיבא בנפשו כח הדבור הרוחני שנק' רוח ממללא דהיינו בחי' אותיות רוחניי' הקבועים בנפש (כמו ב' רוחות מספרות וכן וקרא זא\"ז וכמ\"ש במ\"א) אז יוכל לדבר דבור גשמי כי אותיות הרוחניי' מניעות המוצאו' כידוע ולפ\"ז הצרוף דה' מוצאות כבר נעשה ברוחניו' הדבור ולפי אופן הצרופי' שבדבור הרוחני כל יומשך בדבור הגשמי ולפ\"ז גם צרופי' שברוחניו' הדבור גם זה נק' לבוש לגבי עצם כח הדבור"],[1700400255,"הרוחני שבנפש טרם שידבר דבור הרוחני כו' והוא עצמו כח הדבור שבמבטא הגשמי כי אין לחלק בין כח הדבור הרוחני לכח הדבור הגשמי כי הכל א' משא\"כ מרוחניו' אותיות הדבור לגשמיו' אותיות שבה' מוצאות יש הפר' גדול כו' אבל במח' אין הענין כן כי אין שם הפרש בין רוחניות לגשמיות כמו באותיות הדבור שהרי אותיות המח' רוחניי' הם וכח המח' טרם שיחשב באותיות אינו רק כח כולל כל האותיות כמו כח הדבור הרוחני שכולל כל אותיות הדבור הרוחני כו' ויובן מזה ההפרש למעלה בין עלמין דאתכסיין שמתהווים מאותיות המח' עליונה שמעלתם הגבה למעלה מעולמות שמתהווים מדבור הרוחני (וכידוע בענין וקרא זא\"ז שדבור שלהם רוחני' כמחשבה שלנו ומה שאצלם מח' ודאי למעלה מן הדבור הרוחני שלהם כמו המח' של הנפש שלמעלה מן הדבור של הנפש כו' (וכמו נשמו' שנק' נוני ימא רבא כו' וכמ\"ש בזוהר בפי' וידגו לרוב כו' וכן ביו\"ד נברא העוה\"ב ביו\"ד שבמח' ובה' שבדבור נברא העוה\"ז עלמא דאתגליא מאין ליש גמור כמו בדבר ה' כמשי\"ת) אך ענין לבוש גשם המעשה שנמשך מכח המעשה הרוחני יותר קרוב בערך זע\"ז מערך גשם הדבור לרוחניות שבנפש בלא ה' מוצאו' שרחוקים ונבדלים בערך ביותר כו' ובדרך התלבשות מתלבש המח' בדבור ודבור במעשה בפ\"מ והיו לאחדי' לגמרי כמ\"ש במ\"א:\n(סט) <b>והדוגמא</b> מכ\"ז יובן למעלה בבחי' דבור העליון כמ\"ש בדבר ה' שמים כו' שיש בו ב' מדרגות א' גופו של הדבור כשמתחלק בצרופי' הרבה שאינו רק בחי' המשכה חיצוניות בעלמא מבחי' ומדרגה הב' שבדבור העליון כמו שהוא עצם כח הדבור הנ\"ל שנק' רוח ממללא כו' והיינו מ\"ש לעולם דברך נצב בשמים פי' דברך בחי' עצם כח הדבור העליון (והיינו כנ\"ל בבחי' אותיות רוחניי' שבנפש שהוא כח ועצם דבור הרוחני שהוא מקור לדבור ומבטא שבפה כו') ומשם שרש וכח היולי להמשיך צרופי אותיות הדבור לאין שיעור ואין שם שינויים והתחלפות כלל כמו שבצרופי אותיות הדבור יש שינויי' והתחלפות רבים כי הוא עדיין בחי' מקור הילוי לפעול פעולת והמשכות כל הצרופים שבה' מוצאות כנ\"ל ואין ערך ביניהם כמעשה הגשמי' לגבי הכח דמעשה הרוחני (ויותר יש רחוק ערך ביניהם כנ\"ל בפרטי ענין הג' לבושי' מדו\"מ) (והוא הנק' בחי' כתר מל' שדבוק בחזה דז\"א וז\"ש דברך נצב בשמים שהוא מדו' חצוניות דז\"א וכמ\"ש בע\"ח כמו שאנו רואים שכח עצם הדבור הוא בחזה הלב אם לרבות הדבור או למעט דהיינו אם הלב בכווץ יקצר הדבור ואם הוא בהתפשטות ירחיב הדבור אך לא שמשם יוצא מקור כח זה אלא שדבוק ושוכן שם כו' וד\"ל) וז\"ש ודבר דבר שבשבת הוא זמן עליות העולמות שנמשכים מצרופי' שבדבור ועולין למקור וכח עצם הדבור העליון שהוא בחי' כתר דנוק' כנ\"ל ששרשו בעצמו' דאור אבא דהיינו מ\"ש דאבא יסד ברתא אך הנה ידוע דפי' יסד זה היינו בב' אופנים א' כח המצרף ומחבר האותיות מה' המוצאות כמו מצרף לחכמה שזהו בא דוקא מכח פנימי' דעצמו' כח השכל (שלמעלה מנקוד' חכמ' שמבריק כו' והוא הנק' קדמות דשכל והיינו מאותו מקור הראשון שמשם נמשך עצם כח השכל דלכך דוקא בשלימות כח עצם השכל יוכל לצרף כו' וכמ\"ש במ\"א) והב' בהתהוות עצם כח הדבור הנ\"ל שהוא נמשך דוקא ג\"כ ממקור של כח השכל להשכל שזהו למעלה בחי' מקור דח\"ס כו' כנ\"ל ולפ\"ז הרי הוא היפך ענין החי\"ת ודלית רבתי דחי\"ת זה מדבר בחכמ'"],[1700400256,"שבאה מן ההעלם לגלוי עכ\"פ ואיך יהיה מזה מקור לבחי' כח ועצם הדבור שהוא דלית רבתי אדרבה היה צריך שיהי' אות הא' שהוא במקור החכמה להאיר בדלית רבתי כו' ולא מן החי\"ת בדלי\"ת ואם מטעם ההתכללות ההיולי שבחי\"ת דחכמה הנ\"ל שבזה דומה לו הדלית רבתי אין זה רק ענין הדומ' בלב' ולפי סדר הצירופי' דאחד משמ' דכמו שמן הא' נעשה חית כך מן החית נעשה ד' רבתי ואין האמת כן כנ\"ל בפי' אבא יסד כו' אלא מוכרח לומר כנ\"ל (בססי' ס\"ו) בענין מי שם פה לאדם כו' דבחי' כח הדבור שרשו למעלה ממקור החכמ' ע\"כ והחכמ' תחי' בעליה דחכמ' ועל מוצא פי ה' דוקא יחי' האדם כו' פי' מוצא פי כו' מקור וכח עצם הדבור וזהו מעלת החי\"ת דחכמ' ג\"כ שהוא בחי' כח בירור דחכמ' כשהוא מתקן ומוצא טרף רפ\"ח כו' שחכמתו עמדה לו כו' כנ\"ל ולפ\"ז החי\"ת ודלי\"ת רבתי ענין א' אלא שמחי\"ת דחכמ' שהוא כח הבירור שיש בחכמ' בא ונמשך בפה ששם כח הדבור והיינו שמן החי\"ת נעשה דלי\"ת כו' וכמ\"ש פיה פתחה בחכמ' לברר כו' ומ\"ש ודבר דבר היינו בשבת שהבורר אסור ולכך לא נמשך מכח הדבור דפה לברר בעה\"ד וז\"ש ודבר דבר שהמל' נק' דבר מלך שלטון וזה יותר נכון מפי' דלעיל שבחי' צרופי' שבדבו' עולה למקור וכח הדבור כו' דא\"כ הי' ביטול היש לאין לגמרי מפני שבטלים הי' מאמ' בכח הדבור כמו השתיקה וכתיב דבר אלקינו יקום לעולם וכן דברי אשר יצא כו' לא ישוב וכמ\"ש במ\"א וד\"ל) ועתה יובן ענין דלית רבתי שהוא גדלות הדבור והוא כמו שהדבור נמשך בכח הדבור משרשו בעצמות כח החכמה כמו עד\"מ התינוק שלא יוכל לדבר ולצרף צרופי' עד שנשלם בכח החכמה בנפשו וזהו שנק' נפש השכלית נפש המדברת ועיקר שם אדם הוא כשהוא בחי' מדבר שבזה יתרון מעלתו על החי כי הא בהא תליא שכח הדבור נמשך מן השכל דוקא וזהו שמן הח' דחכמה נמשך דלית רבתי בחי' כח הדבור כו' (ולפי המבואר בכונות דא\"ח דלית היינו ע\"ס דז\"א שמשם נבנ' בנין המל' כו' זהו כענין הנ\"ל בכח של הדבור שהוא דבוק בחזה הלב ששם גלוי המדות כמ\"ש לעולם ה' דברך נצב כו' שמא\"ח נשעה דלי\"ת רבתי כתר דנוק' ואח\"כ מתפשטת בע\"ס שבה בבי\"ע שהוא בשכמל\"ו כידוע) והנה כל תיבה זו דאחד הוא הכל בבחי' יח\"ע שהן ע\"ס דאצי' וכללותם הן ג' דברים חכמ' ומדו' ודבור והן ג' אותיות האלה א' וחי\"ת וד' שיוצאי' כסדרן ע\"ד הנ\"ל והכל למעלה מבחי' התחלקו' המדו' עדיין כי הנה הדלית רבתי הוא כח הדבור שלמעלה מהתחלקו' ושינויים שבדבור כנ\"ל והוא מקבל מחי\"ת דחכמ' כנ\"ל דאבא יסד ברתא שהמדו' כלולים בתכלית בחכמ' שהוא כח היולי של המדות שיבואו מן ההעלם מבינה כנ\"ל והחי\"ת נמשך מן הא' שהוא בחי' מקור והעלם החכמ' כמו שהחכמ' מאין תמצא כנ\"ל שהוא בחי' בטול כח מ\"ה כו' ע\"י מזל ונוצר עד מקור החכמ' בעצמו' המאציל לפי שידוע שאין אא\"ס שורה רק בבחי' הבטול דמ\"ה ואין דחכמ' ולא בבחי' יש כלל ולכך ראישת גלוי אא\"ס אינו אלא בחכמ' כמ\"ש ה' בחכמ' כו' ונמצא שכל ג' אותיות דאחד הכל בבחי' יח\"ע דאיהו וחיוהי חד שהוא בבחי' תכלית היחוד והבטול לגבי עצמו' אא\"ס שלמעלה מבחי' ההתחלקו' וההתכללו' כו' כנ\"ל וזהו שארז\"ל בחית כדי שתמליכהו בז' רקיעי' וארץ שהוא שמי' וארץ ובד' כו' שהוא בטול המדות בחי' ו\"ק באחדות הפשוטה כמ\"ש לך ה' הגדולה כו' וכידוע וזהו כללות פי' האמיתי דאחד שנק' יח\"ע קודם שבא לחלופי אתוון דועד בחי' יח\"ת כי כל ענין החכמה ומדות ודבור שבאחד הכל למעלה מבחי' ההתחלקות לגמרי אלא המה כלולים ומיוחדי' בתכלית בעצמות אא\"ס הפשוט כו' ויובן דבר זה דרך קצרה עד\"מ באדם"],[1700400257,"למטה שעצם כח החכמה ועצם כח המדות ועצם כח הדיבור כלולי' ומיוחדי' בעצמות הנפש בלי ניכרי' למהו' דבר מה דכלא חשיבי לגבי העצמות וכלולי' זע\"ז משא\"כ בהתפשטות החכמ' במדות ומדות בדבור כל אחד ברבוי התחלקות והתכללות שונות כו' וכך למעלה זהו כללות ענין ההפרש בין יח\"ע דאיהו וחיוהו חד כו' ונק' ע\"ס בלי מה כידוע בין יח\"ת שהוא בחי' התפשטו' חכמה ומדו' ודבו' שזהו ענין ועד בחלופי אתוון כו' [והנה באמת גם בע\"ס דאצי' הרי יש בחי' התחלקו' והתכללות כנ\"ל רק שבתיבה זו דאחד מדבר בבחי' עצמו' דכללו' ע\"ס דאצי' שהן בחי' כתר שבחכמ' ומדות ודבור והוא הא' וחי\"ת ודלי\"ת דרך כללות] ולהבין זה וגם להביןלמה הדלי\"ת רבתי ולא הא' וחי\"ת מאחר שהכל בבחי' עצמו' שלמעלה מן ההתחלקו' כו' ויש להקדים שיש בכלל ג' מיני אדם זה למעלה מזה א' אדם גדול שזהו בבחי' החכמ' והב' אדם בינוני שזהו בבחי' המדו' והג' אדם קטן שזהו בבחי' הדבור לבד וביאור הדבר ידוע שאדם בדבור קדם לבא להיותו בבחי' הקטנו' והיינו מיד אחר ימי היניקה כשיטעום דגן שיודע לקרות אבא כו' כבן ב' שנים וכה\"ג שנשלם החכמ' שלו השייך לצרופי הדבור לקרות או\"א וכה\"ג ונק' משבר אעפ\"י שלא יש לו עדיין שכל גמור השייך למדותיו כי מדותיו בתכלית הקטנות כערך המדות טביעו' דבהמה וכידוע בענין הפעוטו' מקחן מקח כו' שבהיותו בן ו' מתחיל גדלו' המדו' שיש לו מעט שכל השייך למדות להיות הן ולאו שלו על פי דעת נוטה וגדל מעט מעט השכל ששייך למדות עד היותו בן י\"ג שנה שאז נשלם החכמה ששייך למדות חו\"ג ולכך אז הוא בר עונשין כי האהבה שרש מ\"ע כו' וזהו אדם הב' חכמה שבמדות ומי\"ג שנה מתחיל גדלות המוחין והוא אדם הג' שנק' אדם גדול דהיינו הגידול בשכל עצמו שאינו שייך למדות חו\"ג כלל רק עצם כח שכלו להשכיל כל שכל כו' גדל מעט מעט עד שנשלם כח החכמה העצמי' שלו בהיותו בן כ' שאז יודע למכור בנכסי אביו לשנות מדבר לדבר כמ\"ש במ\"א ומבן כ' עד בן ע' יש עוד הפעם ג' מיני גידולים הנ\"ל אמנם הוא בגדלות יותר כמו מבן כ' עד בן מ\"ם לבינה כו' עד בן ע' שנק' זקן שקנה חכמה לתכלית שלימות גידול כח השכל שלו כמו שהוא ונק' אדם הגדול כו' וכמ\"ש במ\"א הריני כבן ע' כו' ופי' בן ע' שנה הן ז' מדות כלולי' מכחב\"ד כו' שהן ז\"פ י' כידוע וכ\"ז נכלל בענין גידול צלם ומ\"ם דצלם נשלם לבסוף כידוע בע\"ח בענין אך בצלם יתהלך איש בגדלות שלו ובאמת זהו פלא שנשלם כח הדבור תחלה ונק' אדם קטן והמדות אח\"כ והחכמה באחרונה ואין זה אלא לפי שכל הגבוה יותר יותר יבא אחרון וזהו בגידול והתפשטו' דוקא אבל בבחי' העצמו' נהפוך הוא שכח החכמה קדם ואח\"כ כח המדו' ואח\"כ כח הדבור וזהו ענין א' וחי\"ת א' שרש ועצמו' דכח החכמה ע\"י מזל ונוצר כנ\"ל ח' הוא' עצמו' כח השכל ששייך למדו' שעתיד לבוא ממנו כנ\"ל והד' הוא גדלות הדבור שע\"י החכמ' שנק' אדם קטן ואמנם מפני שנעוץ תחלתן בו' ועיקר שלימות האדם כשנק' מדבר דברי חכמ' כו' יותר מחכמ' העצמי' ע\"כ הדלית רבתי ולא הא\"ח והיינו א\"ח דלית וראי' לזה דגם בשלימות עצם החכמ' דזקן שקנה כו' הוא בהיותו מביא החכמ' בגלוי בדבור ונק' משבר לחכמ' כמו וידבר שלמה כו' (וכנ\"ל בענין מי שם פה לאדם):\n(ע) <b>ומעתה</b> יש להבין ענין ועד בחלופי אתוון דאחד שמן הא' נעשה וי\"ו בועד ומהחי\"ת עי\"ן כו' דהנה כל הנ\"ל בפי' אחד הוא בבחי' יח\"ע דאצי' שכולל ג' אלה א' וחי\"ת ודלי\"ת והוא בחי' כתר שבחכמה ומדות ודבור כנ\"ל וידוע דבחי' יח\"ע דאצי' הוא בחי' מקור ליח\"ת דמל' בבריאה דהיינו שמבחי' יח\"ע נמשך יח\"ת וכמ\"ש כגוונא"],[1700400258,"דאינון מתייחדין לעילא בע\"ס דאצי' אוף הכי בחי' המל' אתייחדת לתתא ברזא דאחד שזהו ועד בחלופי אתוון דאחד דמא' נעשה וי\"ו כו' וכמ\"ש במ\"א בענין מה שאמרו השבטים ליעקב כשם שאין בלבך אלא אחד כך אין בלבינו אלא אחד כו') אך לכאורה מאחר שכגוונא דאינון כו' הרי שוה ממש יח\"ת ליח\"ע (וכמ\"ש כשם שאין כו' כך אין בלבינו כו') א\"כ מהו שסותר דבריו בסוף במ\"ש ברזא דאחד ולא כאחד דיח\"ע עצמו והוא בחי' חלופי אתוון דועד שמא' נעשה וי\"ו וכה\"ג אך הענין יובן בהקדים תחלה הטעם לשינוי הא' לאות וי\"ו דוקא ולא לאות אחרת זולתו דהנה ידוע ביאור ענין מ\"ש אני ראשון ואני אחרון כו' דאני אותיות אין והוא בחי' אור הכתר שנק' אין (כידוע בזהר ע\"פ היש ה' כו' אם אין ובהיפוך אותיות דאין לאני הוא כאשר נמשך בחי' אור מקיף דכתר למטה כמשי\"ת) ופי' אני ראשון ידוע שזהו בחי' אור הכתר בחכמה שנק' ראשית כמ\"ש ראשית חכמ' (רק שחכמ' שמאין תמצא בחי' מקבל נק' ראשית לשון נוק' כחכמה בה\"א לשון נוק' אבל אור הכתר בחכמה נק' ראשון) ואני אחרון הוא בחי' התפשטות אור הכתר עד בחי' המל' שהיא בחי' ומדרגה האחרונה ונק' אחרית והחכמה נק' ראשית כמו מגיד מראשית אחרית שירותא וסיומא ואור הכתר שבחכמ' שנק' אני ראשון כשנמשך למל' נק' אני אחרון שהוא המאיר במל' כמו בחכמ' דהיינו בסוף כמו בראש ממש בשוה וזהו המכוון בפסוק זה דאני ראשון ואני אחרון בהשוואה ממש וכמו ראו עתה כי אני אני הוא פי' אני שבכת' הוא אני שבמל' באין שינוי כלל וזהו שמן הא' דאחד שהוא אאלפך חכמה מקור החכמה נעשה וי\"ו שזהו וי\"ו דואני אחרון שמשוה מעלה ומטה כא' ממש שנמצא למטה כמו למעלה ממש וכמו את השמים ואת הארץ אני מלא ממש בשוה דלית אתר פנוי מיניה כידוע וכן בשמים מעל ועל הארץ מתחת אין עוד בהשוואה ממש כו' וביאור טעם הדבור ידוע שזהו בחי' כתר הכללי שמקיף ד' עולמות דאבי\"ע בשוה ממש עד שאצי' ועשי' שוין ממש כחשיכ' כאורה כו' והענין הוא עד\"מ מחשבה ורצון כללי שמקיף לדבר מה שחושב וסובבו במחשבתו כעיגול מכל צד מבלי קדימה בא' מחלקיו על זולתו אלא סוקרו כולו כא' מראשו לסופו בבת אחת ואין כאן תחלה וסוף כלל (משא\"כ מחשבה ורצון שנמשך דרך פרט שיש תחלה וסוף תחלת המחשבה וסופה דמח' והוא ראשית ואחרית דחכמה ומל' כמו הטעם לרצון בדבר מה שנק' ראשית ומשתלשל ויורד במדות עד גלוי הרצון בסוף מעשה שנק' סיפא דמחשבה וזהו אותיות ונוצר בחילף אותיות דרצון הפשוט כידוע שיש חילוק מדרגות תחלה וסוף אבל בחי' רצון הפשוט שנק' כתר שבכתר שזהו אאלפך חכמה קודם שנעשה מקור לחכמה שהוא הטעם לרצון גם שהוא טעם כמוס לרצון הנק' ח\"ס היינו בחי' כתר הכללי שבו שורה עצמות אא\"ס שלפני הצמצו' הראשון הנק' מק\"פ כו' שמקיף לד' עולמות דאבי\"ע בשוה ונק' סובב הכללי כידוע) והוא הנק' מח' אחת לבד שצופה כו' עד כו' (למעלה גם מחכמ' דא\"ק כו') ושם אצי' ועשי' שוין ממש דהיינו גם בחי' חכמ' דאצי' ובחי' חכמה דמל' דעשי' שוין (כמו עד\"מ הרצון בעסק בנין או מו\"מ הנה מה שחפץ בו בכללותו למעלה עדיין מהתחכמות איך ומה כו' אין בו חילוק מה שיתחכם אח\"כ בשכלו או מה שיתחכ' בזה במעשה גשמיות שניהן שוין לגבי עצם הרצון הפשוט שבו כו') ואמנם הנה ידוע שבחי' כתר ומקיף כללי הזה הגם שמקיף לכולם בשוה אבל הוא בהעל' ולא בגלוי עד\"מ דמיון המחשבה הפשוטה המקפת מכל צד מלמעלה ולא תאיר תוך תוכו כו' אבל המשכת אור המקיף הזה הוא אשר נמשך בתוך כל עלמין מראש לסוף מעליון שבכולם עד תחתון שבכולם"],[1700400259,"דהיינו מראשית ומקור האצי' עד סוף ותחתית העשיה אך אם היה המשכה זו בגלוי גמור דהיינו דרך השתלשלות עו\"ע א\"כ היה חילוק מדרגות בין ראש לסוף עכ\"פ ואיך המשכה זו שוה למעלה ומטה ממש כנ\"ל אלא צריך לומר דאור המשכה זו דמקיף אינו בא בגלוי גמור אלא בהעלם ע\"כ שוה למטה וכמו למעלה ולכאורה אין זה מובן כלל דא\"כ למה נק' בשם המשכה מאחר דכבר המקיף הזה סוכ\"ע בהעלם למעלה ומטה בשוה ומה יתרון יש בהמשכ' המקיף הזה אחר שהוא בהעלם אלא מוכרח לומר שנק' בשם המשכה ממש ועכ\"ז היא בהעלם והו' הנק' המשכ' נעלמ' והוא שבחי' ההעלם דמקיף כללי הזה בא בבחי' ההמשכה מלמעלה למטה בתוך תוך כ\"ע מראש לסוף וזהו הוי\"ו דואני אחרון שהויו הוא מורה בחי' ההמשכה שבאה ביוש' מלמעלה למטה כצורת וי\"ו שהולך ביושר מלמעלה למטה בלי שינוי כלל כך בחי' המשכה דמקיף כללי הנ\"ל בא ביוש' ובהעלם מלמעלה למטה בהשוואה א' בכולן בלי חילוק מדרגות כלל בין עליון לתחתון (והיינו שאנו רואים שיש בחי' בטול בכל הנבראים מעליון לתחתון שלא בדרך מדריגות השתלשלו' עו\"ע רק לפרקי' מתגלה כמו ועברתי בארץ מצרים כו') לפי' שבחי' סובב הכללי הזה להיותו בעצם למעלה מן ההשתלשלות דד' עולמות ע\"כ גם בירידתו והמשכתו בעולמות נמצא בכול' בשוה גם בעוה\"ז הנפרד כמו בעולם האצי' ממש (וביאור דבר זה יובן עפ\"י הנ\"ל בבחי' הרצון הפשוט שמאיר לראש וסוף ונמצא בכולם בשוה עד שהטעם ושכל לרצון שהוא הראשית להתלבשות הרצון עם הרצון שמלובש במעשה הרי נמצא העצם הרצון ממש בשוה במעשה הגשמי' כמו בשכל הרוחני כמו האברים שנשמעים לרצונו כמו שהשכל נשמע לרצון להשכיל טעם כפי רצונו כידוע כו' בהיות שעצם הרצון נבדל מהכל ע\"כ בהתלבשותו והמשכתו נמצא בכולם בשוה משכל הרוחני עד הפועל הגשמי וכמו בעבודה שבלב בתפלה כאשר יתפעל נקודת הרצון הפשוט יבא לכלל התחכמות לעומק התפעלות בחו\"ב באלקות ואח\"כ יבא לכלל התפעלות במדו' שבלב והכל מכחו של נקודת הרצון העצמי ופשוט ואח\"כ יבא להתפעלות במו\"ד עד המעש' שיעשה בהתפעלו' כח הרצון הזה בס\"מ ועש\"ט כל היום בתמימו' גדולה שזהו סוף הכל כמו סוף דבר כו' את האלקי' ירא כו' ובודאי יש חילוק מדרגו' הרבה בין שכל ומדו' ומעשה ומ\"מ כח נקודת הרצון העצמי שמלובש בכ\"א שבלעדו לא הי' מתפעל בשכל ולא בלב כו' אין בו שינוי כלל כי אותו נקודת הרצון שעשה התפעלות השכל הוא העושה התפעלו' הלב והתפעלו' המעש' והולך ביושר ובהשוא' א' בכול' עד שנמצ' מציאותו במעש' כמו בשכל הרוחני ממש בשוה וכך הוא במילי דעלמ' כשיש לאדם רצון עצמי למצו' טרף לנפשו להחיות נפשו בעסק פרנס' אעפ\"י שיתלבש ויומשך בהתחכמות איך לעשות העסק ובמדות שבלב עד שעושה ועוסק בפ\"מ כמו בהילוך ובפועל כפיו ממש לחרוש ולזרוע וכה\"ג אין הפרש כלל בין כשימצא חיות נפשו ע\"י ההתחכמו' הרוחני בין כשימצא חיותו ע\"י העסק ביגיעת גופו בפו\"מ הכל א' ממש כי אין עיקר הרצון רק להחיות נפשו (וכמ\"ש במ\"א בענין ואביוני אדם כו') כמו בענין בע\"ת שחפץ להחיות נפשו האלקית שזה עצם הרצון שלמעלה מהתפעלות השגה עד המעש' שכוללם יחד לכך בכה רבי יש קונה עולמו שע\"י תו\"מ ואוי\"ר שכליי' בשעה א' כמו שאביון זה יגיל בפרוטה שמחי' נפשו יותר משמחת העשיר בכל הון ביתו כו' וזהו מטעם הנ\"ל שהוא ברצון הפשוט כו') וזהו הנק' המשכה שבהעלם שהרי לא נודע בהתפעלו' השכל שזהו מחמת הנקודת רצון העצמי רק נדמה לו שזהו רק בהתפעלות שמצד השכל לבד וכן במדות ומעשה והוא לפי שהמשכה זו"],[1700400260,"שנקוד' הרצון נמשך בשכל ומדות כו' הוא בא בהעלם ולא בגלוי בבחי' או\"פ שאם הי' בא בגלוי או\"פ שאם הי' בא בגלוי או\"פ דרך עו\"ע הי' חילוק מדריגות משכל למעשה במיעוט אור ובנקודת הרצון הזה אין בו שינוי כלל מפני שהוא בא דרך העלם בהתלבשות ע\"כ נמצא למטה כמו למעלה ממש בשוה ועכ\"פ זהו ההפרש בין כשהרצון הזה בבחי' מקיף מלמעלה על השכל ומדות ומעשה כמו דמיון הבע\"ת קודם שנתעורר בנקודת לבבו שיש בכח הועלם המקיף כל מה שיומשך אח\"כ כו' ובין כשנמשך הנקודה זו בכל כחות נפשו מראש לסוף כנ\"ל והדוגמא מכ\"ז יובן למעלה בענין וי\"ו דואני אחרון שהוא בחי' המשכה דמקיף הכללי שנמשך בתוך כ\"ע מעליון לתחתון שבכא\"וא מקבל ממנו בהעלם עד\"מ הנ\"ל לכך נמצא בכולם בשוה למטה בעשי' כמו באצילות דדרך כלל ד' עולמות הן ד' אותיות דשם הוי\"ה יו\"ד דחכמ' באצי' וה\"א בבריאה עד ה\"א אחרונה סוף מעשה דעשי' ונמצא בעשי' כמו בחכמה שבאצי' כו' עד\"מ שנמצא כח נקודת הרצון בפו\"מ כמו בשכל הרוחני המתחכם כו' וכמ\"ש במ\"א בענין כל אשר חפץ ה' כו' דלגבי עצמות הרצון הפשוט העליון שוה אצי' ועשי' והוא הנק' בחי' כתר הכללי שמקיף ד' עולמות בשוה בהעלם מלמעלה בלבד וגם הוא נמשך ומתלבש בתוך כולם מעליון לתחתון בשוה כנ\"ל בענין את השמים כו' שלית אתר פנוי מיניה מיניה מעצמו' הכתר והוא בציור וי\"ו דוקא ומתורץ בזה הקושיא דלעיל למה נק' המשכה אחר שהיא בהעלם דודאי המשכה ממש הוא שהוא המשכות המקיף בתוך כ\"ע ועכ\"ז הוא בהעלם בכא\"וא לפי ערכו ובכולם הוא מאיר בשוה בלי שינוי כלל כנ\"ל וד\"ל):\n(עא) <b>וזהו</b> שמן אות הא' דאחד נעש' וי\"ו בועד שמחבר ראש וסוף כא' שזהו המשכת כתר וסובב הכללי כנ\"ל לכך הוא נעשה וי\"ו כנ\"ל ובזה אין שינוי כלל וכלל מכמו שהי' א' שהוא אאלפך חכמ' שנמשך מכתר שבכתר להיות מקור לחכמ' כנ\"ל רק שזהו למעלה לבד וכשנמשך למטה בתוך כ\"ע הוא בציור וי\"ו כו' (ומה שנקרא הו\"ו חלופי אתוון דא' היינו במה שבא בהעלם בתוך כ\"ע ודרך המשכה כוי\"ו ולא כמו שהוא בעצמו ממש כמו שאנו רואי' שבהתפעלות השכל נסתר כח נקודת הרצון כו' וגם יבא דרך המשכה לבד גם במעשה שזהו כציור קו לבד שהקו אעפ\"י שהוא המשכה אבל הוא המשכה קצרה ומצומצמת כמו הקו הנמשך מן העיגול אע\"פ שהולך ביושר ומתחבר למטה כמו למעלה שזהו הוי\"ו דואני אחרון כנ\"ל) ומעתה יש להבין למה ביחו\"ע שהוא באצי' למעלה מיחו\"ת הרי נעשה מן הא' אות חי\"ת שהוא בחי' גלוי החכמ' מאין ליש וכשנמשך ביח\"ת נעשה עי\"ן ולא וי\"ו דלכאורה ק\"ו הוא אם מא' עצמו שהוא מקיף בהעלם בלבד נעשה וי\"ו ביח\"ת כ\"ש כשנעשה מא' חי\"ת באצי' ביח\"ע שצריך להיו' יותר גלוי אור ההמשכה עי\"ז מאצי' לבריאה בבחי' וי\"ו שילך ביושר בשוה כנ\"ל למה יגרע אור ההמשכה מחמת החי\"ת מאחר שהוא בחי' גלוי אור כו' אך הנה התירוץ הוא דאדרבה היא הנותנת דמשום שהחית בא בציור צורת הפתח דחכמ' מההעלם דכתר לגלוי אור בבחי' או\"פ ע\"כ בירידת אור זה מאצי' לבריאה מתמעט האור מיעוט אחר מיעוט ולא ימצא אורו בבריא' כמו שהוא בעצם מציאותו ופנימיותו באצי' כו' אבל בחי' המקיף דכתר דחכמ' שבהעלם באות הא' דאאלפך חכמ' להיותו בבחי' מקיף שלמעלה מבחי' א\"פ ע\"כ בירידתו לא יתמעט אור כלל ונמצא במציאותו למטה ממש כמו למעלה וטעם הדבר ידוע לפי שזהו ההפרש בין או\"מ לאו\"פ שהא\"פ בא בבחי' השתלשלות עו\"ע כמו משכל למדות הרי מתצמצם בחי' אחרונה שבשכל ונתלבש במדות הרי נתמעט אור השכל במדות וכך"],[1700400261,"נתמעט אור מן המדות למחשבה ודבור ומעשה כו' עד שנמצא במעש' בתכלית המיעוט מצד השתלשלות האור ממהות למהות דרך עו\"ע משא\"כ או\"מ שאיננו בא דרך עו\"ע כלל אלא כמו שהוא יורד ונמשך בהעלם כנ\"ל באריכות הרי אין בו שינוי כלל ולא נתמעט אורו גם למטה מטה מכמו שהוא למעלה מעלה ולכך מן הא' דוקא נעשה וי\"ו ולא מן החי\"ת דהנה החי\"ת הוא כשבא' החכמ' בבחי' או\"פ שהוא גלוי יש מאין כמו והחכמה מאין תמצא כנ\"ל הנה ודאי בירידו' השתלשלו' אורו עד עולם הבריאה לא יוכל לבוא שם בחי' פנימית שלו כלל כמו שהוא באצי' רק בחי' חיצוניו' שלו מפני שנשתנה ממהות למהות כנ\"ל וזהו שנעשה ממנו עי\"ן שהוא בחי' חיצוניו' חכמ' לבד כמשי\"ת אבל פנימי' חכמ' דאצי' לא יוכל לבא בגלוי בבי\"ע וכמ\"ש בזוהר דאור אבא מקנן באצי' ואימא מקננא בכורסייא שהוא עולם הבריא' כידוע אבל הארת אור אבא נפסק מאצי' לבריאה ואינו מאיר בבריאה מבחי' פנימי' שלו כלל כי לא אפשר שיתגלה שם פנימי' חכמה דאצי' רק בחי' חיצוניו' שלו המלובש בבינה שהוא אימא דמקנננא כו' ואם היה מתגלה בבריאה מפנימית חכמ' דאצי' היו מתבטלים ממציאו' לגמרי לפי שהוא למעלה משיעור כלי קבלתם דלכך א' דדוקא אימא מקננ' כו' ולא חכמ' וכענין הידוע בפי' הושיט אצבע קטנה פי' הנקודה דחכמ' שנק' אצבע קטנה שהוא יו\"ד דחכמה שהושיט ביניהן שהוא יותר מכדי שיעור קבלתן מבינה שבמל' ושרשן נתבטלו במציאות לגמרי ומ\"ש כולם בחכמה עשית היינו בחי' חיצוניות חכמה לבד שמתלבש בכל העולמות אבל פנימית חכמ' בלתי מתלבש בעולמות רק באצי' לבד (משום דפנימית אבא הוא פנימית ע\"י ששם הוא עצמות א\"ס כו') ובאור הדברים ידוע ע\"פ כולם בחכמה עשית שפי' בזהר עשית בבינה שכל התהוות יש מאין א\"א להיות מנקוד' דחכמ' שהיא שהיא בבחי' אין והעלם ובהעדר ההתפשטו' לגמרי רק חיצוניו' חכמ' שמתפשט ובא בהשגה דבינה בבחי' יש מאין משם מתהווה כל בריאה יש מאין כמו התהוות השגות הנשמו' בג\"ע הוא דוקא מבחי' בינה שבמל' כידוע ולא מבחי' חכמ' וגם בכל מה שנמשך מאין ליש עד סוף העשי' הכל הוא מבחי' בינה בינה וכמו בראשית ברא אלקי' וא' בזוהר אבא א' לאימא שנק' אלקים וזהו ויאמר אלקי' כו' (ומ\"ש במ\"א בענין אל אדון על כל המעשים שנהירו דחכמתא שנק' אל מתפשט בכל הברואי' שבעולם עד בחי' הדומם כמו ושמן מחלמיש צור וכנ\"ל (בסי' נ\"ו) היינו חיצוניו' חכמ' בחי' כח האין דחכמ' שמלובש בבינה שמוסתר בהעלם גם בבחי' היש המתהוה כו' שהוא בחי' ההיולי והתמצית של כל בריאת יש כו' אבל בחי' פנימי' חכמ' אינו מאיר גם בהעלם בבי\"ע להיות שהוא בחי' האין בעצם כמו שהוא שאינו אלא באצי' שהוא בחי' אלקו' ממש וגם בכלי החיצוני' דזו\"נ דאצי' כו' משו' דאיהו וחיוהי חד והיינו מ\"ש דאור אבא דוקא מקנן כלו' שמתפשט עד סוף האצי' דיו\"ד באצי' כו' והיינו משום דפנימי אבא הוא פנימי ע\"י ששם עצמו' אא\"ס בחי' האין האמיתי כמו שהוא בעצם שא\"א שיתגלה בבחי' יש כידוע (וראי' לזה שאם הי' בחי' פנימי' חכמ' דאצי' מאיר בבי\"ע גם בהעל' הרי נא' ימותו ולא בחכ' שבפנימי' חכמה אין שם שבירה ומיתה רק בחיצוניו' חכמ' שמלובש בבינה ומדו' ושהו הנק' עה\"ח שלמעלה מעה\"ד טו\"ר שאין שם מיתה כלל וממילא אין משם שרש יניקה לחיצוני' שנק' מות כידוע ואם היה פנימי' חכמ' מאיר בבי\"ע לא הי' צד יניק' לחיצוני' שנק' מות גם מאחוריי' דשם אלקי' וגם מטעם שנא' וכבודי לאחר לא אתן שא\"א שיהי' בחי' גלוי עצמו' אא\"ס שבפנימי' חכמ' לאחר כו' וכבודי הוא פנימי' חכמ' שהן ל\"ב נ\"ח גי' כבוד והוא כבוד נאצל כו') אלא ודאי שאין הארה דחכמ' בבי\"ע רק בבחי' חיצונית שבה שמשם"],[1700400262,"יש שרש לעה\"ד בבחי' מדו' שבבינה כידוע שעיקר השבירה הי' בשם ס\"ג כו' אבל באצי' שהוא אחר התיקון דלא יגורך רע שאין שם שרש לחיצוני' כי שרשם מתחיל בבריא' שם מתפשט אור החכמ' ומאיר בגלוי כו') וזהו הטעם שהארת אור אבא נפסק מאצי' לבריאה (ובאצי' אור אבא נמשך למטה יותר מאור אימא וכידוע בענין בינה עד הוד אשפשטת ולא יותר ולכך נק' יסוד יתום מאמו ולא מאב כו') (ובענין הברורי' לברר רפ\"ח נצוצין שבנוגה דבי\"ע זהו דוקא בחכמ' אתברירו וכידוע בענין ששת אלפי צבא שיוצאי' בכל יום מאצי' אור א' לבי\"ע כמו ומרדכי יצא כו' מבחי' יסוד אבא כו' והיינו מבחי' פנימי' חכמ' דוקא אך שהוא מוסתר בתכלית באחוריי' וחיצוניות חכמ' כענין הנ\"ל במי שם פה לאדם פיה פתחה כו' שהחכמ' תחי' בעליה כמשל מי שחכמתו עמדה לו לפרנס א\"ע כו' שכח זה לתקן בא מכח פנימי' החכמ' דוקא כמ\"ש במ\"א בענין מזמור לתודה הריעו כו' והיינו חכמו' ח\"ע דאתמשך בח\"ת בחוץ דוקא תרונה אך בזה נעשה תיקונם ואבודם זהו תקונם כמ\"ש כי גחלים אתה חותה כו' ואין זה גלוי אלקו' שבפנימי' חכמ' לחוץ בהיכלות דנוגה אלא בבחי' הסתר גמור הוא שם כמ\"ש וכבודי לאחר כו' רק שמלובש שם בהעלם כדי לבררם כו') ומ\"ש בדבר ה' כו' ובדבור ודאי יש הארת אור אבא דאבא יסד ברתא הרי מבואר למעלה (בסי' ס\"ח וס\"ט) שיש ב' מדריגו' בדבו' ובחיצוניו' צרופי אותיו' הדיבור אין שם רק חיצוניו' חכמ' מה שמצרף הצרופי' בחכמ' אעפ\"י שבא מקדמות החכמ' כנ\"ל הרי הוא הארה נעלמת בתכלית הקטנו' ואמנם בכח ועצם הדבור ששרשו מעצמו' ופנימי' אבא ממש ודאי מאיר שם מפנימית חכמה ואדרב' נעוץ תחלתן בסופן וכמו מגיד מראשית אחרית כו' ובאמת ראשית בת' הוא חיצוני' חכמ' שמאיר בבינה ואחרית הוא בדבור בגלוי ע\"כ מגיד מראשית דחכמ' דאצי' עד חכמ' שבמל' דעשי' שהוא אחרית הכל אבל אני ראשון הנ\"ל הוא הארת אור הכתר דא' בחכמ' הגם שהוא פנימי' חכמ' שהוא פנימי' ע\"י שאינו מלובש בבי\"ע אבל אני זה הוא המשכ' הכתר עצמו בחי' המשכת המקיף שאינו בא דרך השתלשלו' עו\"ע לכך נמצא למטה כמו למעלה ולפ\"ז גם פנימי' אבא יוכל להיות בהעלם למטה כמו למעלה כשאינו בא בבחי' או\"פ מאחר שהוא פנימית ע\"י ודלא כדלעיל וד\"ל) וזהו שהושיט אצבע קטנה שהוא יו\"ד דחכמה ביניהן ושרפן כנ\"ל שהוא פנימי' חכמ' שבמל' דאצי' (ששרשו הראשון פנימי' אבא שהוא פנימי' ע\"י וא\"ק כו') שבבריא' והמלאכי' דבריא' מקבלים מכלי' חיצוני' דמדו' שבמח' שנק' עולם הבריא' כידוע והיינו שזהו יתר משעור קבלתם ששרש המדו' דמח' מצומצם רק לפ\"ע ההשגה דבינה שבמל' שנק' יש מאין דחכמ' מבחי' חיצוניו' שבה לבד כידוע וד\"ל (אבל הנשמו' יוכלו לקבל מיו\"ד דחכמ' ולא יתבטלו במציאו' כלל שהרי ביו\"ד דחכמ' נברא העוה\"ב שהוא עולם הנשמו' דוקא ומ\"ש בעוה\"ב להנחיל אוהבי יש דוקא וכמ\"ש נברא העו\"הב מאין ליש וכידוע דשרש עוה\"ב בבינה והרי פנימי' החכמ' נק' אין בעצם היינו שיבא בחי' האין העצם בבחי' מורגש בבחי' יש שמעונג הנעלם דעכשיו בבחי' פנימי' חכמ' בעוה\"ב יתענגו הנשמו' ממנו בבחי' יש מורגש וכמ\"ש ונהרותם בחי' בינה כשמן דחכמ' אוליך כו') ובכ\"ז יובן הטעם מה שמן הא' דאחד נמשך בבחי' וי\"ו ביח\"ת ומן החי\"ת דחכמ' דאצי' נעשה החלוף באות עין ביח\"ת לפי שהעין הוא בבחי' חיצוניו' חכמה כידוע דז\"ת דבינה הן בחי' המדות שבהשגה דבינה לבד וכאשר כל א' כלול מיו\"ד דוקא הוא מספר ע' דהיינו כשיש חב\"ד בכל מדה או כח\"ב כו' שזהו תכלית שלימות השפע דחכמ' לבינה השייך רק למדו' לבד (כי גם זקן שקנה חכמ' כו' היינו שנמשך בו תכלית"],[1700400263,"גדלות המוחין דחו\"ב קנה חו\"ב במדו' ואז ראוי לישב בסנהדרין לשפוט ונדון במדותיו עפ\"י תכלית שלימות החכמ' השייך למדות אבל כ\"ז אינו רק בחי' חיצוניו' דחכמ' דהיינו רק ממדות שבחכמה ולא מבחי' ג\"ר שבה שהוא חו\"ב דחכמ' דהיינו עצם נקוד' השכל טרם שיבא לכלל נטיי' והתפשטו' בשביל פסק דין כו' כמ\"ש במ\"א ולזה בבי\"ע נעש' החי\"ת עי\"ן לפי ששם אור פנימי' אבא נפסק כנ\"ל ורק חיצוניו' הוא בחי' מדו' דחכמ' בבינה שהוא אימא דמקננא בכורסייא כו' אעפ\"י שחב\"ד בבריא' וחג\"ת ביצי' כו' היינו בחי' חב\"ד שבכל מדה שהוא שכל וחכמ' השייך לגידול המוחי' במדו' לתכליתם והוא אות העין כו' והן בחי' ע' שנין דדוד שנמשך מחכמ' בראש דאצי' שנק' אדם קדמא' כו' שהוא אות החי\"ת שנעשה מא' דאחד כנ\"ל וד\"ל):\n(עב) <b>ולהבין</b> בטוב טעם יותר במה שהעי\"ן הוא בחיצוניו' חכמ' דוקא הנה יובן עפ\"י הידוע בענין ראי' ושמיע' שזהו בחי' חו\"ב וראי' בבחי' חכמ' ושמיעה בבינה אך הנה הראי' הוא בבחי' חיצוניות חכמ' דהיינו רק כח חיצוני הנמשך מאור השכל שבמוח לכלי חומר העין שהרי העין כלי חומר גשמי בלתי חומר לצורת אור השכל כחומר כלי המוח עצמו אלא רק אור הארה בעלמא מתפשט בראי' רוחניו' שבכלי העין ולכך נק' עין השכל וכמו חכמי' נק' עיני העדה שהמה הרואי' עפ\"י חכמ' לדעת מה יעשו כו' וכמו איזהו חכם הרואה את הנולד שבחכמתו יוכל לראות מה שיולד אשר נעלם מעין כל והחכם רואה בראיי' השכל מה שעתיד להיות כאלו רואה בעינו שאין זה רק שמבין ומשיג בעין השכל שעתיד להיות כך וכך והשגה זו היא חיצוניו' לגבי עצם כח חכמתו בכל מושכל להשכיל כל דבר חכמ' עמוקה כי מה שמביט וצופה בשכלו מה שיולד הוא רק התפשטו' חיצוניו' מעצם כח שכלו ותבונתו העצמי' ואין לה ערך גם לגבי חיצוניו' ההשגה שמשיג איזה שכל וסברא שזהו נק' שכל וסברא ומה שרואה בראיי' השכל את הנולד נק' ראי' שכליי' ולא שכל עצמו כמו שהעין רואה בגשמיו' הגם שלפ\"ע כח שכלו וחכמתו כך ערך מעלת ראיי' שכליות שלו כמו לראו' בעין השכל ערמומי' גדולה שבאד' הנעלמת מכל השג' והחכם יראה ויכיר מיד בראיי' שכלו או באיזה תערוב' טו\"ר שבאדם ירא' להבחין לכל חלקיו הנעלמי' במצפוני לבבו כאלו רוא' בעיניו ויגיד לו כל תעלומותיו וסתריו ולכך אמרו חכם עדיף מנביא כידוע עכ\"ז אין זה רק בחי' חיצוניו' כלי המתפשט מכח העצם של החכמ' רק שלפ\"ע הפנימי' כך ערך יתרון מעלת הפנימי' כמו במשה שנא' וירא ראשית לו שהי' בבחי' ראי' דחכמ' מצד שרשו בפנימי' החכמ' וכן כל חכמי ישראל שנק' עיני העדה שזהו ודאי לפ\"ע יתרון מעלתם בפנימי' חכמ' כך ערך שלהם בבחי' החיצוניו' שהוא ראיי' השכל (וראי' מטביעת עין שאינו אלא בחכם דוקא כידוע ואמנם מלובש בכח הראי' והסתכלות הזאת מכל פנימי' ועצמו' כח החכמ' יותר ממה שיש בכח השכל להשכיל שכליי' וסברו' וכמ\"ש במ\"א בענין לאסתכל' ביקר' דמלכ' שז\"ש יונתי בחגוי כו' עיניך יוני' מלמטה למעלה וכן עיניו כיונים כו' עיני ה' אלקיך בה כו' עין ה' אל צדיקים וכה\"ג מלמעלה למטהכמשל זווג היונים שמסתכלים זב\"ז כו' שזהו מגיע בעצמו' כל הנפש שמלובש בעונג ההסתכלות הזאת עד שכל פנימי' נפשו נמשך אח\"ז כו' וזהו למעלה מהמשכ' כח המשכיל להשכיל כו' והיינו לאסתכל' כו' יראה כל זכורך כו' ולפ\"ז הרי נהפוך שהראי' והסתכלו' הוא בבחי' הפנימי' דוקא וכידוע שלמעלה זהו בחי' אסתכלותא דא\"א בז\"א ומז\"א לנוק' וכן מנוק' לז\"א כמ\"ש אשא עיני כו' עיני כל אליך שזהו למעלה הרבה מגופו של יחוד דזו\"נ כו'"],[1700400264,"לפי שבתענוג זה שבהסתכלו' משפיע ומקבל זע\"ז מלובש כל פנימי' עצמו' התענוג שבנפש יות' מן העונג שנמשך בגופו של יחוד (וראי' מבת יענה כו') ולכך אמרו דחייב אדם להקביל פני רבו דוק' ברגל כמו יראה כל זכורך כו' שראי' זו מקור לכל יחוד משפיע ומקבל שיהי' אח\"כ כמ\"ש שם באריכו' ובכאן משמע מאות הע' שאינו אלא בחיצוניו' חכמ' כנ\"ל אך הענין הוא שיש הפרש בין פנימי' עונג שבחכמ' ובין חיצוניו' עונג שבחכמ' דחיצוניו' עונג שבחכמ' הו' העונג המורגש בהמצא' שכל וסברא מאין ליש כמו חכמ' אדם תאיר פניו כשמחדש שכליות שבאין במושג עכ\"פ אבל פנימי' עונג שבחכמ' נק' עונג הנעל' בבחי' אין ומ\"ה דחכמ' שלא בא במושג ומורגש כלל כמו שמצינו בדוגמא לזה שהאריז\"ל הי' משיג סודות ורזין דאורייתא בחלום הלילה בשעה א' בשינה מה שהי' צריך להביא בכתב כמה שנים כו' שזה ודאי אינו השגת שכלי אלא בחי' אור רוחניו' ראיי' ההשכלה כמו שהיא בהעלם עצמו' האין דחכמ' שלמעלה מהשגה כו' וכדוגמא שמצינו בזהר באד\"ז ואד\"ר בי\"ג ת\"ד שכל א' אמר כפי עצם כח שרשו למעלה ברוחניות והוא הנק' הסתכלות כמו ר' חזקיה א' אסתכלנא כו' וא\"ל ר\"ש נושא עון חמית כו' וזהו כל לשון אסתכלותא דחכמתא שהוא למעלה מהשגה רק כמו ראיה שבעין השכל הגשמי הנ\"ל וכמ\"ש בר\"מ בעין השכל דבליבא אתחזי כולא כראיית שכל גשמי וכמ\"ש ולבי ראה הרבה חכמה ובזה נא' בשמה וירא ראשית לו דראשית דחכמה היה אצלו בבחי' ראיה רוחניות וזהו מצד שרשו בפנימית דחכמה שהוא פנימית ע\"י דהיינו פנימית העונג שבחכמה הנק' ראיה שזהו ענין הסתכלות עינים דלעיל שכל עצמות התענוג שבנפש נמשך בה שלמעלה הרבה מעונג מצומצם ומורגש שבחידוש השכל ממקורו ולזה חייב להקביל פני רבו שבעונג הסתכלות פניו זה יהיה מקור לקבלת שפעו כנ\"ל וכן יראה כל זכורך כו' שהוא הסתכלות עיני כנ\"י מלמטה למעלה וכשם שבא לראות כו' נמשך מלמעלה למטה מבחי' הסתכלות עיני ה' בבחי' עונג העצמות כנ\"ל אבל ראיי' העין מצד עצמות הוא רק בחיצוניות דחכמה וכמו גם ראיי' השכל של החכם לראות את הנולד ואת הנעלם בדבר ערמה או תערובות דק כנ\"ל רק שזה תלוי לפ\"ע כח חכמתו להשכיל כמ\"ש איזהו חכם כו') וזהו שמן החי\"ת דחכמה שבאחד דיח\"ע נעשה עי\"ן דחכמה בחי' חיצוניות שחכמה ביח\"ת וכנ\"ל דפנימי' חכמה אינו מאיר בבי\"ע רק דרך הלבשה בחיצוניו' שנק' עי\"ן לבד כנ\"ל וד\"ל והנה יש עוד טעם אחר לענין אות עי\"ן דוקא שנעשה מאות החי\"ת דאחד בהיות ידוע המאמר דאימא אוזיפת מאנהא לברתא שהן ה\"ג מנצפ\"ך דאימא שנק' פתוחי חותם שנמשכין במל' שנק' ברתא וכמ\"ש כאמה בתה והענין ידוע שהן ב' ההי\"ן דם הוי' ה\"א ראשונה בחי' בינה דאצי' אימא עלאה אם הבנים של המדות הנק' וי\"ו וה\"א תתאה הוא בחי' מל' דאצי' והיינו שאמר תרין נוקבין פריש שלמה אתי מלבנון כלה כו' (וכמו שם הגדולה לאה בבחי' בינה עלמא דאתכסיא ושם הקטנה רחל עלמא דאתגליא וכן שם האחת שפרה שמשפרת הולד ושפ השנית פועה לשון פעיא שהוא עולם הדבור ונק' מילדות העבריות כמ\"ש במ\"א) וביאור הדברים ידוע שעל ידי בחי' ההשגה לאורך ורוחב מיד יתפעל בשכל בחדוה או להיפך ונקרא התפעלות השכל בחי' מדות שבבינה וכפי אופן התהוות התפעלות השכל שבמוח כך יבא ההתגלות בצרופי אותיות הדבור שהוא בחי' המל' לא יוסיף ולא יגרע כלל שהרי אנו רואים שלא ישונה בקול ודבור מכל אופן התפעלות האהבה חסד שבשכל וכל להיפך במדה\"ד שבשכל והשגה יבא הכל בדבור בלי' תוס' וגרעון וכך בכל פרטי המדות כנצח והוד והתפארות וכה\"ג וכידוע (והגם שהמדות שבשכל נמשכין בלב"],[1700400265,"ומתפעל הלב גם הוא באותו אופן שנתפעל בשכל שבמוח ממש לא יוסיף ולא יגרע ומן הלב אל הדבור יוכל להשתנות מן הקצה שיוכל לדבר היפך מה שבלבו מחסד לדין או מדין לחסד כמו המדבר במרמה או מן השפה ולחוץ או שאין פיו ולבו שוין כידוע כ\"ז א\"א להיות מן התפעלות מדות שבשכל אל הדבור כי מדות שבלב יוכל לצמצם ולהעלים לגמרי ולהראות היפוכו בדבור וכאשר ידבר בהיפך בהכרח שידבר בדעת והשגה שבמוח ואם לאו לא ידע לכוין הצרופים שבדבור א\"כ יתהווה שינוי בהשגה שמוכרח לחשוב במוח בשביל הדבור היפך מה שבלבו וממילא מובן מזה שכל אשר ישיג ויתפעל במוח באופן צרופי' שבמחשבה והשגה זו ממש יבא בדבור וא\"א לו לשנות כלל כנ\"ל דאם ירצה לדבר היפך המח' וההשגה לא יוכל לצרף מאומה בדבור) וכ\"ז מצד ששרש התחלקות ה\"ג מנצפ\"ך דאימא הן עצמן באין לחלק בה' מוצאות שבדבור כמ\"ש אוזיפת מאנהא לברתא והענין הוא דאופן התחלקות צרופי אותיות דמח' דבינה בא ע\"י ה\"ג המחלקות ומפרידו' וכפי אופן התחלקות הצרופי שבמח' כך ממש יבאו בחי' ה\"ג הללו לחלק ולצרף אותיות הדבור והיינו דאוזיפת אימא לברתא כו' וכמ\"ש במ\"א ולפ\"ז לפי אופן צרופי' שבמחשבה שמזה יהיה אופן התפעלות המדה שבשכל בהכרח שבא יבא בדבור כדוגמתו ממש בלי תוס' וגרעון כלל (וזה ודאי שהאופן של התפעלות המדה שבשכל אינו אלא לפי אופן הצרופים שבאותיות המח' שנתפס בהן השגת הטעם והשכל ומשתנה אופן התפעלות המדה שבשכל מחסד לדין ומדין לחסד בכמה אופנים שונים וממוצעים הכל לפי אופן שנויי הצרופים שבמח' הסובל את ההשגה כמו שאנו רואים בקפידא וכעס שיבא באופנים שונים לפי אופן הצרופים שבמח' שחושב לטעם שמחמתו יתפעל בקפיד' וכן להיפך במדות התפעלות האהבה במוח לאהובו או בנו הרי משתנה באופנים רבים לפי אופן שנויי צרופי' שבה) ובזה יש הפרש בין מדו' שבמח' ושכל (שנק' ז\"ת דבינה שמלובשים במדות דמח' שנק' לאה עלמא דאתכסייא) שבאין בדבור בגלוי בלי שינוי כלל מטעם הנ\"ל משא\"כ מדו' שבלב שאינן תלויי' ומתאחדי' בדבור כמו המח' שבמוח ע\"כ יכול לשנות מלב לדבור כנ\"ל אע\"פ שגם המדות מתהווים לפי אופן הצרופי' שבמוח כמו הקפידא שבמוח שבאה ללב כו' מ\"מ יכול לצמצם בלב ולכבוש כעסו כו' ואע\"פי שגם מן המחשבה יוכל שישנה ויכבוש כעסו שבמחשבתו וידבר במרמה היפוכו דברי אהבה מ\"מ בשעה שידבר דברי אהבה מוכרח שיהיה אופן הצרופים במח' כאותן הדברים אהבה שבא בגלוי בלי שינוי כלל והוא מטעם דה\"ג שבמח' באים בדבור כנ\"ל):\n(עג) <b>וזהו</b> טעם ענין אות העי\"ן דועד בחילוף אות החי\"ת דאחד שהוא בחי' ז\"ת דהשגה דבינה שנק' ע' רבתי דשמע שם ע' כמ\"ש בזוהר וכשבא להתפעלו' המדות במח' כנ\"ל נק' ה\"א עלאה (והוא בחי' לאה שילדה ששה בנים כידוע) ומשם נמשך למל' דאצי' עולם הדבור העליון ונק' גדולה וגבורה בה\"א דדבור ושרשו בה\"א עלאה דמח' דבינה כי משם נמשך כל פרטי המדו' מן ההעלם לגלוי כמ\"ש ברוך ה' אלקי ישראל מן העולם ועד העולם מעלמא דאתכסיא כו' (והיינו שית תיבין דיח\"ת שמקבלין משית תיבין דיח\"ע) (ובדלית רבתי שהוא גדלו' הדבור כמו שהוא בשרשו באור אבא הנק' כח הדבור שם המדו' ג\"כ בבחי' ע' רבתי דבינה וזהו עד ה' בכם כמ\"ש בזהר וכמשי\"ת) (וכמ\"ש לך ה' הגדול' והגבורה כו' לך הן נש\"ב מפני שעולה מלמטה למעלה מהדבור אל השכל והשגה ואח\"כ חוזר ונמשך משכל אל הדבור וזהו כי כל כו' וכמ\"ש במ\"א) ולהיות שעיקר הבנין של המל' מה\"ג מנצפ\"ך דאימ' כמה שכתוב כאמה בתה כנ\"ל שעי\"ז"],[1700400266,"נמשכי' המדות שבבינה במל' בלי תוס' וגרעון כלל כנ\"ל ע\"כ נעשה אות עי\"ן דוקא ביח\"ת דמל' בתיבת ועד וד\"ל אך הנה עדיין יש להבין למה מן החי\"ת דוקא נעשה עין שהוא מדו' שבבינה שנמשך למל' דלכאורה זהו היפך גמור דז\"ת דבינה הוא שמאירים במל' הוא שנק' עי\"ן וההמשכ' הוא מאות החי\"ת דאחד שהוא בחכמ' שלמעלה מז\"ת דבינה ואיך יהי' חילוף כזה מחי\"ת דחכמ' לעי\"ן דבינה שהן ב' הפכי' שהחכמ' נק' אין ובינה נק' יש כידוע ועוד דלמה לא יאיר רק מז\"ת דבינה במל' מטעם ה\"ג מנצפ\"ך דאוזיפת אימא לברתא שזהו דרך שאלה לבד ולא יאיר מן החכמ' במל' שנמשך עצם שרש המל' משם דאבא יסד ברתא כידוע דמצד זה יש למל' שרש באבא יותר מבאימא כו' אך הנה יש להקדי' תחל' בתוס' טוב טעם לאות העי\"ן שבועד שהוא בבחי' מל' דהנה מבואר בספרי הקבלה דעין גי' ק\"ל והיינו דנשים דעתם קלה קל ה' דהיינו משום שאין לנוק' רק עטר' דגבורה שהן מה\"ג דאימ' לבד שחסר לה הדעת שכולל חו\"ג והן ה' הויות לבד שמס\"ט דגבורה שעולה מספר ק\"ל משא\"כ בדכורא שכלול מחו\"ג ע\"י הדעת אז יש מספר י' הויות ה' הויות מה\"ג דאימא וה' הויות מה\"ח דאבא ויוד הויות עולה מספר ר\"ס ב\"פ ק\"ל והיינו שא' במשה כי סר לראות גי' ר\"ס שמשה הי' שרשו בבחי' הדעת שכולל חו\"ג דאו\"א שזהו סר לראות בראי' דחכמ' להמשיך למל' כו' וכמ\"ש וירא ראשית כו' אבל הנשים דעתן קלה קל ה' שאינו אלא ה' הויות מס\"ט דה\"ג דאימא לבד וכידוע דמקור כל החסדי' נמשך מה\"ח דאבא כמו אבינו אב הרחמן כו' ומקור כל הגבורו' נמשך מה\"ג דאימא כמ\"ש אני בינה לי גבורה כו' וביאור כ\"ז ידוע בענין ה\"ג דאימא וה\"ח דאבא שמוח החכמ' קר ולח שיסודו העיק' הוא מיסוד המים שהן בבחי' החסדים ע\"כ יש בטבע מוח החכמ' לסבול דבר והיפוכו ולהרגיש בצער ולהתפעל ברב חסד ורחמי' כטבע האב שהוא רחמני כמו כרחם אב על בנים כו' וכל שכמתו מרובה יותר יוכל לסבול כל ההפכיי' המנגדי' אליו כי ימצא בכלי רוחב מוחו להכיל צד המנגד שהוא בחי' גדלי' המוחין לסבול דבר והיפוכו מצד שמתחלק השכל לקוין ימין ושמאל בכמה אופני' שוני' וימצא טעם לדבר המנגד ג\"כ משא\"כ הקטן בדעת לא יוכל לסבול רק כרצונו ולא יוכל להטות שכלו לקו המנגד לו והוא סיבת ריבוי הקפידא במוח במי דעתו קצר' דוקא כתנוק ואש' וזהו שדעתן קלה כמו שאנו רואי' בתנוקות שמלאים דינין וכעס להקפיד במוח מיד שיעשו נגד רצונו ושכלו כי לא יכיל מה שנגד קו שכלו ורצונו מצד קוצר הכלי ועיקר הקפידא במחשב' שבמוח שתתפעל ותזוז ממקומה (צו רייצט בל\"א) כידוע דלאה דינא קשיא כו' וע\"כ הנשים ג\"כ מלאי' דינין וגבורו' מפני שדעתן קלה שהו' בקו א' והיינו סט' דגבור' שלא יסבול המנג' אליו ויקפוד מיד בכעס שלא יכיל הכלי למצוא מקום למנגד לפי שחס' לה הקו הב' שהוא קו ימין להטות כלפי חסד כו' וכן קטן שאין לו מחשבה שהוא הדעת שכולל חו\"ג רק קו א' ולא יסבול דבר והיפוכו כלל ע\"כ אינו בר עונשין (כי בחי' הקוין הן ולאו אצלו קרובי' זא\"ז שמיד יתחלף מדבר להיפוכו מהן ללאו ומלאו להן ואוי\"ר שרש מ\"ע ול\"ת אינו אלא בגדול שקוין שלו רחוקי' מבלתי יפותה מהן ללאו וכמ\"ש במ\"א בענין אהבה דלא אתכלילת מב' סטרין שהוא ב' קוין חו\"ג כו' ע\"כ הוא בר עונשין שאהבה שלו דבר של קיימ' ואם עובר על מ\"ע ול\"ת ענש יענש משא\"כ הקטן וכך ענין הנשים דעתן קלות שאין להן רק קו א' וע\"כ נוחין להתפתות מלאו להן ומהן ללאו כמו עובדא דברורי' דביתהו דר\"מ דגם שהי' לה חכמ' גדולה אבל ב' קוין שבדעת אין לה כו' וזהו דמיון להבין ענין ה\"ג דאימא דכאמה בתה בבחי' קו"],[1700400267,"השמאל לבד כו' שזהו גי' ק\"ל וכמו רוכב על כרוב קל שלו שהוא המל' שהוא בקטנו' הדעת שנק' כרוב קל כרביא אנפי זוטרי וכן הנה ה' רוכב על עב קל ובא מצרים שזהו בחי' הסתר אלקו' בגלות ע' שרים דנוגה וזהו שרוכב על כרוב קל בלילה דוקא ושט בח\"י אלף כו' בבחי' שינה שנק' דרומיטא כו') וזהו כי סר לראות ר\"ס הן יוד הויו' שעולה ר\"ס כשכלול מחו\"ג דאו\"א דוקא אבל כשאין בו רק ה\"ג דאימא שהן ה' הויו' דגבורו' לבד עולה מספר ק\"ל והוא ענין נשים דעתן קלה קל ה' כנ\"ל וזהו עין גי' ק\"ל דהיינו שרש השפע דה\"ג דאימ' שנמשך במל' שאז נק' המל' אד' דינא דמלכותא כמ\"ש מלך במשפט יעמיד כו' במשפט ודין דבחי' הגבורות דוקא משום דעיקר בנין המל' מבחי' הגבורות דוקא כידוע (ומ\"ש והוכן בחסד כסא שכסא המלוכה הוכן יסודה בחסד דוקא גם זה אמת דחסד דז\"א נמשך למל' ומזה דוקא הוכן כסא דמל' הנק' שופט כל הארץ כו' כמ\"ש באור פני מלך חיים דאם לא בחי' החסדים שבמל' לא הי' מציא' אור ושפע האלקי בעולמות כלל ומ\"ש בע\"ח דעיקר בנין המל' מבחי' הגבורות דוקא היינו שעיקר בנין עצמה לבד שהוא ע\"י התחלקות ה\"ג מנצפך דאימא כנ\"ל ובאמת עיקר ה\"ג הללו הוא לצורך העולמו' דהיינו לצורך הנהגות העולמות שזהו דוקא לשפוט את העולם וכמ\"ש מלך במשפט דאד' דינא דמלכותא כנ\"ל וכידוע דאלמלא מוראה של מלכות איש את רעהו כו' כך במלכותא דרקיע שא\"ל בחי' יראה עלא' דאור האלקי שנורא מאד כמ\"ש מי לא ייראך כו' לא הי' עולם עומד מהתגברו' שפע החיצוני' ומלך במשפט ודין יעמיד לברר ולבער הרע כו' ואמנם פי' במשפט היינו שכלול מחו\"ג דוקא שהרי א' במ\"א משפט דאיהו רחמי שהוא הת\"ת שכלול מחו\"ג כידוע ושרש הענין דשניהם אמת דנמשך ה\"ח וה\"ג במל' וה\"ח דז\"א זהו שאמ' והוכן בחסד כו' ובה\"ג הוא בחי' ה\"ג דאימא ולא ה\"ח דאבא ובאמת זהו פלא למה לא נמשך ה\"ח דאבא במל' שהרי עצם שרש המל' הוא מאבא דיסד ברתא ויסד זה בחסדי' דוקא וכמ\"ש באר חפרוה שרים כו' או\"א שנא' ויבן ה' אלקי' את הצלע דאו\"א תקינו לה כמ\"ש בזהר ואבא תיקן בבחי' החסד דבאתרה שקיע רחמי כו' (וגם עצם הצלע עצם מעצמיו שהעצמו' מן האב וגם תלה הכתוב זכרים בנקבות משום דאיש מזריע תחלה יולדת נקב' כידוע) וגם פי' באר חפרוה היינו במי החסדי' דוקא אמנם זהו לצורך עצמה אבל לצורך העולמות הרי אמ' והוכן בחסד כסא שהוא בחי' חסד דז\"א ולא חסד דאבא (וכמ\"ש בזהר ע\"פ אתה כהן לעולם על דברתי מלכי צדק שזהו ה\"ח דמל' שנק' מלכי צדק שמקבל מז\"א מבחי' חסד דז\"א שנק' כהן לעולם כו' ואמנם מבואר בזהר דבתלת דוכתי אקרי אתה כמו כי אתה אבינו והוא בחי' חסדים דאבא דוקא שזהו מה דאבא יסד ברתא לצורך עצמה כו') ובכ\"ז מובן הטעם לאות עי\"ן בתיבת ועד שהו' בחי' עין משפט דמל' (כמו ע' סנהדרין בלשכת הגזית שהוא בהיכל הגבור' ונקראו עיני העדה שכלול מחו\"ג ושפטו והצילו כו') דהיינו בחי' ה\"ג דבינה שנמשך למל' שהן ה' הויות גי' קל שהוא גי' עין כנ\"ל לצורך העולמות ולפי שחסר ה' הויות דה\"ח דאבא משום דכאמה בתה דוקא ע\"כ הוא באות ע' דוק' ולפ\"ז הקושיא דלעיל יותר באה בחזקה למה מן החי\"ת נעשה עי\"ן דזהו היפך גמו' דחי\"ת הוא בחכמ' שהוא מקו' החסדי' וכנ\"ל בפירוש כי ס\"ר לראות שהן י' הוי\"ות ואם נעשה אות עי\"ן ה\"ז מצד שחסר ה' הויו\"ת דאבא ואיך אפשר לומ' שמן החי\"ת דחכמ' יהי' עי\"ן במל' שמן החי\"ת הי' צריך להיות המשכ' החסדי' וגם שיהי' כלול מחו\"ג שזהו בכפל ממספר ע\"ין כנ\"ל (ומ\"ש והוכן בחסד כסא הרי הוא בחסד דז\"א ולא בחסדי' דאבא כנ\"ל ואם"],[1700400268,"נא' דאתה כהן לעולם קאי על כי אתה אבינו שהן ה\"ח דאבא דאבא יסד ברתא א\"כ למה נעשה אות עי\"ן ואם לא נמשך מחסדי' דאבא איך יאמר שמבחי' חי\"ת דחכמ' נעשה עי\"ן דהיינו חלק גבו' דאימא לבד כנ\"ל דדעת דנוק' כלול בדכורא כי לכך דעתן קלה כנ\"ל:\n(עד) <b>והנה</b> להבין תירוץ אמיתי על ענין החי\"ת שנעשה עי\"ן דוקא יש להקדים תחלה בענין ביאור כל הנ\"ל באלף דכתר וחי\"ת דחכמ' כו' הכל בעבודת ה' בתפלה דהנה ידוע שמחו\"ב שבנפש האלקי' נולדו המדו' שהן התפעלות אהבה ויראה ואמנם לא ראי זה כראי זה שהאהב' והירא' ב' הפכי' המה דהיינו בענין הקירוב והריחוק שאנו רואי' בחוש שטבע התפעלו' האהב' היא באה מצד בחי' הריחוק ביותר וטבע התפעלות היראה להיפך שהיא באה מצד בחי' הקירוב ביותר וכל שיהי' הריחוק יותר יותר יתפעל באה\"ר ונפלאה ביותר וכל שהקירוב ביותר יותר יתפעל ביראה ופחד עצום כו' דהנה אנו רואי' בחוש שכל מי שיראה את המלך או שר מקרוב בא אליו ביותר קירוב ובהתגלות יותר יפחד ביותר וארכבותיו נקשן כו' עד שיבא לכלל ביטול במציאות ממש שזהו הנק' יראה עילאה בחי' תכלית הביטות כו' עד שנעשה כאבן דומם בלי הרגשת עצמו כלל וזה תלוי באופן הקירוב דוקא כי יראה אותיות ראיה וכל שאינו בא בקירוב כ\"כ אין היראה ופחד כ\"כ וכמו פחד מן השונא כל שהוא מקרוב יותר תפול הפחד (וכמו ובכן תן פחדך כו' תפול עליהם אימתה כו' מצד עוצם הגלוי אלקות שז\"ש בגדול זרועך ידמו כאבן כו' וכן לע\"ל דכתיב ובאו במערות צורים מפני פחד ה' כו' היינו מצד בחי' הקירוב דוקא שאז יהיה גלוי עצום כמ\"ש ונגלה כבוד ה' כידוע וכן בפחד יצחק שהוא ג\"כ מצד עוצם הקירו' והגלוי כמ\"ש ויצחק בא מבוא באר לחי רואי כו' וכמ\"ש ופחד יצחק היה לי לי דוקא שבא מצד קרבת אלקים לי כו') וזהו היפך טבע האהבה שהאהבה תתפעל בסיבת הריחוק ביותר וכל שהדבר האהוב מקרוב אין מדת האהבה בהתפעלות אליו כ\"כ כמו שאנו רואים בחוש באב אל בנו או אהובו כנפשו שכל שיתרחק ממנו בזמן ומקום יותר יותר תכלה נפשו אליו באה\"ר ותתעורר האהבה והתשוקה אליו ביותר וכשרואהו תמיד בקירוב אין האהבה ניכרת כלל כו' וכמ\"כ בעבודה שבלב בתפלה התפעלות האהבה באה רק מהתבוננות הריחוק מאלקות והוא כשיתבונן בהפלאת השגה בעצמו' אח\"פ בעילוי אחר עילוי כידוע בבחי' סדכ\"ס וכה\"ג עד שנפלא ממנו לגמרי כו' אז יתפעל ויתעורר לבו באה\"ר ותשוקה נפלאה ליכלל ולידבק באח\"פ כו' וכל שקרוב אליו בהשגה יותר אין ההתפעלות אהבה כ\"כ לפי שההשגה והראיה בא בבחי' הקירוב כמו לאסתכלא ביקרא כו' שם ימצא בחי' הפחד והביטול דוקא כנ\"ל כמו שאנו רואים בחוש שכל מה שיבא אליו גלוי אלקו' בנפשו ויוקלט בעצם פנימי' כלי השגתו וחכמתו בבחי' ראיה שכלי' מקרוב מאד יותר יבא לבחי' פחד האמיתי בהעדר הרגשה עצמו מכל וכל שנק' יראה עלאה ירא' בושת כו' כמ\"שהן יראת ה' היא חכמה שהחכ' היא בבחי' ראי' מקרוב כנ\"ל שם הוא בחי' יראת ה' ירא' עלא' הנ\"ל ובירא' ה' בחי' ביטול שם הוא בחי' החכמה והכל א' ממש עד שא' דיראת ה' יראה עלאה הנ\"ל היא בחי' החכמה עצמה ואין לחלק ביניהן כלל משום דהא בהא תליא משום דהיראה תלויה בקירוב דראי' דחכמה דיראה אותיות ראיה כנ\"ל והאהבה מרחוק דוקא ולא מקרוב כנ\"ל (ובמ\"א מבואר להיפך ממש דחו\"ב הן ראיה ושמיעה דהיינו ראיה דחכמה מקרוב והשגה דבינה נק' שמיעה מרחוק ואינו דומה שמיעה לראיה והתפעלות האהבה מקירוב דראי' דחכמה והיראה מרחוק בהשגות דבינה כמו שמעתי שמעך יראתי וכמו העומד מרחוק כשנתפעל בירא' ופחד כמ\"ש וינועו ויעמדו מרחוק והאהב' הוא הקירוב והדביקות"],[1700400269,"דוקא כמו אברהם אוהבי הלוך ונסוע בדביקו' וקירוב אחר קירוב כאהב' האוהבי' שמתדבקי' יחד שטבע המים לדבק כו' וזהו היפך כל הנ\"ל באוי\"ר שהאהבה בריחוק כו' הענין הוא דבכאן מדבר באהבה שבעה בתשוקה וכלות הנפש מצד ריחוק המשפיע שהיא אהבה דבכל מאדך כמשי\"ת שזהו דוקא מצד הריחוק ביותר יותר תכלה נפשו כו' ולא באהבה שנמשך כמים שהיא בקירוב כו' וכן ביראה מדבר בפחד ובטול שבא לו מצד המשפי' שאינו אלא מצד הקירוב והגלוי דמשפיע כמו ובמור' גדול זו גלוי שכינ' כמ\"ש במ\"א ומה שמבואר במ\"א דיראה בבינ' בשמיע' מרחוק היא יראה שמצד המקבל וכן האהבה שמצד המקבל הוא להיפך בקירוב ודיבוק כו' אבל כאן מדב' באוי\"ר שבא מצד המשפיע דנהפוך הוא ממש וד\"ל) והנה התפעלות האה\"ר הנ\"ל שמצד הריחוק יוכל להיות בבחי' מס\"נ ממש שלמעלה מן הגבלת השכל וטעם לרצון בלי גבול כלל שנק' בכל מאדך שהרי כל מה שיפלא וירומם יותר בהפלא' גדולות אא\"ס ביותר מכלי השגתו יותר יצא מקשרי הגבלת נפשו מכל רצון רק לה' לבדו והוא התפעלות נקודת הרצון שלמעלה מו הטעם ושכל וזהו בבחי' כתר דאלף הנ\"ל שלמעלה מן החכמ' שנק' פלא ומבואר למעלה בענין וי\"ו דועד שנעשה מאלף דאחד שנמצא למטה כמו למעלה ממש בשוה להיותו בחי' המשכת המקיף כו' וזהו ג\"כ ענין זאת האה\"ר הנפלא' שמצד הפלא והריחוק שנק' כתר שבזה נמצלא גלוי אא\"ס למטה מטה בריחוק היותר כמו למעלה מעלה בקירוב ביותר מאחר שזהו למעלה מכל השגה וכל שיעמיק יותר להשיג יות' ויתעלה השגתו יותר יותר יפלא מהשגתו בריחוק ופלא כמו סדכ\"ס כו' ואז יותר בא גלוי אור בתוקף ונמצא תוקף אורו למטה דוקא בריחוק כמו למעלה ממש בקירוב היותר פנימי ונמצא שמאיר למטה ולמעלה בשוה כמו בחי' מקיף דא' דכתר הנ\"ל וד\"ל משא\"כ בחי' החכמ' שנק' ראי' מקרוב שמזה מתפעל ביראה ובטול הנ\"ל הנה בחי' הקירוב הזה א\"א שיהי' בא בגלוי ובקירוב למטה כמו למעלה ממש שלא יבאו התחתוני' לבחי' בטול במציאו' לגמרי כענין הושיט אצבע כו' ושרפן כנ\"ל אלא בהכרח צריך לבא בחי' גלוי האור דקירוב דחכמ' בסדר והדרגה בהשתלשלו' עו\"ע בכל עולם לפ\"ע כפי אשר יוכל שאת בבחי' הביטול והיראה שמצד ראיי' החכמ' ולכך אין בחי' הביטול שוה בכל העולמו' לפי אופן צמצום הגלוי אור דחכמ' שם וכמו באצי' שם הגלוי יותר מבחי' אור החכמה ולכך בחי' הבטול שם בתכלית עד דאיהו וחיוהי חד ממש כו' שזהו בחי' הבטול בעצם שהוא בשם מ\"ה דחכמה עלאה שנק' יראה עלאה שבא מתכלית הקירוב כמו במשה שהיה בבחי' מ\"ה דחכמה כמ\"ש ונחנו מ\"ה בטול בעצם לפי שבו היה הקירוב פא\"פ כו' ואהרן והזקנים למטה ממנו כו' וכן יובן שמאצי' לבריא' נפסק אור גלוי החכמה ואינו מתגלה שם בחי' הפנימית שבה כלל כנ\"ל דיו\"ד באצי' ולא בבריאה דאימא מקננא בכורסיא כו' ע\"כ בהגיע אות החי\"ת דחכמ' דאצי' בבריאה נעשה אות עי\"ן דהיינו חיצוניו' התפשטו' דחכמ' שנק' הסתכלות דח\"ע דאצי' שמאיר במל' בבחי' ההשגה דבינה בבחי' ז\"ת דבינה הבא בכלי השגת שכל בקירוב זהו הנק' עי\"ן לפי שקירוב זה דהשגה דבינה קירוב חיצוני' הוא לגבי עצם ח\"ע להיות שאינו מאיר שם רק בחי' חיצוניו' חכמ' שהוא בחי' ראי' דעין השכל בחיצוניו' ומעין השכל ראי' זו נעשה בחי' השגה בבינה (כמו רואין את הנשמע) ומזה לא נעשה רק בחי' בטול היש בלבד שזהו בעולם הבריא' שנק' יש מאין ויש מי שבטל כו' והיינו ע\"י ההשגה דבינה דאימא מקננא כו' ואינו אלא מבחי' הסתכלות חיצוניו' דח\"ע דאצי' שמאיר בח\"ת דמל' וזהו שמן החי\"ת דוקא נעשה עי\"ן וד\"ל ובזה יתורץ היטב הקושיא דלעיל איך"],[1700400270,"מחי\"ת יומשך ז\"ת דבינה דהלא חי\"ת דחכמ' הוא חיצוניו' הראי' והסתכלות דחכמ' שנמשך מאין ליש בבינה בכלי ההשגה שזהו הנעשה עי\"ן שהן ז\"ת דבינה שנכללי' בע' רבתי ונק' עי\"ן ע\"ש הראי' והסתכלו' דחכמ' כי מתייחדי' זע\"ז וכ\"ז משום דחי\"ת דח\"ע בא בהשתלשלו' בהדרגת עו\"ע ע\"כ בהכרח בהגיע אורו למטה בבריאה נעשה עי\"ן חיצוניו' חכמ' בז\"ת דבינה כו' אבל פנימי' ח\"ע שלא בא למטה כלל בהשתלשלו' ה\"ז כמו האלף דכתר שנמצא למטה כמו למעלה ממש בשוה מטעם הנ\"ל (וזה הי' ראי' והסתכלו' דמשה שהי' שרשו בפנימי' אבא דאצי' ועשי' שוין ולכך צוה לו לראות את א\"ימרחוק כו' וע\"ז נא' ותחצב אחותו מרחוק דלפעמי' החכמ' שהיא בחי' אחותו בבחי' הריחוק דהיינו כשהוא בבחי' פנימי הכתר שמאיר מרחוק כמו מרחוק ה' נראה כו' ושם שוה מעלה ומטה ממש כנ\"ל בוי\"ו דועד וד\"ל:\n(עה) <b>אך</b> הנה יש להבין לכאורה בענין כלל הנ\"ל דפנימי' ח\"ע לא יבא בגלוי אור למטה לעולם כמו שהוא למעלה רק בחי' חיצוניו' שבה לבד שזהו עין דועד כנ\"ל א\"כ האיך מצינו שירדה התורה למטה בגלוי ממש כמו שהוא למעלה ושרש התורה הוא ודאי מפנימי' חכמתו ית' כידוע ומבואר בזהר וגם בעיקר טעם עסק התורה אינו אלא להמשיך גלוי אא\"ס שבפנימי' חכמ' שבתור' למטה מטה כמו שהוא למעלה וכמ\"ש ותורה אור פי' אור המאיר ובא למטה כמו למעלה ממש שהרי מבואר בזהר דג' קשרין הן ישראל מתקשראן באורייתא ואוריי' בקוב\"ה וע\"י אדם שעוסק בתור' לשמה נתגלה ונמשך אא\"ס שבפנימי' ח\"ע שבתור' דאוריי' מח\"ע נפקת כידוע וזהו ענין עוסק בתור' לשמה לשם התור' כידוע ועוד דלפי כלל הנ\"ל דא\"א שיבא בחי' גלוי פנימי' חכמ' דאצי' למטה בגלוי א\"כ האיך א' והיו הדברי' האלה כו' ודברת בם כו' וידוע שעיקר מצות ת\"ת בדבור דוקא וכמ\"ש למען תהי' תורת ה' בפיך דוקא כדי להמשיך בדבור זה גלוי אא\"ס שבפנימית חכמה כמו ואשים דברי בפיך וכידוע בענין את ה' האמרת שהקב\"ה יושב ושונה כנגדו (ואפשר לומר דפסוק והיו הדברים כו' הוא אחר אהבה דבכל מאדך שהיא בבחי' הכתר שמעלה ומטה שוין כנ\"ל ועין דועד שהוא בחיצוניו' חכמה זה לא א' משה דבשכמל\"ו לא א' משה דמשה מלגיו בפנימית ח\"ע כידוע אבל באהבה דבכל מאדך אין זה גלוי אור ממש רק בהעלם כאות וי\"ו כו') אך הענין יובן בהקדים תחלה בשרש ענין אור דתור' שאין אור דתור' באה בבחי' השתלשלות ע\"וע כאור חכמה דאצי' הנ\"ל שאם הי' אור דתור' באה בהשתלשלות ע\"וע באבי\"ע מלמעלה למטה בכל עולם לפי ערכו ודאי שלא הי' אפשר שיבא גלוי אורה למטה כמו למעלה ממש אבל באמת אין גלוי אור דתורה בא למטה כ\"א ע\"י בחי' לבוש דוקא כמ\"ש על התורה עוטה אור כשלמה והלביש ושלמה זו שעוטה בה אור דתורה עי\"ז תוכל לבא בהתגלו' למטה כמו למעלה ממש באין שנוי כלל דהיינו שע\"י לבוש הזה יוכל לבא דוקא בחי' גלוי אא\"ס שבפנימית ח\"ע גם למטה מטה מה שלא הי' ביכולתו לבא בלא לבוש מטעם הנ\"ל וביאור הדבר צ\"ל ענין הפסוק כאשר יאמר משל הקדמוני דקאי על התורה שנק' משל הקדמוני לפי שקדמה לעולם הנאצל ונברא כו' והטעם לזה שנק' בשם משל דוקא הענין הוא לפי ששרש החכמה שבתו' הוא בבחי' עצמות ופנימית החכמה הקדומה שבעצמות אא\"ס ממש וכמ\"ש ואהי' אצלו אמון שעשועי' כו' בחי' שעשועים העצמיי' וכמו משחקת לפניו כו' וכל אור שהוא מן העצמות ממש א\"א שיבא למטה בגלוי כמו שהוא כ\"א ע\"י התלבשות בענין לבוש זר כמו ע\"י משל גשמי שיוכלו להשיג מתוכו אור עומק השכל כמו שהוא בעצם שבלתי"],[1700400271,"אפשר להשיגו בלא משל מצד עומקו ובהיות שהמשל הוא לבוש זר להעלי' ולהסתיר אור השכל עי\"ז יוכלו להביט ולהשיג בו כמו שרואין ע\"י מסך וכה\"ג כידוע ומה שא\"א להביא גלוי אור עומק השכל בדבו' יוכלו להשיגו ע\"י המשל דוק' כמו שאנו רואין שעד מ' שנין לא קאים אינש אדעתי' דרבי' שהשפיע לו בדבור אבל ע\"י המשל יכול להשיג מיד וגם לתינוק קטן יוכלו להשפיע ע\"י משלים שיקבל הוא לפי ערכו כל עומק השכל כמו שאצל המשפיע שלפי הלבוש של המשל יוכלו לתפוס הנמשל המלובש בו לעומקו משא\"כ ע\"י הדבור שהעומק ותמצית המכוון בשכל לא קאים עד מ' שנין כו' ואמנם מובן עוד דבלבוש המשל אין הפרש בין גדול לקטן שהכל יכולים לקבל ולהשיג ע\"י הגם שהגדול בחכמה ישיג הנמשל יותר לעומק והקטן ישיג זה בקטנות אין זה הפרש לגבי עצם אור החכמה הגנוזה במשל אעפ\"י שהשגתה יובדל לגדול יושג ע\"י המשל שנק' חומר לצורה יותר לעומק שכפי הערך של הגדול יכיר יותר לצור' שבחומר המשל מן הקטן זה היה הפרש גמור אם היה המשל לנמשל כחומר לצורה ממש כעין לראי' וכמוח לשכל אבל אם הנמשל במשל בא דרך התלבשות א\"כ אין חילוק כלל לגבי עצם אור החכמה מאחר שאין זה המשל רק בחי' לבוש לבד ומה שגדול ישיג יותר בו אין בה בפנימי' עצמו' החכמה רק בזיו הגלוי הנגלה מתוכה באמצעו' המשל שהוא מעין ודוגמא לנמשל דוקא וכמו משלי שלמה וג' מאו' מתלי דר\"מ וכה\"ג שמפני עומק החכמה צריך להלביש במשלים וכל שהחכמה עמוק' יותר יותר צריך להלבשת משלים ולכך משלי שלמה במעלה גדולה לעוצם עומק החכמה עלא' הגנוז בהם והיינו עוטה אור כשלמה ולבוש שלמה זה היינו בחי' המשלים שנק' משל הקדמוני ולזה אע\"פ שיש תור' דאצי' ותור' דבריאה ה\"ז לבושים שונים שבכל עולם מתלבשת אור דתורה לפי אופן זה העולם עד לבוש האחרון שבזה העולם בתורה הנגלית לנו אבל בעצם מהותה אין שנוי כלל כמו שהיא למעלה ולמטה באצי' ועשי' שוין מטעם הנ\"ל וד\"ל (וראי' לזה שלע\"ל כתיב ולא יכנף עוד כו' הרי הלבוש דתור' אינו מעלים כלל אדרבה ע\"י יראו אור העצמי כמו ובתורתו של ר\"מ היה כתוב כתנו' אור באלף כמ\"ש במ\"א וד\"ל ונמצא שיוכל לבא גלוי אור פנימית ח\"ע דתורה למטה כמו למעלה ממש מאחר שבא בבחי' לבוש וזהו שמצות ת\"ת להמשיך גלוי אא\"ס בפנימית ח\"ע שבתורה שזהו עוסק בתורה לשמה כנ\"ל וכלל הנ\"ל דא\"א לפנימית חכמה לבא למטה כמו למעלה היינו במלאכים שמקבלים מחיצוניות חכמה ולכך כשבקשו הוד ואור דתורה לא נתנה להם אף ע\"י משל ולבוש רק לישראל לבדם משום דישראל עלה במח' פנימית אבא כו' וכמ\"ש ג' קשרין הן כו' שהמלאכים מקבלים מעי\"ן דועד ומשה שהי' מפנימי' אבא א' שמע ישראל כו' ולא א' בשכמל\"ו וכן מי שתורתו אומנתו כו' כר\"י הנשיא וכה\"ג אינו קור' רק פסוק ראשון ואע\"פ שאין הלכה כאנשי יריחו שהיו כורכין את שמע כו' היינו לפי שאין הכל יכולים להיות בבחי' תורתו אומנתו כר\"י הנשיא וכמ\"ש במ\"א וד\"ל) ומעת' יש להבין ענין אות הדלי\"ת רבתי דאחד למה לא נשתנה בחלוף אתוון ביח\"ת כלל אלא רק מגדלות לקטנות לבד הנה יש בזה ב' טעמי' הא' מפני שבאמת הגם שמבואר למעלה בהפרש שבין כח הדבור לצרופי אותיו' הדבור שמתפשטי' מעצם כח הדבור שזהו ממש כמו הפעולה שמתפשטת מכח הפועל וכה\"ג מ\"מ לענין גוף השפע הנמשך מן כח הדבור לגלוי הדבור שהוא החכמ' שבראש שמגלה הדבור או הרצון והמדו' וכה\"ג הרי בזה אין שנוי כלל וכלל שהוא אותו השכל שמבין לעצמו בא לדבור כמו אדם שמדבר דבר שכל שגם שמשפיל ומביא לאור עצם השכלתו בדבור אין זה שינוי כלל לעצמו מאחר שהוא עצמו המדבר דבר"],[1700400272,"זה משא\"כ לזולתו יש שנוי שאין זולתו משיג רק מדבור שלו ואין בדבור רק גלוי אור בעלמא מן עצם השכל ולכך לא קאים אדעת' דרבי' כידוע וכך יובן בענין ירידת המל' מאצי' לבריאה דהיינו מכתר מל' שזהו עצם כח הדבור העליון כנ\"ל לחכמ' ומדו' הנגלים בדבור שהן ט\"ס דמל' בבי\"ע כידוע שאין זה שינוי לגבי עצם האדם העליון שנק' רוח ממללא רק שבכח הדבור הי' הדבור כלול בעצם החכמ' שמשם נמצא מציאת כח הדבור והי' בבחי' הגדלות (דהיינו להביא בכמה צרופי' עד אין שיעור כמו כח היולי דפועל טרם שיפעל וכנ\"ל בפי' ודבר דבר כו') ובגלוי הדבו' בא לכלל קטנות אבל אין שנוי כלל בעצם לכך לא נתחלף אות שלי\"ת דיח\"ע להיות באות אחרת ביח\"ת בועד אלא הוא אות הד' דיח\"ע רק שנשתנה מגדלות לקטנות לבד משא\"כ הא' והחי\"ת דיח\"ע שלא הן בעצמן ומהותן יורדין למטה רק שמתלבשים ונמשכי' למטה הא' נמשך דרך קו בהעלם כנ\"ל והחי\"ת משתלשל דרך עו\"ע ממש ע\"כ בהכרח שיהי' שנוי וחילוף לאות אחר בהגיע אורם למטה מאצי' לבריאה כמו מן הח' נעשה וי\"ו כו' [אבל הדלי\"ת הוא עצמו נמשך שהרי כח הדבור הוא שמדב' דהיינו שהעצם הוא מתפשט ולא כמו החי\"ת דחכמ' שמאין תמצא שזהו ג\"כ רק גלוי והתפשטו' מן העצם ולכך נשתנה מא' חי\"ת ששם בא בדילוג גדול ממהות למהות שזהו מאין דאאלפך שנבדל מהיות מקור לחכמ' ומפלא נעשה אלף ע\"י מזל ונוצר כנ\"ל לכך נעשה חי\"ת כו' משא\"כ הכח של הדבור הוא עצמו בא לגלוי ונק' השפע' עצמי' ומקורי' כמעיין שהוא עצמו מתפשט בנהר וכשרש האילן שהוא עצמו צומח ולא בבחי' שפע אור וזיו כמ\"ש במ\"א וד\"ל] אך הנה עכ\"ז אין זה מתיישב לנכון דודאי יש הפרש גדול בין עצם להתפשטו' בכ\"מ אעפ\"י שהעצם עצמו בא בהתפשטו' כמו ענין המילויי' של כל אות כיוד ואלף בית ולמה במילוי דה\"א באלף אין האלף ניכר במבטא ומכ\"ש כשהוא במלוי ה' ה\"ה או גם במילוי יו\"ד כמו הי ועיקר המילוי שלו ה' הרי ה\"ה אין שנוי כלל בה' הב' מה' הראשון כו' משום דה' הוא אתא קלילא דלית בי' ממשא כו' דהיינו ה' מוצאות הפה דדבור שאינו רק בחי' גלוי לחוץ שאין בזה עצם דבר שיבא בו מילוי אות אחר בהתפשטות רק הה' עצמו נכפל כו' וביאור הדבר צריך לומר טעם שני בענין הד' ג\"כ מה שלא נשתנה כלל והוא העיקר להיות ידוע דנעוץ תחלתן בסופן דהיינו בחי' הכתר במל' ומ\"ל בכתר דסוף מעשה עבמ\"ת דלכך בבחי' ע\"ס דאו\"א המל' הוא בחי' כתר וע\"כ א' דכתר מל' איהו כ\"ע ממש וכמ\"ש במ\"א בענין ארוממך אלקי המלך כו' בענין סופא דמח' ותחלת המח' כו' לזאת אין באות ד' וה' שהן בבחי' המל' שהוא הדבור חילוף ותמורה בהתפשטות שלהם למטה שמעלה ומטה שוין ממש מאחר שהמל' הוא בחי' כתר והכתר הוא בחי' מל' הרי עליון תחתון ותחתון עליון בהכרח שהוא בבחי' המקיף עצמו ששוה שם מעלה ומטה ממש וביאור הדבר הוא ענין תחלת המח' אנא אמלוך שנק' מל' דא\"ס וסופא דמח' מל' דאצי' ונעוץ תחלה בסוף וסוף בתחלה עד שאין לחלק ביניהן כלל ובאמצעות תחלה וסוף יחד נשלם הדבר כמו הרוצה בדבר מו\"מ שאין עיקר השלימות לא בתחלת המח' טרם שבאה לגמר המעשה ולא כשבא לפ\"מ ולא נגמר עדיין תחלת הרצון אלא כשנשלם הפ\"מ כפי שהי' תחלת המח' ורצון כמו וירא כו' והנה טוב כו' הרי תחלה וסוף כא' ממש חשיב ואין זה בלא זה מהות בפ\"ע ולכך לפעמים המל' כתר בבחי' או\"ח דסוף עולה בתחלה וכאשר תחלה נמשך בסוף נק' או\"י ושניהם א' ממש ע\"כ עליון תחתון ותחתון עליון כעיגול כו' וזהו עיקר הטעם מה שאין המילוי דה' רק ה\"א להיותו רק בחי' גלוי כנ\"ל שהגלוי רצון א' הוא לכך אין הפרש בגלוי הרצון שבתחלת המח' לגלוי הרצון שבפ\"מ כנ\"ל וזהו שהדלית רבתי שהוא מל' דא\"ס הוא מל' דאצי' כמ\"ש אני"],[1700400273,"ראשון כו' אני אני הוא והוי\"ו דמא' דיח\"ע אינו אלא דרך המשכה מעליון לתחתון לכך הוא בא בשנוי קו שהוא הוי\"ו אבל כשנשלם תחלה בסוף יחדיו יהיה תמים כמהות א' ממש בלי יצטרך לחבר ולהמשיך מזה לזה ולכך הדלי\"ת רבתי הוא דלי\"ת ביח\"ת כמ\"ש אני אני ולא ואני אחרון רק שבא למטה בבחי' קטנות דבי\"ע כו' ולמעלה בעצמו' הרצון הוא בבחי' הגדלות דא\"ס עצמו כו' אבל לא שנוי בעצם כלל כמ\"ש אני ה' לא שניתי וד\"ל:\n(עו) <b>והנה</b> אחר שנתבא' ענין ועד בחלופי אתוון דאחד כנ\"ל עתה יש להבין מה שהע' דתיבת שמע ע' רבתי והדלי\"ת דאחד ולא אותיות זולתם כלל וידוע ביאור וטעם לזה בזה' פ' פנחס (דרל\"ו ע\"ב) פתח ר\"ש ואמר שמע ישראל כו' ע' רברבא ד' אוף הכי וסימנא דא עד היינו דכתי' עד ה' בכם אשתארון אתוון ש\"מ מ' פתיחה מ\"ט לא סתימא בגין דמ' סתימ' מלכא עלא' מ' פתיחא מלכא תתאה ע\"כ והנה מבואר דבתחלת המא' בא להקשו' מפני מה הע' רברבא וד' דאח' אוף הכי ולא שאר אותיות זולתם כמו ש\"מ דשמע וא\"ח דאחד וגם לא בתיבו' אחרו' דפסוק זה ותירץ לקושיא זו משום דאותיות הללו ע\"ד צריכים דוקא להיות באותיות גדולים ולא אותיות זולתם דסימנא עד ה' בכם ולכאורה לא תירץ כלום דמשום הסימן דעד ה' כו' אינו מוכרח כלל שיהי' ע' דשמע וד' דאחד דוקא גדולים שאין הסימן עד' ה' בכם שייך עם ב' תיבות הללו דשמע ואחד ועוד שהע' וד' הללו רחוקים זמ\"ז ביותר כו' אך הנה תחלה יש להקדים להבין מהו ענין אותיות גדולים דהנה ידוע בע\"ח שיש ג' מיני אותיות גדולים ואותיות בינונים ואותיות קטנים אותיות גדולים בבינה ואותיות בינונים בז\"א ואותיות קטני' במל' וא\"כ כאן שא' ע' רברבא בודאי ע' זהו בבינה וד' אוף הכי בבינה וזהו עד כו' ולהבין זה הנה מבואר למעלה בענין אות העי\"ן דועד בטעם אות ע' שהוא ז' מדות כלול כאו\"א מי\"ס דוקא אז המספר ע' ובכאן שהע' רברבא הרי מדבר בז\"ת דבינה שהן מדות שבשכל שהן גדולים הרבה ממדו' שבלב כנראה בחוש שהתפעלו' האהבה והחסד ורחמים וכה\"ג בשכל מתפשט ברוחב גדול בכמה אופנים שונים כו' ובהגיע התפעלות זו להתפעלות הלב תקצר כו' לפי שאור הבינה שבמוח ההשגה כשבא לבחי' אותיות שהן אותיות המחשבה המתארים ומציירים בגלוי למדות שבשכל כאוי\"ר וכה\"ג הן בחי' אותיות גדולות מאד כערך גדלות השכל שבמוח וכמ\"ש לפי שכלו יהולל איש שהן אותיות מדות שבשכל שגדולים לפ\"ע גדלות השכל של איש כו' אבל האותיות שבמדו' שבלב המתארי' ומגבילים אותם נקראו אותיות בינונים ובהגיע המשכו' המדו' שבלב באותיות הדבור שהוא בחי' אויר נבדל לחוץ נק' אותיות קטני' כידוע וזהו ביאור ג' מיני אותיות דבינה וז\"א ומל' ובכאן אמר דע' רברבא שהן אותיות מדות שבשכל והוא בחי' אחוריים דאימא שמשם מקבלת מל' דתבונה שהוא בחי' לאה כידוע שזהו דלי\"ת רבתי דאחד והוא ענין קשר של תש\"ר כו' וז\"ש לסימן עד ה' כו' לפי דדלי\"ת רבתי בחי' מל' דתבונה מלבשת לבחי' תנה\"י דאימא דהיינו לנצח והוד ויסוד דאימא וגם לשליש ת\"ת דבינה המכריע ע\"כ הוא באות דלית דוקא לפי שמלביש ד' מדרגות תנה\"י דבינה וע\"כ גם הד' רברבא אוף הכי כי גם הוא בבחי' הבינה שהוא בחי' אותיות המח' דבינה אלא שהוא בבחי' המל' שהן האותיות גדולים הנ\"ל ובחי' המל' ל\"ל מגרמה כלום ונק' דל כידוע בענין חסד ח\"ס דלי\"ת וכן משכיל אל דל לכך נק' דלי\"ת ע\"ש הדלות וכמו שידוע בענין בחי' מל' דז\"א שהוא בחי' אותיות הדבור שהוא ג\"כ באות דלי\"ת מטעם זה שמלבשת לבחי' תנה\"י דז\"א שהן ד' מדרגות וגם נק' דל מטעם דלית"],[1700400274,"לה כו' אלא שמל' דתבונה הנ\"ל נק' דלי\"ת גדול להיותו בבחי' הגדלות דאותיות דבינה והוא בחי' עלמא דאתכסיא שזהו ה' ראשונ' דשם הוי\"ה כו' ודלי\"ת דמל' דז\"א הוא דלי\"ת קטן להיותו בבחי' הקטנות דדבור עלמא דאתגליא כו' ולהבין ביאור הדברים הנה תחלה יש להבין איך שבחי' מל' דז\"א נק' דלי\"ת ע\"ש שמלבשת לבחי' תנה\"י דז\"א ומזה יובן בדלי\"ת רבתי בחי' מל' דתבונה שמלביש לתנה\"י דבינה דהנה ידוע בביאור ענין נו\"ה שהן כמו בחי' כליות יועצות איך להשפיע שנק' עצה שכולל הן ולאו בהיות ידוע שמהות ועיקר השפע הן עצם של המדות חג\"ת כי אור החסד הוא מדה במהות ומציא' ממש וכן מדה\"ד או הממוצע מבין שניהם שהוא הת\"ת המכריע אבל נו\"ה אינן בחי' מדות בעצם רק שהן יועצות איך להביא משפע של המדות חג\"ת כמו תרין ירכין שאינן גופו של אדם רק שמוליכין אותו כו' כידוע וענין העצה דנו\"ה יובן עד\"מ באדם שמתייעץ באיזה דבר מה אם לעשותו אם לאו כמו לבנות בנין או עסק מו\"מ וכה\"ג הנה אנו רואים כשמתייעץ אם לעשות יעלה תחלה כל חלקי הסותר המנגד שאין ראוי לעשות ולבנות והוא כל הטעמים שהמה המונעים העסק ואח\"כ מיד יעלו הטעמים שראוי לעשות ולעסוק ואח\"כ ישקול הדבר בעצתו איך ומה לעשותו דהנה לפי שהן ולאו ב' קוין רחוקים לעשות הכל או שלא לעשות כלל וא\"א אלא באחד משניהם או לעשות או שלא לעשות ולא יכול להכריע כי שניהם שקולים שזה וזה יוכשר כי לא יגבר טעם המונע על טעם המחייב ולזה צריך עצה איך יוחלט הן או לאו וא\"כ לכאורה עצת הכליו' הוא להחליט על הן או על לאו וזהו לא נק' עצה אלא הענין הוא דההכרעה בין המונע ומחייב כבר נעשה והו' בחי' הת\"ת שמכריע בין חו\"ג רק לענין לעשות כך בפ\"מ צריך להתיישב מחדש אולי לא יתכן לעשות כך וזהו עיקר העצה כידוע ואמנם אין פסק והחלט בנו\"ה שהן ב' הפכי' למנוע המעשה או לחייב המעשה אלא עיקר העצה שיהי' המעשה באופן זה דוקא ולא באופן זולתו ותחלה יעלה החלקים המונעים אופן המעשה דהיינו שבאופנים כאלה א\"א לעשות ואח\"כ יעלה החלקים והאופני' שיחייב המעש' באופנים כאלה וחוזר וסותר לפרטי אופנים שלא יוכשרו ואח\"כ יבחר במה שיוכשר עד כמה פעמי' יתיישב כך שזהו הנק' ישוב בעצה איך ומה לעשות אם כך או כך ולא שיוחלט מיד איך ומה דהיינו שזה האופן יוכשר וזה האופן לא יוכש' דאין זה נק' עצה וא\"צ לשאול בדבר הידוע שזה ראוי לעשות וזה אינו ראוי אלא בדבר השקול שיכולים לומר על ראוי לכאורה שאינו ראוי ועל שאינו ראוי ראוי עצתו יבחר הא' ויעזוב השני או שיעשה באופן שיברר איך ומה שיתכן לכל הדיעות (וזהו הנק' בל\"א גיקלערט די זאך או גישטעלירט כמ\"ש במ\"א) כי זה צריך לחזור מלאו להו ומהן ללאו בכמה אופנים כמה פעמים עד שימצא דבר המוחלט לעשות כך וכך דוקא והדבר שנתברר ע\"פ עצת הכליות איך ומה יעשה או ידבר אז הוא שולח ועושה ונק' יציאת אור גלוי השפע הזאת הבאה לאחר הברור דכליות יועצות כך וכך בשם יסוד וכידוע דנו\"ה אינם באים בגלוי עדיין כי המה היועצים וגומרים העצה איך ומה להשפיע אך מה שיושפע על ידם נק' יסוד וי\"ו זעירא כו' ככליות שמבשלות הזרע שמתעכב בהן זמן מה ואח\"כ יוצא הזרע בפי האמה כו' וכך נו\"ה נק' שחקים יזלו צדק כו' או נק 'מאזני צדק ששוקלים השפע איך וכמה ואח\"כ נשפע ביסוד כו' אמנם הנה העושה המשקל בנו\"ה שהוא ענין ההשואה שנעשה בעצה שיהיה כך ולא כך לכאורה אינו מובן מהיכן יבא מאחר שהן ב' קוין מנגדים זה מונע וזה מחייב ומי ימצא פשר דבר להכריע ביניהם אם לא כמו בחי' ת\"ת המכריע בין חו\"ג והוא בחי' שליש ת\"ת האחרון דת\"ת שהוא השייך למעשה בלבד כי ת\"ת בעצם הוא ההכרעה בין המדות בעצם טרם שיעלה ברצון להשפיע"],[1700400275,"כלל אך שליש ת\"ת זה הוא בחי' נה\"י דת\"ת שזהו מה ששיך לבא למעשה והוא הנותן כח ועוז בנו\"ה להכריע המשקל דמאזני צדק שיהא בא לגמר עצה בפסק מוחלק להיות אופן המעשה כך וכך דוקא ולא כך וכך כו' והיינו כללות ענין ד' מדרגות תנה\"י בכ\"מ ומעתה יובן כ\"ז בבחי' תנה\"י דז\"א דהנה בחי' המדות שבלב בעצם נק' חג\"ת כידוע והנה אנו רואים כשאדם רוצה להשפיע המדו' חג\"ת שבלבו לדבור בגלוי באיזה ענין דבר מה הנה ודאי יתיישב תחלה אם לגלות בדבור כלל וכמו לבא לפומא לא גלי ויש בזה ב' קוין שקולין הן ולאו ואם יתייעץ יהי' ענין העצה כנ\"ל דהיינו שמתייעץ איך ובאיזה אופן זולתו לא יגלה אלא יעלים ותחלה יעלה כל חלקי אופני' בצרופי' שלא יגלה בדבור הנק' נצח המנגד לעמוד על חלקי הסותר להעלים במה שצריך להעלים בדבור וההוד בא להיפך לגלות במה שיתכן לגלות בדבור ובזה הוא עיקר העצה כמה יהי' ההעל' וכמה יהי' הגלוי באיז' אופן כו' ויתישב בהן ולאו כמאזניי' ששוקלי' וכמה פעמי' מכריע לבחי' הן יותר מלאו וכמ' פעמי' ללאו יות' מהן עד שימצא דבר ברור באופן כזה וכזה יהיה הגלוי ולא יותר (בל\"א אוש גיקלערט כו') (וכמ\"ש במ\"א שזהו מכבר הנחשת שע\"ג המזבח שזהו בחי' הבירור שבנו\"ה דז\"א ומל' וכמו שחקים שטוחנות מ\"ן כו') והדבר הנבחר ונחלט יותא לגלוי מן המשפיע זהו נק' יסוד ז\"א כמ\"ש בזהר בראשית יקוו המים כו' אל מקום א' זהו יסוד שהוא גלוי שפע דמדו' דז\"א במל' שנק' דבור באופן מיוחד ונק' וי\"ו זעירא כידוע והעושה המשקל הנבחר במאזניים דנו\"ה הוא בחי' שליש ת\"ת האחרון דז\"א כנ\"ל ונק' כללות ד' אלה בחי' תנה\"י דז\"א שנמשכי' לדבור שהוא בחי' המ\"ל דז\"א שמלבש' לד' מדריגות הללו כידוע דאותיות הדבור אינו רק בחי' לבוש דומם לגבי הארות הד' מדרגו' בחי' תנה\"י דז\"א ולכך נק' דלי\"ת כנ\"ל וד\"ל:\n(עז) <b>והנה</b> כמ\"כ יובן הכל בבחי' מל' דתבונה שהוא דלי\"ת רבתי דאחד שהוא מלביש לתנה\"י דאימא כנ\"ל זהו ע\"ד ע' וד' רברבין כנ\"ל דהנה ידוע שהמדות שבשכל שנק' ז\"ת דבינה גם הן באין בב' מדרגו' כמו במדו' שבלב והיא בחי' חג\"ת שהן עצם התפעלו' המדו' שבשכל להטות לזכות או לחוב או לבחי' ממוצע שמבין שניהם ועדיין הן למעלה מבחי' השפעה שיבאו לגלוי לא בדבור ומעשה לבד אלא גם בלתי יבאו להתפעלו' בלב כמו שיכול להיו' התפעלו' חו\"ג במוח ולא יולדו בלב כלל וגם שבהיותן במוח צריכי' לבא לגלוי במוח באופן מיוחד במח' שבמוח שהרי כמו שהדבו' הוא לבוש נבדל לגבי המדו' שבלב כך אותיו' המח' לגבי מדו' שבשכל כמו לבוש נבדל כו' ואמנם קודם שיומשך אור עצם המדו' חג\"ת דבינה במח' שבמוח שנק' מל' דתבונה כנ\"ל צריך להיו' ג\"כ כמו בחי' כליות יועצו' שנק' נו\"ה שבמדו' שבשכל כנ\"ל במדו' שבלב ממש והוא שיתיישב במוח בשכל אם יובא השפע דמדו' דשכל לכלל גלוי במח' אם לאו בכל חלקי המונע והמחייב וישקול הדב' עד שיוחלט אופן מיוח' כנ\"ל וההחלט הוא עפ\"י בחי' שליש ת\"ת דאימא המכריע בין חו\"ג שבעצם כו' להביא לגלוי במ\"ת שנק' מל' דתבונה באופן כך וכך ולא כך וכך וזהו הנק' עצה במדו' שבשכל שנק' נו\"ה דאימא איך ומה וכמה יהי' העלם השפע שלהם באותיו' המח' ואיך וכמ' יהי' הגלוי כו' ומתעכב זמן מה עד שתפול העצה בגמר דבר באיזה אופן יוכשר לבא באותיו' המח' כו' וזהו הנק' בחי' תנה\"י דאימא לפי אופן הנברר בתנה\"י דאימא לבא במח' כך ממש יובא בדבור ע\"י תנה\"י דז\"א במל' דז\"א שנק' דבור לא יוסיף ולא יגרע דבר ממש שהרי בחי' יסוד אימא הוא אשר קולט אור הנברא עפ\"י עצה דנו\"ה דבינה ומשפיע לאותיו' המח'"],[1700400276,"באופן מיוחד כנ\"ל בבחי' יסוד ז\"א למל' שהוא הדבור שהמח' לבוש למדו' דשכל כדבור שהוא לבוש למדו' שבלב כנ\"ל וא\"כ איך יגרע וישונה דבר או חצי דבר מן המח' אל הדבור גם בעברו דרך המדו' שבלב אם לא יעלים בנו\"ה דז\"א מה שבלבו מכמו הנברר בנו\"ה דבינה כו' ובזה יובן המאמ' הכולל כל ענין הנ\"ל והוא בענין י\"ב שעות הוי היום יב\"ש ראשונות יושב ועוסק בתורה פי' המוחין של המדות להטות לזכות או לחוב או לממוצע דמלך במשפט יעמיד ארץ דכל שפע העולמות בי\"ע במשפט התורה דוקא נשפטי' בכל יום כמו השופט כל הארץ כו' ובכל יום יש יב\"ש י\"ב צרופי הוי' (דחסד אל כל היום יום א' חסד דז\"א כלול מיב\"ש כו' ובכלל אלף שנה הראשונים וכן בכל יום בפרט יש יב\"ש ויושב ועוסק ודן וזן בכל העולמות בהשגחה פרטיות ולכך ימצאו שנויים בכל עת ושעה בכל העולמות כמו שא' אדם נידון בכל יום) והנה ג\"ש הראשונים הן מוחין שבמדות שבשכל וג\"ש השניים הן מדות שבשכל להטות לזכות או לחוב וזהו יושב ודן כאדם שפוסק דין מתוך שכל וסברא המטה לחסד או לדין וג\"ש הג' יושב וזן את כו' היינו כמו בחי' מדות שבלב שנמשכי' לדבור להיות השפע מאין ליש עד שפע גשמית דעוה\"ז השפל לזון את העולם בגשמיות אם כך או כך ויש בזה שנוי מיום ליום (כמו והימים ימי בכורי כו' שאז היה זמן שליטת אור הגבורות דבחי' דין שבמדות דבינ' כו') וזהו לפי אופן שנוי הצרופים דמח' מל' דתבונה שמלבשת לתנה\"י דבינה ומשם יורד למדות דז\"א ומז\"א למל' בבחי' הדבור הרי שכולל כל ענין הנ\"ל במאמר זה יושב ודן יושב וזן כו' ולא יוסיף ולא יגרע בכל יום מכמו שדן במדות שבמח' כך זן במדות בדבור) והנה בחי' מל' דתבונה ד' רבתי שזהו אותיות המחשבה מלבשת לתנה\"י דאימא כנ\"ל במל' דז\"א שהוא הדבור שמלביש לתנה\"י של מדות שבלב כו' שצרופי אותיות המחשבה הן ג\"כ בחי' דומם בערך לגבי אור השכל שמטה כלפי חו\"ג כו' והיינו בחי' ע' רברבא שהן ז\"ת דבינה שמתלבשים בדלי\"ת רבתי שגם הדלי\"ת רבתי הוא בבינה כנ\"ל ולהיות שהמדו' דבינה באי' באותיות המח' בבחי' גדלו' השכל נק' אתוון רברבין כנ\"ל שלמעלה הרבה מאותיות בינונים דמדו' שבלב שנק' ז\"א לכך הדלי\"ת רבתי כמו הע' רברבא כו' וד\"ל ובכ\"ז יובן מ\"ש כאן בזוהר שמע פי' רברבא שהן בחי' ז\"ת דבינה כנ\"ל דלי\"ת אוף הכי רברבא שהוא בחי' מל' דתבונה שמקבל מתנה\"י דבינה ומלבשת אותם כנ\"ל ולכך הדלי\"ת רבתי כמו הע' לפי שהד' הוא אותיו' המח' שהן בחי' כלי בית קיבול למדו' שבשכל ומלבשת אותם ממש כמו שאנו רואים שאותיות המח' מכילים את אור השכל שנשפע בהן ובהן ועל ידן יושלח אור שפע השכל שבמדות ללב או לדבור ומאחר שהן בחי' בית קיבול להכיל גדלות אור הבינה ע\"כ הד' רברבא כמו הע' שהן המדות שבשכל ואמנם נק' דלי\"ת כמו דל דלית לי' מגרמי' כלום הענין הוא לפי שעצם אור השכל המושג נבדל הוא בערך ומושלל ומופשט מבחי' אותיות המח' כידוע בענין מחשבת שכל ממש הנק' עיון שכלי גם היותו במדות כמו שכל הנוטה לזכות וכאשר צריך לבא בהשפעה נגלית בבחי' אותיות המ\"ח ה\"ז כמו שנמשך המדו' שבלב בדבור דלית לי' כלום מעצמו כדל רק מה שנמשך בהן מאור שפע השכל שהרי כשיסתלק אור השכל מן האותיות דמח' נק' אותיות בטלים ורקנים מבלי שום שפע אור שכל (כמו הרהורים דברים בטלים כו') (ובאמת אין המח' דומה עם הדבור שהדבור אין לו מציא' בלא הבל הלב כידוע ואותיו' המח' יש להן מציא' בלא שכל כמו הרהורים שמהרהר אדם תמיד שאין בהן שכל כלל ולכך המל' נק' דל והוא הדבור ולא המח' ומה שהיא באות דלי\"ת מאחר שהוא בבחי' הגדלו' דבינה אין זה ע\"ש הדלות אלא לשון דלייה והגבהה כמו דלה דלה לנו"],[1700400277,"כו') ומעתה יובן לשון המאמ' דלעיל במ\"ש ע' רברבא ד' אוף הכי וסימנא דא עד כו' דהנה מה שאות ע' וד' דוקא רברבין ולא אותיו' זולתם כלל מבואר ע\"פי כל הנ\"ל משום דע' במדו' שבבינה וד' במל' דבינה ששם האותיות בבחי' גדלות ולכך הן גדולים אך עדיין אינו מובן בטעם חיבור אותיות הללו יחד שהוא לכאורה חיבור ב' אותיו' מרוחקי' זמ\"ז ביותר ע' משמע וד' מאחד ולזה אמ' דחיבור זה הוא להיות תיבת עד דוקא כמ\"ש עד הוי' בכם והענין הוא להיות ידוע בשרש ענין העדות שאינו אלא על דבר הנסתר ונעלם דוקא שצריך עדו' ע\"ז להעיד עליו שישנו במציא' לפי שנעל' מעין כל אבל דבר הנגל' לעין כל א\"צ עדות להעיד על מציאותו אחר שנודע ונגלה לכל לא יתכן שם עדות ע\"ז כלל כמו עידי הלבנה שמסתתרת כנקודה ונעלמת מעין כל צריך עדים להעיד על מציאות' אבל בהגלות נגלות לכל לא יתכן עדות כמו שלא יתכן עדות שראה השמש בחצי השמים וכה\"ג בכל עדות איש לחבירו אינו נופל רק בדבר שנעלם מהכל שעשה בהסתר והוא ראה וידע מזה אבל על הנעשה בגלוי לכל לא יתכן שם עדות כלל כידוע וכך הוא בכל דבר הנסתר ונעלם לגמרי בטבע האנושי שא\"א לאדם לידע כלל מזה כמו הנסתרות מלב כל אדם לידע מה שבסתרי מצפוני לב וכליו' מה שבלב זולתו שאינו ידוע רק לה' היודע כל הנסתרות ובוחן כליות ולב ותעלומו' סתרי כל חי נגלו לפניו אז לשון בני אדם לומר על דבר הנסתר ונעלם מכל אדם ה' יהי' עד בדבר לפי שהוא יודע כל הנסתרות ויודע תעלומו' סתרי כל חי מה בחדרי לבו סתומים מכל אדם כו' וכך יובן למעלה בבחי' עדו' ה' כמ\"ש עד ה' כו' שלא יתכן בחי' עדו' זו רק בבחי' ההעלם וההסתר שלא נודע בגלוי כלל כמו הנסתרות לה' אלקינו שהן בחי' חו\"ב כו' שבחי' בינה נק' עלמא דאתכסיא ששם כל בחי' העלם והסתר (ונק' מי דלא קיימא לשאלה) וכמו שמבואר במ\"א בפי' ששם עלו שבטים שבטי י\"ה די\"ה היינו הנסתרות לה' אלקינו בחי' חו\"ב דאצי' שהשבטי' הן י\"ב ג\"א שבמדו' דבינה נק' שבטי י\"ה ומשם עדות לישראל דוקא שצריכי' לעדות להיות שהוא נסתר ונעלם לכך צריכי' לעדו' דהיינו מי שיגיד על מציאות' והוא מי שיודע את הסוד וההעלם והוא בחי' חו\"ב שנק' י\"ה שהנסתרות נגלה לשם לבד כמ\"ש הנסתרו' לה' אלקינו כו' כמו לפניך נגלו כל תעלומו' כו' ולכך עדו' לישראל משם דוקא אבל בבחי' עלמא דאתגליא לא יתכן לשון עדות שהכל יודעי' שם כו' וכך יובן כאן במ\"ש עד ה' בכם פי' בכנ\"י ששרשם בחי' ישראל דלעילא ודוקא מבחי' י\"ה דהוי' עד בכם ששם הוא כל בחי' ההסתר והעלם והוא מבחי' בינה שנק' עלמא דאתכסיא כי הנסתרות לה' כו' שהוא יודע כל הנסתרות ואין העלם לפניו לכך הוא דוקא עד בדבר ואין זולתו שיעיד כו' כמא' הוא העד כו' כי נעלם מהכל רק לו לבדו נגלה כל העלם והסתר כו' כנ\"ל במשל עדות שבין איש לרעהו בדבר שבסתר שנעלם מכל אדם שיאמר יהי' ה' עד בדבר כו' וזהו שא' כאן וסימנ' דא עד ה' בכס פי' סימן לחיבור ב' אותיות דע' וד' אע\"פ שרחוקים זמ\"ז הוא בחי' העדו' דעד ה' כו' שאין זה אלא בבחי' בינה דוקא כנ\"ל דע\"כ ב' אותיות הללו באותיות גדולות ושם יש להן חיבור זע\"ז להיות תיבת עד בבחי' עדות כי העדות משם דוקא בא כנ\"ל והוא בחי' מדות ומל' דבינ' שהוא ע' וד' רברבין והוא בכלל ה' ראשונה דשם הוי' שיעיד על ה' אחרונה שזהו בחי' מל' דז\"א שרש כנ\"י למטה וזהו בכס וכמ\"ש בר\"מ פ' שופטי' על פסוק ע\"פ ב' עדים כו' (ושם מבואר באופן אחר):\n(עח) <b>ועוד</b> צריך להבין מ\"ש במא' הנ\"ל אשתארו אתוון ש\"מ מ' פתוח' מ\"ט לא סתימ' כו' הנה"],[1700400278,"מ\"ש אשתארו כו' בא להקשות בזה למה אותיות דש\"מ הן קטנים ואשתארו בבחי' הקטנות והע' רברבא כו' וקושי' זו מתורץ מעצמו ויש להקדים תחלה להבין שרש ענין ש\"מ דשמע שהוא בחי' מל' דאצי' שנק' שם כמ\"ש ויעש דוד שם וכן ברוך שם כו' והטעם ידוע בס' הקבלה לפי שבחי' המל' יורדת למטה לברר ברורים דרפ\"ח נצוצין שנפלו בשבירה כו' והוא בחי' שם ב\"ן המברר כידוע וכאשר עולין רפ\"ח נצוצין ונכללין בשם ב\"ן ה\"ז מספר ש\"מ כי רפ\"ח עם ב\"ן עולה ס\"ה ש\"מ וזהו ויעש דוד שם (ולע\"ל נא' טוב שמן משמן הטוב והיינו כתר שם טוב דמשיח שלמעלה מכתר מל' דדוד שנא' בו ועשית לך שם כשם הגדולים כ' אך כאן אינו מדבר בשם עצמו רק מה שיוכל לברר רפ\"ח כו' והוא מ\"ש ותקם בעוד ליל' ותתן טרף כו') והנה ידוע דירידת המל' בבי\"ע לברר ברורים הוא בא בבחי' הקטנות כדרך כל מברר שצריך להתלבש בלבוש המתברר כו' (ועוד שנעש' ראש לשועלי' כו') והוא בלילה דוקא כמ\"ש ותקם בעוד לילה ותתן טרף רפ\"ח ע\"ה וכמ\"ש טרף נתן ליראיו שמסתתרת בהיכלו' דנוגה (וכמ\"ש בזהר דאזלית לטורא חשוכ' ומשם ארחת מזונא כו') ע\"כ בחי' המל' בבחי' הקטנות לכך אשתארו אתוון דש\"מ בבחי' הקטנות באותיות קטנים ופי' אשתארו היינו מפני שאין המל' עולה בבחי' בינ' כדלי\"ת רבתי דבחי' לאה שעולה ומתייחדת במדות דבינה כנ\"ל בתיבת עד אך המל' דז\"א אינה עולה שם ונשארת למטה להיות ראש לשועלים ובפרט בבחי' מיעוט וקטנות כדי לברר רפ\"ח כו' כנ\"ל ולכך א' אשתארו אתוון ש\"מ אשתארו בבחי' הקטנות ועדיין פי' אשתארו לא מתיישב דמשמע דאשתארו עדיין למטה ולא עלו א\"כ גם העי\"ן היה למטה אלא שעלה למעלה והן אשתארו למטה כו' הענין הוא דכתיב תנו עוז לאלקים דהיינו לשם אלקים הוא בחי' שם ב\"ן המברר צריך עוז וסיוע מעליון (כמבואר במ\"א בענין הבא לטהר פי' לטהר את השם מסייעין אותו מבחי' מקיפי' דבינה שבאים לטהר כמו וזרקתי עליכם מים טהורים כו' וכל טהרה הוא בחי' הברורים וקדוש השם הוא מבחי' אור אבא כידוע) והוא מבחי' בינה שנק' אלקי' עלאה והיינו ע\"י בחי' ה\"ג מנצפ\"ך דאוזיפת אימא לברתא ובזה יתן עוז לאלקי' כמ\"ש חגרה בעוז מתניה כו' וכן ה' מלך כו' לבש ה' עוז כו' עוז לעמו יתן כו' ואמנ' עוז זה נמשך בבחי' מקיף בהעלם ומרחוק ולכך אע\"פ ששם ב\"ן מברר כו' העוז והסיוע העליון לברר הוא למעל' והיינו בבחי' ע' רברב' שעל' למעל' ואתוון ש\"מ אשתארו למט' לברר ברורי' כו' וד\"ל ולכך הוקשה לו עוד על מ\"ם זה מ\"ט לא סתימא פי' כי על בחי' המל' דז\"א יתכן שהוא בבחי' מ\"ם פתוחה דוקא להיותה בבחי' אותיות קטנות לברר ברורי' דרפ\"ח כנ\"ל אבל על בחי' העוז ממקיף דבינ' שהיא לעולם בבחי' מ\"ם סתומה כידוע ולזה מקשה מ\"ט לא סתימא ותירץ בגין דמ\"ם סתימא מלכא עלא' מ\"ם פתוחה מלכא תתא' וד\"ל ופי' השני כי עיקר הקושי' מ\"ט לא סתימ' הגם שהמ\"ם הזה באמצע התיבה לפי שהמ\"ם הזה גם בבחי' מל' דז\"א סתומה היא במקו' אחר והוא במ\"ש ויעש דוד שם שהוא במ\"ם סתומה דוקא אעפ\"י שהמל' הוא בבחי' מ\"ם פתוחה לעולם לפי שנק' פתח כידוע אך יש הפרש במל' בין בחי' ירידתה למטה מטה לברר ברורים דרפ\"ח וכה\"ג אז היא בבחי' מ\"ם פתוחה שנפתח השפע לכל גם לע' שרים דנוגה וכמ\"ש ומלכותו בכל משלה וכמשי\"ת אבל בעליית המל' למעלה מעלה בבחי' בינה עלמא דאתכסיי' ה' עלא' (ונק' תשוב' תשוב ה\"א לה\"א עלא') אז נא' כאמה בתה שגם מל' דז\"א בבחי' הגדלות דאור אימא ואז גם היא בבחי' מ\"ם סתומה כבינה עצמה (וכמילוי ה' ה\"ה) והיינו מ\"ש ויעש דוד שם שהוא"],[1700400279,"מדבר לאחר עליי' הברורים דרפ\"ח ע\"י שם ב\"ן דדוד למעלה כידוע דב\"ן עולה בס\"ג דבינה בשרש רפ\"ח כו' דעיקר השבירה הי' בס\"ג כמ\"ש כולו סג כו' ואז נא' א\"ח עט\"ב עטרת לשם מ\"ה בעלה כו' כידוע לכך נא' שם במ\"ם סתומה וכמשמעות הפשט דויעש דוד שם במלחמ' גדולות שנצח לאויבים רבים וקנה שם גדול כו' וכך ע\"י הברורי' לאהפכא חשוכא כו' לאכפייא לסט\"א אסתלק יקרא דקוב\"ה שהוא כתר שם טוב כמו מלך ב\"ו שקונה שם גדול כשכובש כל העול' ודוקא כשכובש הרחוקים מאד כו' (ולכך כתר ש\"ט דמשיח עולה ע\"ג) וזהו ג\"כ שם במ\"ם סתומה שהוא מלכא עלאה בחי' בינה כידוע דבינה נק' מלכא עלא' כמו אלקי' חיים ומלך עולם ומל' דז\"א נק' מלכא תתאה כו' ולזה הוקשה לו גם על בחי' מל' דז\"א למה אינו במ\"ם סתומה דמה שיורדת לברר למטה אינו אלא בליל' דוקא כמ\"ש ותקם בעוד לילה כו' דמצד זה יתכן שיהי' המל' בבחי' אותיו' קטנו' כנ\"ל אבל בעליי' המל' למעל' באצי' בבינה כמו ביחיד זו\"נ דק\"ש שעולין לאו\"א כו' כידוע בכונו' דשמע ישראל ה' אלקינו כו' שזו\"נ ה' אחד א\"ח דלי\"ת וה' אלקינו או\"א כו' ושם אינו מהראוי שיהי' בבחי' מ\"ם פתוחה שאינה מסתתרת אז בבי\"ע להיות משפיע למטה כלל (אך לפ\"ז יקשה גם על מה שהאותיות ש\"מ בקטנו' דהוא עצמו הטעם שיהיו האותיות גדולו' בגדלו' דבינ' כנ\"ל בדלי\"ת רבתי ולה לא יוקש' לו רק על המ\"ם פתוחה ומה דאשתארו אתוון ש\"מ בקטנו' לא קשה לו כלל ואפשר דקטנות האותיות אינו דוקא בירידת המל' למטה אלא גם דוקא בעלותה למעלה מצד בחי' בטול והתכללות תחתון לגבי העליון נעשה בבחי' הקטנות דוקא כמו א' זעירא דויקרא וכמו ואל משה אמר שלא סליק בשמא כלל כמ\"ש בזהר בכמה דוכתי (ומה שהדלי\"ת רבתי ולא נעשה בקטנות לפי שהמח' קרוב' יותר לערך דקו השכל משא\"כ אותיות הדבור דכלא חשיב בבינה וגם במדו' דז\"א כו' וכמו ודבר דבר כו') ואדרבה בירידתו למטה נעשה ראש לשועלים נעשה בגדלו' האותיו' כמו אדם דדברי הימים כידוע אך על המ\"ם פתוח' קשה לו משני טעמי' א' מצד בחי' המל' שהיא בבחי' בינה ועוד דמקיף דבינה עוז לאלקי' כנ\"ל) והנה התירוץ שתירץ בגין דמ\"ם סתומה מלכא עלא' כו' לכאורה אינו מובן כלל דזה עצמו עיקר הקושי' דמ\"ם סתומה היא בבינה שנק' מלכא עלאה ובחי' מל' דז\"א ג\"כ בשעת ק\"ש בבחי' יחוד עליון דאו\"א (או גם שאינה מתייחד' רק בז\"א אינו מ' פתוחה רק בירידתה למטה בבי\"ע ועוד שהרי אמרו עולה עמו כו') והענין יובן בהקדי' תחלה ההפרש הידוע בין מ\"ם פתוחה למ\"ם סתומה (כמ\"ש דלמרבה המשרה שבאמצע תיבה וסתומה כמ\"ש במ\"א) שמ\"ם פתוחה הפתיחו' שבה בין כף לו\"י שבה למטה מורה הגלוי לחוץ שכל פתיחה מורה היציא' לחוץ ובפרט כשהפתיחה למטה באות ולא בצד מצדדיו כפתיחת הבי\"ת והפ' וכה\"ג והוא הנק' מאמר פתוח שהשפע נפתח לכל ויורד למטה מטה להחיו' גם לחיצונים שעומדי' בחוץ לפתח העליון כמ\"ש לפתח חטאת רובץ כידוע משא\"כ מ\"ם הסתומה מכל צד מורה אור ושפע הגנוז ונעלם מהכל לא יקרב זר שם כלל לקבל יניקה להיותו סתום מכל צד בלי פתיחה כלל והוא הנק' מאמר סתום בבחי' עלמא דאתכסיא דבינה בבחי' פנימי' בינה שנק' עולם החירות חירות ממות כו' שאין שם שרש אחיזה ויניקה כלל לחיצוני' ונק' יין המשומר ממגע נכרי לפי שהחיצוני' לא יוכלו ליקרב שם גם בנגיעה להיותו סתום מכל צד ופנה באין מקום פתוח לחוץ כלל וזהו שא' כאן דמ\"ם סתומה מלכא עלאה בחי' פנימי' בינה בחי' יובלא עלאה שאין משם שרש לחיצוני' כלל ומ\"ם פתוחה מלכא תתאה בחי' מל' דאצי' בבי\"ע שנפתח שפע"],[1700400280,"משם לכל גם לחיצוני' וכמו ומלכותו בכל משלה וכן מלך אלקים על גויים כו' וכאשר המל' עולה עם הרפ\"ח נצוצין לשרשה בבינה הרי גם החיצוני' יכולי' לעלות עמה כי יש להם שרש במל' המברר אותם וכמ\"ש בזהר כמה אלקי' אחרי' דסלקין כו' ולזאת גם בעליית המל' היא במ\"ם פתוח' ואינה יכול' לעלות בהיכל בינ' שהיא מ\"ם סתומה להיות משומר ממגע נכרי מכל צד כו' ובזה מתורץ הקושי' למה לא נק' מ\"ם סתומה הגם שעולה המל' באצי' ואינה יורדת למטה כלל לפי שעולה עם רפ\"ח כו' והוא ברורי' דרפ\"ח כו' שעשתה טרף בלילה מעל' מ\"ן באצי' ובק\"ש עולה עמהם ואמנם לא תוכל לעלות עמהם במקום שאין משם לא שמץ יניקה ושרש לעה\"ד טו\"ר כו' וע\"כ א\"א להיות למל' בבחי' מ\"ם סתומה כאן בתיבת שמע דוקא לפי שש\"מ זה הוא ענין עליי' רפ\"ח בצרוף שם ב\"ן עצמו לאחר שמבררת אותם ועולה עמהם כנ\"ל אבל מ\"ש ויעש דוד שם נכתב במ\"ם סתומה שזהו לאחר תשלום כל הברורים דוקא שנהפך הרע לטוב כאלו לא הי' במציאת מעולם כמו לע\"ל דכתיב ואת רוח כו' ויבולע המות כו' שזהו כמו בחי' יובלא עלא' דפנימית בינה ממש שאין שם שרש לרע כל ואז נא' א\"ח עט\"ב דב\"ן נעשה בבחי' ס\"ג דבינ' ממש כמ\"ש כאמה בתה כב' ההי\"ן דשם הוי' כו' וכמו תיב' יהיה שהוא ה' אחרונ' שוה לה' ראשונה דשניהם שוין לקבל מיו\"ד כו' וז\"ש ביום ההוא יהיה שזהו למעלה משם הוי' דה\"א אחרונה מקבל מבחי' וי\"ו דז\"א כמ\"ש במ\"א וד\"ל וזהו שתירץ מ\"ם פתוחה מ\"ט לא סתימ' כמ\"ם דלמרבה המשרה כו' שהוא בפנימית בינה ולזה א' בגין דמ\"ם סתומה דלעתיד מלכא עלא' ונק' קרית מלך רב כמ\"ש בזהר והוא ירושלים של מעל' כידוע ומ\"ם פתוחה מלכא תתאה בחי' מל' דז\"א שגם בעלייתה היא עולה עם הברורי' כמו ורחל באה עם הצאן כי רועה היא כידוע וד\"ל:\n(עט) <b>עוד</b> שם בסוף המאמר דלעיל אתוון אתרנין אשתארו א\"ח כבוד אלקי' הסתר דבר כתיב אשכחנ' בספר' דרה\"מ סבא כל מאן דמייחד יחוד' דא בכל יומא חדוה זמינא לי' מלעילא מרזא דאתוון אילין ש\"מ מהאי סט' א\"ח מהאי סט' ומצרף אתוון למפרע שרי ובמישר סיים וסמין אשמ\"ח דכתיב אנכי אשמח בה' ממש דא יחודא קדישא ושפיר איהו והכי הוא בס' דחנוך ע\"כ והנה תחלה יש להבין חיבור תחלת המאמ' אשתארו אתוון ש\"מ עם סוף המאמ' הזה שאמ' אתוון אחרני' אשתארו א\"ח מה שייכו' יש זע\"ז דודאי ש\"מ דשמע מדבר בבחי' המל' כנ\"ל בענין ויעש דוד שם ובא\"ח דאחד מדבר בבחי' ז\"א כידוע ומה יש חבור ענין ביניהם בענין אשתארו אתוון ש\"מ בקטנות לגבי ע' רברבא לענין אשתארו אתוון דא\"ח בקטנות לגבי דלי\"ת רבתי דאחד דלכאורה הן ב' ענינים נבדלים זמ\"ז כו' ועוד יש להבין מ\"ש הביאור ע\"ז כבוד אלקי' הסתר דבר ולא א' זה על אשתארו אתוון דש\"מ שהוא בבחי' מל' שנק' אלקי' כו' והנה תחלה יש להבין בכללו' ענין זה המא' ובפרט במה ששיבח זה היחוד דחדוה זמינא לי' כו' דמשמע שזהו יחוד חדש ונפלא שלזאת חדוה זמינא לי' כמ\"ש הסימן אנכי אשמח כו' ויש להבין תחלה שרש ענין א\"ח דאחד כפי המבואר בס' הקבלה בכמה דוכתי שא\"ח הוא בחי' ט\"ס דז\"א וגם נק' אח והמל' נק' אחות כמו מי יתנך כאח לי שהמל' נק' אחותי אחות לאח זה והגם שזו\"נ נזכר תמיד בבחי' יחוד איש ואשתו כמבואר בשה\"ש אך בהיות זו\"נ בבחי' עיבור באימא שנקראו תאומי' בן ובת כידוע הרי המל' כלולה בז\"א בבחי' עשיראה דכולהו דהיינו בבחי' המל' דכל ספי' דז\"א כי ז\"א עצמו הוא בעל ט\"ס לבד (וגם כלי' פנימי' אמצעי' חיצון כל א' כלול מט' נגד חב\"ד חג\"ת נה\"י הרי טפ\"ט פ\"א"],[1700400281,"וג\"פ פ\"א רמ\"ג ועם ה\"ח המגדילי' רמ\"ח כמ\"ש בע\"ח בכמה דוכתי שז\"ש אתה סתר ראש תוך סוף דג' כלי' הנ\"ל) וענין בנין המל' ממל' דט\"ס דז\"א היינו שנבנה בפרצוף בפ\"ע מי\"ס שלימו' כמו מבחי' מל' שבחכמה דז\"א נעשה בחי' חכמ' שבמל' ומבחי' מל' דחסד דז\"א נעשה בחי' חסד שבמל' ועד\"ז כל בנין המל' במהות בפ\"ע כידוע וכמ\"ש ויבן ה' אלקי' את הצלע כו' וכידוע בענין הנסירה ואחר שנבנה פרצוף הנוק' מתייחדי' זו\"נ בבחי' יחוד איש ואשתו כמ\"ש לזא' יקר' אש' כו' ולא נק' בבחי' אח ואחותו רק בהיות' בבחי' עיבור תאומי' כנ\"ל כידוע כ\"ז בס' הקבלה וביאור כ\"ז מבואר בכמה דוכתי שהמדו' נק' ז\"א ויחוד ז\"א בנוק' הוא שפע המדו' בבחי' וי\"ו זעיר' דיעקב כמ\"ש הקול קול יעקב והוא המשכות הקול בדבור שהדבור הוא בחי' מקבל מן הקול שיוצא מהבל הלב ששם משכן המדו' ואין זה אלא כאשר יצא בנין המל' שהוא הדבור במהות בפ\"ע שנק' רוח ממללא ששם יש כל ע\"ס בשלימות בפ\"ע כמו חכמה שבדבור וחסד ונצח וכל אופני התכללות הע\"ס דז\"א הכל נמצא בדבור במהות נבדל בפ\"ע רק שמקבלים מע\"ס שבז\"א שהן מדו' שבלב עם המוחין שבהם כשהקול יוצא מן הלב אל הדבור בכל פרטי ההמשכות לדבור אז יש אור וחיות בדבור ואם אין אור ושפע המדו' יוצא לדבור הרי הדבור בלא חיות כלל אלא בחי' דומם כאותיות גשמיי' חומר בלא צורה וכידוע בזהר בכמה דוכתי ביחוד קול ודבור כלל ופרט כו' ולמעלה היינו בחי' יחוד יעקב ורחל והוא הנק' זווג זו\"נ כידוע וד\"ל והנה ידוע שיש עוד יחוד עליון מזה והוא שנק' יחוד יש\"ס ותבונה והיינו ענין הנ\"ל בע' רברבא ודלי\"ת רבתי דשמע ואחד שהוא ענין אותיות המח' שנק' מל' דתבונה שמלבשת לבחי' המדו' שבשכל שנק ז\"ת דבינה והוא ג\"כ ענין מדות שבחכמ' שנק' יש\"ס כו' (ובזהר נק' או\"א תתאין כמ\"ש ביאור זה במ\"א) וידוע שלא ישונה סדר היחודים האלה במדות שבשכל ומחשב' ובקול ודבור שנק' יחוד יש\"ס ותבונה ויחוד זו\"נ ע\"ד הזה לעולם דהיינו שלעולם היחוד תחלה במדות שבשכל עם המח' וכפי אופן יחודם ממש כך יהי' סדר היחוד של המדו' בדבור (וכנ\"ל בענין יב\"ש הוי היום כו' דג\"ש ראשונות הן מוחין שבמדו' שבשכל שמשפיעי' במח' ומשם נמשך ללב ומן הלב אל הדבור והיינו יושב ודן ויושב וזן כו' ולא ישונה זמ\"ז אפי' כקש\"י וכנ\"ל ומכ\"ש שלא יוחלף מעליון לתחתון כו' (רק יחוד או\"א עצמן שנק' או\"א עלאין דהיינו יחוד בג\"ר דאו\"א הנה זהו הנק' זווג תמידי דלא מתפרשין לעלמין והוא תמידי' השפע מאין דג\"ר דחכמ' עצמה להשגה דבינה בבחי' ג\"ר דבינה כמעיין הנובע כו' שזה למעלה עדיין מתולדו' המדו' להטות השכל לזכות או לחוב כו' כידוע ומה שנמשך מיחודם לתולדו' המדות שבשכל והמדות נמשכי' במח' זהו יחוד לפרקי' וכן יחוד קול ודבור) (אך יחוד יעקב ולאה או ישראל ולאה הוא יחוד דמדו' שבלב במחשבה כמו שאנו רואין שמה שאדם חפץ בלבו מהרהר מיד במחשבה שנק' הרהורי לבו זהו באותיות שבמחשבה היותר נמוך שלמטה ממחשבה ממחשבה עיונית שמלבשת למדות שבשכל הנק' מל' דתבונה שמתייחדת ביש\"ס וכמשי\"ת בסמוך) והנה כאן בתיבת שמע ובתיבת אחד שאותיות דש\"מ דשמע הוא מדבר בבחי' המל' ובא\"ח דאחד מדבר בבחי' ז\"א כנ\"ל הנה אנו רואי' שנשתנ' סדר שני היחודי' הנ\"ל מן הקצה לקצה דהיינו שאין סדר היחודים כמו שהן במקומם המדות שבשכל עם המחשבה והקול הבל הלב עם הדבור כנ\"ל אלא שנתהפך מן העליון לתחתון ומתחתון לעליון כו' דהנ' ודאי שכל תיבה כמו שהיא כלול בה היחוד דדכר ונוק' כמו שמע ש\"ס ע' הרי האותיות דש\"ס בבחי' המל' שעולה ש\"מ בס\"ה מן מספר רפ\"ח עם בחי' ב\"ן עצמו כנ\"ל עולה למעלה"],[1700400282,"מעלה מהכל והוא להתייחד בפ' רברבא שהן בחי' המדות שבשכל כנ\"ל והיינו תיבת שמע שם ע' בבחי' ז\"ת דבינ' או דחכמה ובתיבת אחד א\"ח דלי\"ת הרי מבואר למעלה דא\"ח הוא בחי' ט\"ס דז\"א וסד היחוד שלו לעולם לבא בבחי' ירידת ההמשכ' והשפעה לדבור שהוא יחוד הקול ודבור שנק' יחוד זו\"נ ומכאן משמע בפי' א\"ס דלי\"ת שא\"ח זה מתייח' בד' רבתי שהוא מל' דתבונ' שהיא למעלה בבחי' המחשבה שמלבשת למדות שבשכל כנ\"ל הרי נהפוך מעליון לתחתון ומתחתון לעליון בין מצד המשפיע בין מצד המקבל דהנ' בחי' המשפיע שהוא ע' רברב' דחו\"ב שלעול' יחודו' במל' דתבונה בדלי\"ת רבתי שזה עד כו' כנ\"ל עתה יורד הע' הזה להתייח' במדריג' שלמט' הימנו הרבה שהוא בחי' הדבור דהיינו ש\"מ דאחד ומצד המקבל הוא בחי' ש\"מ בחי' מל' זהו עלי' להתייחד לקבל ממדריגה העליון ביותר שהוא ז\"ת דבינה וכפי פי' דשמע שם ע' זהו עליי' המל' לבינה ובתיבת אחד א\"ח הוא בחי' ז\"א מתייחד במל' דתבונה הרי זהו בחי' ירידה למל' דתבונה שהוא המחשבה להתייחד במדו' שבלב שלמטה הימנה ולמדו' שבלב זהו בחי' עלי' להתייחד בבחי' ומדריגה עליונה הימנה שהוא המח' שנק' עלמא דאתכסיי' אשר מעולם הי' סדר יחודו לבא למטה בבחי' גלוי הדבור בעלמא דאתגליא שזהו יחוד קול ודבור כידוע ונמצא בתיבת שמע עליון נעשה תחתון מצד המשפיע שהוא הע' ותחתון נעשה עליון מצד המקבל שהוא ש\"מ ובתיבת אחד עליון נעשה תחתון מצד המקבל שהוא המח' שהי' בחי' מקבל למדריג' עליונה דמדות שבשכל ונעשה תחתון להיות בחי' מקבל ממדות שבלב ותחתון נעשה עליון מצד המשפיע שהן המדו' שבלב שעולה למעלה להשפיע במח' כנ\"ל וד\"ל (ודרך כלל ובתיבת שמע עולה ש\"מ שהוא המל' למעלה להתייחד בע' רבתי ובתיבת אחד עולה א\"ח שהוא ז\"א להתייחד בד' רבתי דמחשבה ואין זה נק' היפוך מעליון לתחתון כו' אלא שינוי במקבל ומשפיע דמל' נעשה מקבל למדו' דשכל וז\"א נעשה משפיע למל' דתבונה וממילא נק' עליי' תחתון לעליון ממל' לבינה ויריד' עליון לתחתון ממל' דתבונה בז\"א ויהי' איך שיהי' זהו היפוך סדר שני היחודי' הנ\"ל דיש\"ס ותבונה וזו\"ן מן הקצה כו' שלא כסדרן מעולם ועם זה יובן כללות המא' במה ששיבח לבחי' סדר יחוד החדש הזה דחדוה זמינא לי' כו' כמשי\"ת):\n(פ) <b>ובכל</b> זה יובן כללו' ענין המאמר במ\"ש אתוון אחרנין אשתאר א\"ח כבוד אלקי' הסתר דבר כתיב דהנה יש להבין בתוס' ביאור ענין היפוך סדר שני היחודי' הנ\"ל דלכאורה מה שמבואר למעלה בש\"מ דשמע שעולה בע' רברבא איך יוכל להיות עלי' לדבור בבינה וגם מה שמבואר למעלה ביריד' מל' דתבונה בז\"א שהוא המח' במדו' שבלב ג\"כ יש להבין איך יהי' זה דאם נאמ' עד\"מ במדו' שבלב האדם שאנו רואי' בחוש דמה שחפץ ומשתוקק בלבו מיד מהרהר במח' ונק' בשם הרהורי לבו הנה זהו הנק' יחוד יעקב ולאה כמו שהמדות שבלב נמשכי' בגלוי לדבור כך נמשכים בהעלם המח' להרהר מה שבלבו וכידוע דמח' ודבור נק' תרין אחתן לאה ורחל ויעקב בחי' משפיע לשניהם וזהו ב' מיני יחודים דיעקב ולאה ויעקב ורחל (בחול או ישראל ולאה דישראל ורחל בשבת) ואין כל חדש בזה כלל ומה שיבח זה ליחוד חדש כו' דודאי המח' מקבל תמיד ממדות שבלב ונגבלים אורות המדות שבלב בצרופי' שונים באותיות המח' בכל רגע צירוף אחר כנרא' בחוש שאין רגע בלא מחשב' והרהו' הלב שעול' ומתחד' תמיד כו' ועוד דזהו אינו נק' יריד' למח' כלל כי אותיות המח' הן רק בחי' לבוש נבדל וע\"י השפעו' האור וחיות מן המדות שבלב מקבלים אור וחיות גדול ובלעדם הן"],[1700400283,"בלא חיות כמו מחשבו' שאין לבו בהן שאינם כלים כאותיות הדבור בלא חיו' הלב כו' ועוד שבכאן משמע דיש עלי' לז\"א שהן במדות שבלב להתייחד במל' דתבונה ולפ\"ז אין זה בחי' עלי' כלל אך הענין הוא דמ\"ש אתוון אחרנין אשתארו א\"ח פי' אשתארו בבחי' הקטנות והן מדות דז\"א שבאי' אחר צמצום וקטנו' עצם המוחין שבראש כידוע דהתפעלות הלב הן בקטנות המוחין ולכך הן באותיות קטנים ואשתארו משמע שהד' רבתי והן אשתארו למטה בקטנות והענין הוא דד' רבתי זה אינו בחי' אותיו' המח' ממש שנק' לאה אלא הוא מל' דתבונה או מל' דבינ' עצמה שהוא הנק' אותיות השכל וההשגה שאינן אותיות גשמיי' ומוגבלים כאותיות המח' שיכולים להיות בלא שכל כלל כמחשבות של דברים בטלים לגמרי כו' אלא הן דוקא אותיות השכל וההשגה והוא ענין הגלוי של אופן ההשגה כשבא בעיון המחשבה הנק' מחשבת שכל או מחשבה עיונית שבו מלובש ההשגה עצמה כמו שאנו רואים שכל שכל וסברא אינה אלא היולית ועצם אור פשוט מופשט מבחי' מח' לגמרי גם לא במחשבת שכל בלתי נתפס בעיון המח' לחשוב אותו (שבלתי נתפס עדיין ברעיון המח' (בל\"א ע\"ש לייקט זיך ניט אין דער מחשבה או עש פאר נעמט ניט די מחשבה) וכאשר צריך לבא במחשבה עיונית זו זהו הנק' השפעה מעצם המדות שבשכל במל' דבינה או תבונה שלמעל' מהיות עדיין אותיות גשמיי' במחשבה וכידוע דלאה מקבלת ממל' דתבונה וענין קשר של תש\"ר הוא במל' דתבונה שבבחי' חיצוניות דאימא עלא' כו' כמשי\"ת) והנה המד' שבלב ודאי גם בבחי' קטנות מאד לגבי גדלו' מדות שבשכל ויכול להיות לפעמים שיעלו למעלה מן הקטנות אל הגדלו' שבשכל וכמו שאנו רואי' ע\"ד דוגמא מבחי' יחוד יעקב ולאה הנ\"ל שכאשר חפץ בלב מהרהר באותיות גשמיי' במחשבה כנ\"ל כך יכול להיות שהתפעלות יעלה בכלי השגת שכל שבמוח והוא כמו העוצר רוחו שבלב אם בהתפעלות חדוה או מרירות יעלה הכל לכלי המוח דבינה ושם יהיה התפעלות שלהם בהעלם שאז בלתי נגלה לזולתו שיש התפעלות בלבו כלום כמו באוי\"ר שכליי' שהן במוח הבינה דהיינו מה שמתפעל בפחד בלב מסתלק הפחד מן הלב לגמרי ועולה התפעלות זו ממש במוח להתפעל שם דוקא ונק' התפעלות הלב שבמוח (די הארץ איז אין שכל בהאלטון) ואז הסימן שיהיה המח' העיונית הנ\"ל בתוקף עוז ביותר כמו המפחד במוח שעיונו תמיד בזה בבלבול ורתיח' לא תנוח עיון המח' ולהיפך בשמחה ועונג שנתפעל בלב ועלה למוח גם הוא יבוא בעיון המח' שהוא ההגיון והוא למעלה עדיין מבחי' אותיות במחשבה הנק' הרהור עד אחר זמן מה שתנוח ההתפעלות מעט יהרהר הכל בצירופים שונים במחשבה שנק' לאה כו' (משא\"כ מדות שבשכל בעצם כמו המצאת שכל לזכות שבא דרך ירידה מלמעלה למטה לחשוב אותו במחשבה שכל הנ\"ל וכן להיפך לדין והוא כמו היושב ודן בשכל שזהו בישוב כו') והרי נק' עלי' למדות שבלב להיות מתייחדי' במל' דתבונה שעולי' מן הקטנו' אל הגדלות דד' רבתי הנ\"ל וכמו שמבואר למעלה דד' רבתי מלבשת לתנה\"י דבינה כך מלבשת לתנה\"י דז\"א שבבינה לאחר שעלה א\"ח דהיינו ט\"ס דז\"א למעלה כו' וזהו א\"ח דלי\"ת בבחי' משפיע ומקבל וזהו יחוד חדש שלא היה כזה מעולם דז\"א משפיע לדבור שנק' רחל או מחשבה שנק' לאה ולא לעיון מחשבת שכל שאינו אלא בחי' מקבל לעצם המדו' שבשכל כו' וזה היחוד נעלה הרבה מיחוד זו\"נ במקומן לפי שנשאר הכל בהעלם כח המחשבה ולא בא בגלוי למטה בדבור לעול' כמובן ממשל זה שמדו' שבלב עולין למוח שאינו מביאו לדבור כלל וכלל כמו לבא לפומא לא גלי בקץ משיח אלא העלה הדבר"],[1700400284,"לסתימות המחשבה שבבינה שאינו בא גם לצרופי אותיות שבמח' ומכ\"ש בדבור כו' וד\"ל ומעתה יש להבין גם בענין יחוד השני דשמע שם ע' איך יוכל להיות העלי' דדבור בבינה ומהו החידוש בו הנה ודאי שהדבור מקבל תמיד מן המדות שבלב ע\"י הקול שיוצא מן הבל הלב כנ\"ל שנק' יחוד יעקב ורחל ואין כל חדש בו שהוא תמיד כו' אך אנו רואי' שלפעמי' יוכל הדבור לעלות מעלה מעלה לקבל מעצם אור השכל שבמדו' דשכל אם להטות לזכות כו' כמו הטרוד בענין איזה מושכל שבמדות דתור' אם לאסור או להתיר ולא יוכל לכוין הדבר לאמיתתו עדיין לפסוק בדבר אסור או מותר הוא בא לבחי' השתיקה ששותק מלדבר מאומה עד שיוציא לאור האמת במדות שבשכל בטוב טעם בהשג' אזי מובן הדבור לפסוק אסור או מותר ועדיין לא ישיב לשואלו דבר בגלוי אלא מרחשין שפתיו בחשאי בלתי מרגיש בעצמו עדיין מה שמדבר לעוצם טרדת עיון השכל עד שנגרר אחריו כח הדבור וכמ\"ש במ\"א בענין צלותא בלחש וקולה לא ישמע גם בהעלם המחשבה כו' וזהו אדנטי שפתי תפתח אין מלה בלשוני כו' וזה יובן בענין עליי' המל' בחי' שם ב\"ן עם הברורים דרפ\"ח כו' שנק' ש\"מ כנ\"ל שעולה הכל למעל' בחשאי בלתי גלוי הדבור כלל אלא נגרר הדבור ונמשך אחר בחי' עיון השכל שבמדות דבינה הנק' ע' רברבא (כמו שמבואר במ\"א בענין משל לבת מלך שהריחה ציקי קדרה שהן ברורי' דרפ\"ח תאמר יש לה גנאי תאמר בדבור להעלותם גנאי לבת מלך כו' לא תאמר בדבור ותשתוק שאז עליית המל' בעצם החכמה יש לה צער מהעדר העונג שבברורי' דרפ\"ח כו' הביאו לה עבדיה שהן נשמות ומלאכי' מעלין מ\"ן מנוגה בחשאי בצלותא שבלחש כו') (ויש הפרש בין לחש לשתיקה לגמרי כמ\"ש במ\"א בענין והאיש משתאה לה מחריש כו' שזהו ההפרש בין ש\"ע לנפ\"א ובכאן מדבר בהעלאה דרפ\"ח עם ב\"ן שהוא בחשאי ובלחש ולא שתיקה לגמרי דבשתיקה לגמרי אמרו סייג לחכמה שתיקה שממשיך אור חדש בחכמה מאין כו' כמו מלה בסלע משתיקא בתרין פי שנים מדבור של שכל הראשון לפי שהשתיקה עולה בכח המשכיל ההיולי כו') ובכ\"ז יובן ענין חיבור תחלת המאמר בסופו במ\"ש תחלה אשתארו אתוון ש\"מ כו' אתוון אחרנין אשתארו א\"ח כבוד אלקים כו' דהנה מ\"ש כבוד אלקי' הסתר דבר הוא ביאור כללי לכללו' המאמר מראשו לסופו והוא לש\"מ וא\"ח דאשתארו בקטנו' והע' והד' רבר בין על זה אמר דהיינו דכתי' כבוק אלקי' כו' דהנ' ע\"פי כל הנ\"ל יובן היפוך סדר היחודי' ממל' לבינה בשמע ומז\"א למל' דתבונה באחד כ\"ז היא בחי' עלי' לזו\"נ לשניהם יחד ע\"י היפך היחודי' הנ\"ל כי הרי בחי' ז\"א עולה במל' דתבונה ומתייחד שם כנ\"ל והיינו א\"ח דלי\"ת כנ\"ל והמל' עול' בז\"ת דבבינה שנק' ע' רבתי בשמע כנ\"ל וז\"ש כבוד אלקי' הסתר דבר דהנה ידוע דהמל' נק' דבר כמו דבר מלך שלטון כו' כי בחי' גלוי הדבור נק' דבר שהוא בחי' יש כמו הלא דבר הוא כו' ועליית המל' למעלה נק' הסתר דבר שדבר המל' בא לבחי' ההסתר והעלם וזהו כבוד אלקי' שהוא בחי' כבודו של אלקי' הוא בבחי' המל' כשבא ועולה בבחי' הסתר דבר כו' כמו כל כבודה בת מלך פנימה כו' והיינו ענין עליי' הדבור שהוא המל' שבא כאן בב' יחודי' הנ\"ל לבחי' ההסתר באמצעות ב' טעמי' הא' בתיבת שמע הרי עלי' לעצמו' הדבור למעלה במדו' שבשכל להתייח' שם בבחי' ההעלם דבינה כנ\"ל אינו בא לגלוי כלל לעולם וזהו הסתר דבר דמל' בבינה שנק' מ\"ם סתומ' כנ\"ל וד\"ל והטע' השני לפי שאין לדבור משפיע כי המדו' שבלב עולין למוח הבינה בתיבת א\"ח דלי\"ת רבתי כנ\"ל שהוא בחי' ז\"א שתמיד משפיע למל' וכאן כבר עלה למעל' וכמו ועלה האיש כו' ונשאר"]]});
